    { key = "arcatraz_key_access", kind = "ITEM", title = "Arrange Arcatraz access: key-holder, rogue, and flying", optional = true, phases = { from = 1, to = false },
      item = { id = 31084, name = "Key to the Arcatraz", count = 1 },
      detail = "The Arcatraz is the north-eastern satellite of Tempest Keep in Netherstorm, portal at about 74.6, 57.6, floating above the ground, so you need Expert Riding (225) and a flying mount, Druid flight form, or a warlock summon once two flyers are inside. Its door is locked: any one party member holding the Key to the Arcatraz opens it, or a rogue with Lockpicking 350 picks it. The key is the reward of How to Break Into the Arcatraz from A'dal, which sends you for the Top Shard in The Botanica and the Bottom Shard in The Mechanar after the Consortium chain in Netherstorm. The Arcatraz portal itself requires level 68. Like the Shadow Labyrinth key, this is optional for you personally as long as someone in the group has it." },
    { key = "second_fragment_steamvault", kind = "ITEM", title = "Dive for the Second Key Fragment in The Steamvault", optional = false, phases = { from = 1, to = false }, consumedBy = "the_second_and_third_fragments",
      item = { id = 24487, name = "Second Key Fragment", count = 1 },
      inside = { instance = 545, heroic = false, boss = "Hydromancer Thespia", npcs = { 17797, 22891 } },
      places = {
        { role = "inside", name = "The Steamvault", instance = 545 },
      },
      detail = "The Steamvault is the middle pipe of Coilfang Reservoir under the lake in Zangarmarsh, left of the Serpentshrine Cavern entrance, between the Slave Pens (west, 48.9, 35.5) and the Underbog (east, 54.4, 34.4); dive at the reservoir at about 50.4, 40.8 and the portal is at about 50.2, 33.3. The Arcane Container lies at the bottom of the pool to the right of the path leading to Hydromancer Thespia, just before her room; one route is to turn right down the ramp into the pool and jump left into the water. Opening it spawns the Second Fragment Guardian, which you fight in or beside the water, so watch the breath bar and kill it quickly. Loot the Second Key Fragment from the guardian. Thespia does not need to die, and this and the Arcatraz fragment can be done in either order. Leaving the instance with the quest abandoned deletes the fragment." },
    { key = "third_fragment_arcatraz", kind = "ITEM", title = "Take the Third Key Fragment from The Arcatraz", optional = false, phases = { from = 1, to = false }, consumedBy = "the_second_and_third_fragments",
      item = { id = 24488, name = "Third Key Fragment", count = 1 },
      inside = { instance = 552, heroic = false, boss = "Zereketh the Unbound", npcs = { 20870, 22892 } },
      places = {
        { role = "inside", name = "The Arcatraz", instance = 552 },
      },
      detail = "Inside The Arcatraz, go past the staircase in front of you in Zereketh the Unbound's room and through a few guards into the first room beyond, the one with Negaton Screamers and Negaton Warp-Masters on the lower floor. The Arcane Container stands in the right-hand corner as you enter. Opening it spawns the Third Fragment Guardian, a level 70 elite; kill it and loot the Third Key Fragment. Zereketh can be skipped entirely, which makes this a very short run once the door is open. Everyone on the quest should loot before the group moves on." },
    { key = "the_second_and_third_fragments", kind = "QUEST", title = "Return both fragments to Khadgar", optional = false, phases = { from = 1, to = false }, questId = 9832, questName = "The Second and Third Fragments", impliedBy = { 9836, 9837, 9838 },
      places = {
        {
          role = "start",
          name = "Khadgar",
          npc = 18166,
          zone = "Shattrath City",
          map = 1955,
          x = 54.6,
          y = 44.2,
        },
        {
          role = "turnin",
          name = "Khadgar",
          npc = 18166,
          zone = "Shattrath City",
          map = 1955,
          x = 54.6,
          y = 44.2,
        },
      },
      detail = "With the Second and Third Key Fragments in your bags, hearth to Shattrath and hand them to Khadgar on the Terrace of Light. He fuses the three pieces into the Restored Apprentice's Key, gives it to you, and sends you to the Caverns of Time for The Master's Touch. The turn-in pays 350 Violet Eye reputation. Before you accept the next quest, make sure Return to Andormu is complete, or the Black Morass portal will not let you in." },
    { key = "the_masters_touch", kind = "QUEST", title = "Have Medivh enable the key after Aeonus falls", optional = false, phases = { from = 1, to = false }, questId = 9836, questName = "The Master's Touch", questItem = { id = 24489, name = "Restored Apprentice's Key", count = 1 }, impliedBy = { 9837, 9838 },
      inside = { instance = 269, heroic = false, boss = "Aeonus", npcs = { 17879, 17880, 17881, 15608 } },
      places = {
        {
          role = "start",
          name = "Khadgar",
          npc = 18166,
          zone = "Shattrath City",
          map = 1955,
          x = 54.6,
          y = 44.2,
        },
        { role = "turnin", name = "Medivh", npc = 15608, zone = "The Black Morass", instance = 269 },
        { role = "inside", name = "The Black Morass", instance = 269 },
      },
      detail = "The Black Morass is the south-western timeway at the bottom of the Caverns of Time, portal at about 57.1, 63.1 on the Tanaris map; it requires level 66 and Return to Andormu complete (see the Caverns of Time guide). Run the full Opening of the Dark Portal event: eighteen waves of rifts with Chrono Lord Deja at six, Temporus at twelve and Aeonus at eighteen, keeping Medivh alive throughout. When Aeonus dies Medivh finishes opening the portal and stays as a quest giver only briefly after the portal opens, so stand next to him as the last boss falls and turn in before leaving and talk to him straight away. He completes The Master's Touch, converts the Restored Apprentice's Key, and offers Return to Khadgar on the spot; accept it before leaving. Reward 350 Violet Eye reputation." },
    { key = "return_to_khadgar", kind = "QUEST", title = "Show Khadgar The Master's Key", optional = false, phases = { from = 1, to = false }, questId = 9837, questName = "Return to Khadgar", questItem = { id = 24490, name = "The Master's Key", count = 1 }, impliedBy = { 9838 },
      places = {
        { role = "start", name = "Medivh", npc = 15608, zone = "The Black Morass", instance = 269 },
        {
          role = "turnin",
          name = "Khadgar",
          npc = 18166,
          zone = "Shattrath City",
          map = 1955,
          x = 54.6,
          y = 44.2,
        },
      },
      detail = "Return to Khadgar on the Terrace of Light. He hands you The Master's Key, which goes to your keyring, and 500 Violet Eye reputation; the chain to this point has paid 2100 reputation in total. You are now attuned: the key opens the front gate of Karazhan in Deadwind Pass at about 46.6, 74.1 (there is also a side door at 46.5, 70.5), and one key-holder opening the gate lets the whole raid walk in. On Anniversary realms this completion also unlocks the raid for every other character on your Battle.net account. Khadgar offers The Violet Eye, a short courtesy quest back to Alturus." },
    { key = "the_violet_eye", kind = "QUEST", title = "Report back to Archmage Alturus", optional = true, phases = { from = 1, to = false }, questId = 9838, questName = "The Violet Eye",
      places = {
        {
          role = "start",
          name = "Khadgar",
          npc = 18166,
          zone = "Shattrath City",
          map = 1955,
          x = 54.6,
          y = 44.2,
        },
        {
          role = "turnin",
          name = "Archmage Alturus",
          npc = 17613,
          zone = "Deadwind Pass",
          map = 1430,
          x = 47,
          y = 75.5,
        },
      },
      detail = "Not required for entry. Khadgar asks you to tell Alturus the tower is open; the turn-in pays 75 Violet Eye reputation and unlocks the reputation chain inside Karazhan: Assessing the Situation (find Koren inside), Keanna's Log, A Demonic Presence and the Nightbane chain that ends with the Blackened Urn. Do it on your first trip to the raid since Alturus stands at the gate." },
    { key = "enter_karazhan", kind = "MANUAL", title = "Open the gate and enter Karazhan", optional = true, phases = { from = 1, to = false }, auto = { enteredInstance = 532, heroic = false },
      inside = { instance = 532, heroic = false },
      places = {
        { role = "inside", name = "Karazhan", instance = 532 },
      },
      detail = "Gather ten players, have a key-holder click the front gate of Karazhan at the foot of the tower in Deadwind Pass (about 46.6, 74.1) and zone in; the raid lockout is seven days. Attumen the Huntsman in the stables is the usual first pull. If you are an alt on an account that has already finished this chain you may be able to enter without the key under the Anniversary account-wide rule, but one Master's Key is still needed in the raid to open the gate." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "GRUUL_MAGTHERIDON", name = "Gruul and Magtheridon", title = "Gruul's Lair and Magtheridon's Lair",
  category = "RAID", order = 20, faction = "BOTH", gate = nil,
  phase = { introduced = 1, requiredUntil = false,
            note = "Neither raid has ever had a gate; since the Zul'Aman update every boss in both also drops Badges of Justice." },
  unlock = nil,
  accountWide = false, minLevel = 70, instance = 565, recurring = false,
