  unlocks = "Reaching level 70 is the only requirement; it opens both doors and lets you start every other raid attunement in this section.",
  steps = {
    { key = "reach_70", kind = "LEVEL", title = "Reach level 70", optional = false, level = 70, phases = { from = 1, to = false },
      detail = "Both raids are tuned for level 70 characters and every raid quest in this section requires level 70 to accept. Level 70 is the practical requirement for both. Once you are 70, pick up the heroic dungeon keys as you go, because the Serpentshrine and Tempest Keep chains both send you into heroics." },
    { key = "gruul_door", kind = "MANUAL", title = "Find the Gruul's Lair entrance", optional = false, phases = { from = 1, to = false }, auto = { enteredInstance = 565, heroic = false },
      inside = { instance = 565, heroic = false, boss = "Gruul the Dragonkiller", npcs = { 18831, 19044 } },
      places = {
        {
          role = "door",
          name = "Gruul's Lair",
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 68.7,
          y = 24.3,
          instance = 565,
        },
      },
      detail = "Gruul's Lair sits in the north east of Blade's Edge Mountains at roughly 68.7, 24.3, north of Ruuan Weald; fly or ride up the ramp into the cave. It is a two boss raid: High King Maulgar and his council, then Gruul the Dragonkiller. There is no door check at all, so simply zone in. The raid resets weekly." },
    { key = "magtheridon_door", kind = "MANUAL", title = "Find the Magtheridon's Lair entrance", optional = false, phases = { from = 1, to = false }, auto = { enteredInstance = 544, heroic = false },
      inside = { instance = 544, heroic = false, boss = "Magtheridon", npcs = { 17257 } },
      places = {
        {
          role = "door",
          name = "Magtheridon's Lair",
          zone = "Hellfire Peninsula",
          map = 1944,
          x = 46.6,
          y = 52.8,
          instance = 544,
        },
      },
      detail = "Magtheridon's Lair is inside Hellfire Citadel in Hellfire Peninsula at roughly 46.6, 52.8. Enter the citadel courtyard where the three dungeon portals are and go down to the bottom level on the western side; the raid portal is the one opposite the other three. It is a single boss raid with a weekly reset and no attunement of any kind. Magtheridon's Head drops for The Fall of Magtheridon, a separate Honor Hold or Thrallmar quest, and the kill itself is what Trial of the Naaru: Magtheridon counts." },
    { key = "kill_gruul", kind = "KILL", title = "Kill Gruul the Dragonkiller", optional = true, phases = { from = 1, to = false },
      inside = {
        instance = 565,
        heroic = false,
        boss = "Gruul the Dragonkiller",
        npcs = { 19044 },
        encounters = { 650 },
        last = true,
      },
      places = {
        { role = "inside", name = "Gruul's Lair", instance = 565 },
      },
      detail = "Optional here, but if you are working on Serpentshrine Cavern pick up The Cudgel of Kar'desh first so you can loot the Earthen Signet from Gruul on the same kill. Gruul is the second boss, after High King Maulgar. The signet is a quest item that every raid member on the quest can loot. See the Serpentshrine Cavern guide." },
    { key = "kill_magtheridon", kind = "KILL", title = "Kill Magtheridon", optional = true, phases = { from = 1, to = false },
      inside = {
        instance = 544,
        heroic = false,
        boss = "Magtheridon",
        npcs = { 17257 },
        encounters = { 651 },
        last = true,
      },
      places = {
        { role = "inside", name = "Magtheridon's Lair", instance = 544 },
      },
      detail = "Optional here, but Trial of the Naaru: Magtheridon requires you to be on the quest when Magtheridon dies, so do the three heroic trials first if you want the Tempest Key from this kill. The fight needs five players on the Manticron Cubes to interrupt Blast Nova. See the Tempest Keep guide." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "NIGHTBANE_SUMMON", name = "Nightbane", title = "Nightbane and the Blackened Urn",
