  alternatives = nil,
  summary = "Nightbane does not appear in Karazhan until someone uses the Blackened Urn on the Master's Terrace, and the urn is only handed out at the end of a nine quest Violet Eye chain that runs through Karazhan, Deadwind Pass, Area 52 and two heroic dungeons. Only one raid member needs the urn and it is kept after the quest, so most raids rely on a single urn holder. The Blazing Signet that Nightbane drops is half of the Serpentshrine Cavern attunement.",
  unlocks = "The Blackened Urn, which summons Nightbane in Karazhan as often as the lockout allows, plus three thousand Violet Eye reputation and an amethyst gem.",
  steps = {
    { key = "medivhs_journal", kind = "QUEST", title = "Take Medivh's Journal to Wravien in Karazhan", optional = false, phases = { from = 1, to = false }, questId = 9630, questName = "Medivh's Journal", impliedBy = { 9638, 9639, 9640, 9645, 9680, 9631, 9637, 9644 },
      inside = { instance = 532, heroic = false, boss = "The Curator", npcs = { 16813 } },
      places = {
