      },
      detail = "Archmage Alturus stands outside Karazhan at the Master's Cellar entrance in Deadwind Pass (47.0, 75.6); he offers this once you hold The Master's Key. Wravien is a friendly ghost in the Guardian's Library, the large hall after The Curator, so you need a Karazhan raid that has cleared that far. The mobs around him auto-clear about half an hour after the Shade of Aran dies, but a raid will normally just clear to him. Steps one to three are pure talking and can all be done in one visit." },
    { key = "in_good_hands", kind = "QUEST", title = "Speak to Gradav in the Guardian's Library", optional = false, phases = { from = 1, to = false }, questId = 9638, questName = "In Good Hands", impliedBy = { 9639, 9640, 9645, 9680, 9631, 9637, 9644 },
