        { role = "turnin", name = "Gradav", npc = 16814, zone = "Karazhan", instance = 532 },
        { role = "inside", name = "Karazhan", instance = 532 },
      },
      detail = "Wravien sends you a few steps along the library to Gradav, another ghostly scholar. Hand in and accept the next quest immediately." },
    { key = "kamsis", kind = "QUEST", title = "Speak to Kamsis in the Guardian's Library", optional = false, phases = { from = 1, to = false }, questId = 9639, questName = "Kamsis", impliedBy = { 9640, 9645, 9680, 9631, 9637, 9644 },
