      },
      detail = "Gradav passes you to Kamsis, who stands in the same library hall. She is the one who actually sends you after the Shade of Aran, so accept her follow up before the raid pulls him." },
    { key = "shade_of_aran", kind = "QUEST", title = "Loot Medivh's Journal from the Shade of Aran", optional = false, phases = { from = 1, to = false }, questId = 9640, questName = "The Shade of Aran", questItem = { id = 23933, name = "Medivh's Journal", count = 1 }, impliedBy = { 9645, 9680, 9631, 9637, 9644 },
      inside = { instance = 532, heroic = false, boss = "Shade of Aran", npcs = { 16524 } },
      places = {
