      detail = "Kill the Shade of Aran in the library above Kamsis and loot Medivh's Journal from his corpse; it is a quest item so everyone on the quest can take one. Stand still during Flame Wreath, run out of Arcane Explosion, and have the raid stack and drink during his mana drain phase. Return the journal to Kamsis." },
    { key = "masters_terrace", kind = "QUEST", title = "Read the journal on the Master's Terrace", optional = false, phases = { from = 1, to = false }, questId = 9645, questName = "The Master's Terrace", impliedBy = { 9680, 9631, 9637, 9644 },
      inside = { instance = 532, heroic = false, boss = "Shade of Aran", npcs = { 16815 } },
      places = {
        { role = "start", name = "Kamsis", npc = 16815, zone = "Karazhan", instance = 532 },
        {
          role = "turnin",
          name = "Archmage Alturus",
          npc = 17613,
          zone = "Deadwind Pass",
          map = 1430,
          x = 47,
          y = 75.6,
        },
        { role = "inside", name = "Karazhan", instance = 532 },
