    { key = "digging_up_the_past", kind = "QUEST", title = "Retrieve the Charred Bone Fragment", optional = false, phases = { from = 1, to = false }, questId = 9680, questName = "Digging Up the Past", impliedBy = { 9631, 9637, 9644 },
      places = {
        {
          role = "start",
          name = "Archmage Alturus",
          npc = 17613,
          zone = "Deadwind Pass",
          map = 1430,
          x = 47,
