          npc = 17613,
          zone = "Deadwind Pass",
          map = 1430,
          x = 47,
          y = 75.6,
        },
      },
      detail = "A solo errand that cannot be completed while in a raid group, so leave the raid first. The Charred Bone Fragment lies on the ground against the mountainside directly behind the Karazhan meeting stone (about 45, 79 in Deadwind Pass); it respawns in roughly seven minutes if someone else just took it. Bring it straight back to Alturus." },
    { key = "colleagues_aid", kind = "QUEST", title = "Take the fragment to Kalynna Lathred in Area 52", optional = false, phases = { from = 1, to = false }, questId = 9631, questName = "A Colleague's Aid", impliedBy = { 9637, 9644 },
      places = {
