          map = 1953,
          x = 32.2,
          y = 63.6,
        },
      },
      detail = "Fly to Area 52 in Netherstorm. Kalynna Lathred stands at 32.2, 63.6 inside the town. Hand in and take her heroic request." },
    { key = "kalynnas_request", kind = "QUEST", title = "Loot the two books from heroic Nethekurse and Syth", optional = false, phases = { from = 1, to = false }, questId = 9637, questName = "Kalynna's Request", questItem = { id = 25462, name = "Tome of Dusk", count = 1 }, impliedBy = { 9644 },
      inside = { instance = 540, heroic = true, boss = "Grand Warlock Nethekurse", npcs = { 16807 } },
      questItems = { { id = 25462, name = "Tome of Dusk" }, { id = 25461, name = "Book of Forgotten Names" } },
