          name = "Kalynna Lathred",
          npc = 17636,
          zone = "Netherstorm",
          map = 1953,
          x = 32.2,
          y = 63.6,
        },
        { role = "inside", name = "The Shattered Halls", instance = 540 },
      },
      detail = "Two heroic dungeon drops, in either order: the Tome of Dusk from Grand Warlock Nethekurse, first boss of heroic Shattered Halls (Flamewrought Key, Honor Hold or Thrallmar), and the Book of Forgotten Names from Darkweaver Syth, first boss of heroic Sethekk Halls (Auchenai Key, Lower City). Both are quest items that every group member on the quest can loot. On Anniversary the heroic keys cost Honored since 22 October 2026 (Revered before that), and a Revered character can buy a Communal key for alts." },
    { key = "nightbane", kind = "QUEST", title = "Summon and kill Nightbane with the urn", optional = false, phases = { from = 1, to = false }, questId = 9644, questName = "Nightbane", questItem = { id = 24140, name = "Blackened Urn", count = 1 },
