    { key = "reservoir_key", kind = "ITEM", title = "Get the Reservoir Key for heroic Coilfang", optional = false, phases = { from = 2, to = 2 }, needsStanding = { factionId = 942, standing = 6, factionName = "Cenarion Expedition" },
      item = { id = 30623, name = "Reservoir Key", count = 1 },
      detail = "Skar'this only exists in the heroic version of the Slave Pens, so you need the Reservoir Key from the Cenarion Expedition quartermaster at the Cenarion Refuge in Zangarmarsh. On Anniversary the quartermaster sells it at Honored since the 22 October 2026 update (Blizzard: 'The reputation requirement to purchase Heroic dungeon keys has been reduced to Honored'); note the item's own tooltip in the Anniversary data still reads 'Requires Cenarion Expedition - Revered', so do not treat a Revered tooltip as proof the vendor requirement is unchanged. A Revered character can also buy a Communal Reservoir Key for alts, which works from Friendly. One keyed player opens the heroic for the whole group." },
    { key = "mark_of_vashj", kind = "QUEST", title = "Accept and hand in The Mark of Vashj to Skar'this", optional = true, phases = { from = 2, to = 2 }, questId = 10900, questName = "The Mark of Vashj",
      inside = { instance = 547, heroic = true, boss = "Mennu the Betrayer", npcs = { 22421, 17941 } },
      places = {
        { role = "start", name = "Skar'this the Heretic", npc = 22421, zone = "The Slave Pens", instance = 547 },
        { role = "turnin", name = "Skar'this the Heretic", npc = 22421, zone = "The Slave Pens", instance = 547 },
        { role = "inside", name = "The Slave Pens", instance = 547 },
      },
      detail = "Inside heroic Slave Pens clear past Mennu the Betrayer; Skar'this is chained in a cage shortly before Rokmar the Crackler. Guides describe The Mark of Vashj as an instant hand in that unlocks The Cudgel of Kar'desh, so accept it and turn it straight back in. If the Cudgel is already offered to you, skip this." },
    { key = "accept_cudgel", kind = "QUEST", title = "Accept The Cudgel of Kar'desh from Skar'this", optional = false, accept = true, phases = { from = 2, to = 2 }, questId = 10901, questName = "The Cudgel of Kar'desh",
      inside = { instance = 547, heroic = true, boss = "Mennu the Betrayer", npcs = { 22421 } },
      places = {
        { role = "start", name = "Skar'this the Heretic", npc = 22421, zone = "The Slave Pens", instance = 547 },
        { role = "turnin", name = "Skar'this the Heretic", npc = 22421, zone = "The Slave Pens", instance = 547 },
        { role = "inside", name = "The Slave Pens", instance = 547 },
      },
      detail = "Pick up the quest before your Gruul and Karazhan raids, because both signets only drop for players who have it in their log. The quest text says Skar'this in the heroic Slave Pens wants the Earthen Signet and the Blazing Signet. Both signets can be collected in either order." },
    { key = "earthen_signet", kind = "ITEM", title = "Loot the Earthen Signet from Gruul", optional = false, phases = { from = 2, to = 2 }, consumedBy = "turn_in_cudgel",
      item = { id = 31750, name = "Earthen Signet", count = 1 },
      inside = { instance = 565, heroic = false, boss = "Gruul the Dragonkiller", npcs = { 19044 } },
      places = {
        { role = "inside", name = "Gruul's Lair", instance = 565 },
      },
      detail = "Kill Gruul the Dragonkiller, the second boss of Gruul's Lair in Blade's Edge Mountains. The Earthen Signet is a quest item: every raid member on The Cudgel of Kar'desh can loot one from the corpse. Ask the raid leader to leave the corpse open until everyone has looted." },
    { key = "blazing_signet", kind = "ITEM", title = "Loot the Blazing Signet from Nightbane", optional = false, phases = { from = 2, to = 2 }, consumedBy = "turn_in_cudgel",
      item = { id = 31751, name = "Blazing Signet", count = 1 },
      inside = { instance = 532, heroic = false, boss = "Nightbane", npcs = { 17225 } },
      places = {
        { role = "inside", name = "Karazhan", instance = 532 },
      },
      detail = "Nightbane must be summoned on the Master's Terrace by a raid member holding the Blackened Urn (see Nightbane). He is an optional Karazhan boss with a ground phase and a flying phase of Rain of Bones and Smoking Blast; tanks pick up the skeletons during the air phase. The Blazing Signet is a quest item lootable by everyone on the quest." },
    { key = "turn_in_cudgel", kind = "QUEST", title = "Return both signets to Skar'this in heroic Slave Pens", optional = false, phases = { from = 2, to = 2 }, questId = 10901, questName = "The Cudgel of Kar'desh",
      inside = { instance = 547, heroic = true, boss = "Mennu the Betrayer", npcs = { 22421 } },
      places = {
        { role = "start", name = "Skar'this the Heretic", npc = 22421, zone = "The Slave Pens", instance = 547 },
        { role = "turnin", name = "Skar'this the Heretic", npc = 22421, zone = "The Slave Pens", instance = 547 },
        { role = "inside", name = "The Slave Pens", instance = 547 },
      },
      detail = "Go back into heroic Slave Pens, clear to the cage again and hand in. Completing this quest is the Serpentshrine Cavern attunement flag; there is no key item. If you have also finished Trial of the Naaru: Magtheridon you receive the title Champion of the Naaru. The raid entrance is in Coilfang Reservoir, Zangarmarsh, around 50.4, 40.9: swim down the central drain and take the lift up to the Serpentshrine portal." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "TK_ATTUNEMENT", name = "Tempest Keep", title = "Tempest Keep: The Tempest Key",
  category = "RAID", order = 50, faction = "BOTH", gate = "TK",
  phase = { introduced = 2, requiredUntil = 3,
            note = "Not needed since Phase 3 (27 Aug 2026): Tempest Keep opens without it. The trials still exist and still count towards Champion of the Naaru." },
  unlock = nil,
  accountWide = true, minLevel = 70, instance = 550, recurring = false,
  prerequisites = { { guide = "GRUUL_MAGTHERIDON", hard = true } },
  alternatives = nil,
  summary = "The Eye was gated by The Tempest Key, a key item A'dal awards after four Trials of the Naaru: a timed run of heroic Shattered Halls, trophies from heroic Steamvault and heroic Shadow Labyrinth, rescuing Millhouse Manastorm in heroic Arcatraz, and finally killing Magtheridon. Before Khadgar will even give you the opening quest you must finish the long Cipher of Damnation chain in Shadowmoon Valley. On Anniversary the gate was lifted at the start of Phase 3, but the chain still awards the key and counts towards Champion of the Naaru.",
  unlocks = "The Tempest Key item that opens The Eye while the gate exists, and together with The Cudgel of Kar'desh the title Champion of the Naaru.",
  steps = {
    { key = "hand_of_guldan", kind = "QUEST", title = "Start the Cipher of Damnation: The Hand of Gul'dan", optional = false, phases = { from = 2, to = 2 }, questId = { A = 10680, H = 10681 }, questName = "The Hand of Gul'dan",
      places = {
        {
