          name = "Earthmender Torlok",
          npc = 21024,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 42.2,
          y = 45.1,
        },
      },
      detail = "Alliance take The Hand of Gul'dan from Earthmender Sophurus at Wildhammer Stronghold (36.4, 57.0); Horde take 10681 from Earthmender Splinthoof in Shadowmoon Village (28.5, 26.6). Both send you to Earthmender Torlok at the Altar of Damnation (42.2, 45.1), who runs the first part of the chain. From here the chain is identical for both factions." },
    { key = "enraged_spirits", kind = "QUEST", title = "Capture the enraged fire, earth, water and air spirits", optional = false, phases = { from = 2, to = 2 }, questId = 10481, questIds = { 10458, 10480, 10481 }, questMode = "CHAIN", questName = "Enraged Spirits of Air",
      places = {
        {
          role = "start",
          name = "Earthmender Torlok",
          npc = 21024,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 42.2,
          y = 45.1,
        },
        {
          role = "turnin",
          name = "Earthmender Torlok",
          npc = 21024,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 42.2,
          y = 45.1,
        },
      },
      detail = "Three quests in a row from Torlok: Enraged Spirits of Fire and Earth, Enraged Spirits of Water and Enraged Spirits of Air. Drop the Totem of Spirits and kill the enraged elementals next to it so their souls are captured: fire and earth spirits around 46 to 52, 42 to 54; water spirits in the north around 45 to 52, 24 to 34; air spirits in the south east around 59 to 65, 54 to 70. Only kills made beside the totem count." },
    { key = "oronok_lessons", kind = "QUEST", title = "Help Oronok Torn-heart and learn the Cipher's history", optional = false, phases = { from = 2, to = 2 }, questId = 10519, questIds = { 10513, 10514, 10515, 10519 }, questMode = "CHAIN", questName = "The Cipher of Damnation - Truth and History",
      places = {
        {
          role = "start",
          name = "Earthmender Torlok",
          npc = 21024,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 42.2,
          y = 45.1,
        },
        {
          role = "turnin",
          name = "Oronok Torn-heart",
          npc = 21183,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 53.9,
          y = 23.5,
        },
      },
      detail = "Torlok sends you to Oronok Torn-heart at his farm (53.9, 23.5) with Oronok Torn-heart. Oronok then has you dig up ten Shadowmoon Tubers with his boar whistle without killing the felboars (I Was A Lot Of Things), smash ten Ravenous Flayer Eggs nearby while avoiding the elite matriarch (A Lesson Learned) and listen to his story (Truth and History). After that he gives three quests at once, one for each of his sons." },
    { key = "gromtor_charge", kind = "QUEST", title = "Recover the first Cipher fragment with Grom'tor", optional = false, phases = { from = 2, to = 2 }, questId = 10523, questIds = { 10521, 10522, 10523 }, questMode = "CHAIN", questName = "The Cipher of Damnation - The First Fragment Recovered",
      places = {
        {
          role = "start",
          name = "Oronok Torn-heart",
          npc = 21183,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 53.9,
          y = 23.5,
        },
        {
          role = "turnin",
          name = "Oronok Torn-heart",
          npc = 21183,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 53.9,
          y = 23.5,
        },
      },
      detail = "Grom'tor, Son of Oronok waits at 44.6, 23.6. His charge is to kill Shadowmoon Darkweavers and Burning Legion mobs around 45 to 48, 26 to 32 until the First Fragment of the Cipher drops. Return it to Oronok with The First Fragment Recovered. The three sons' sub chains can be done in any order." },
    { key = "artor_charge", kind = "QUEST", title = "Recover the second Cipher fragment with Ar'tor's spirit", optional = false, phases = { from = 2, to = 2 }, questId = 10541, questIds = { 10527, 10528, 10537, 10540, 10541 }, questMode = "CHAIN", questName = "The Cipher of Damnation - The Second Fragment Recovered",
      places = {
        {
          role = "start",
          name = "Oronok Torn-heart",
          npc = 21183,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 53.9,
          y = 23.5,
        },
        {
          role = "turnin",
          name = "Oronok Torn-heart",
          npc = 21183,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 53.9,
          y = 23.5,
        },
      },
      detail = "Ar'tor, Son of Oronok is at 29.6, 50.4 on the western side of the valley. Free him with a Crystalline Key (Demonic Crystal Prisons), then talk to the Spirit of Ar'tor for Lohn'goron, Bow of the Torn-heart, a drop from the mobs around 27 to 32, 50 to 57. Ar'tor's Charge has the spirit follow you south east until it summons Veneratus the Many, who carries the Second Fragment; bring it back to Oronok with 10541." },
    { key = "borak_charge", kind = "QUEST", title = "Recover the third Cipher fragment with Borak", optional = false, phases = { from = 2, to = 2 }, questId = 10579, questIds = { 10546, 10547, 10550, 10570, 10576, 10577, 10578, 10579 }, questMode = "CHAIN", questName = "The Cipher of Damnation - The Third Fragment Recovered",
      places = {
        {
          role = "start",
          name = "Oronok Torn-heart",
          npc = 21183,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 53.9,
          y = 23.5,
        },
        {
          role = "turnin",
          name = "Oronok Torn-heart",
          npc = 21183,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 53.9,
          y = 23.5,
        },
      },
      detail = "Borak, Son of Oronok sits at 47.6, 57.2. His part is the longest: a Rotten Arakkoa Egg taken to Tobias the Filth Gorger in Shattrath's Lower City (63.9, 70.0), The Bundle of Bloodthistle, To Catch A Thistlehead at the bridge, six Eclipsion Armor pieces (The Shadowmoon Shuffle), delivering Illidan's message in disguise to Grand Commander Ruusk, and finally Borak's Charge against Ruul the Darkener, a hard hitting elite best done with a group. Return the Third Fragment to Oronok." },
    { key = "cipher_of_damnation", kind = "QUEST", title = "Summon and defeat Cyrukh the Firelord", optional = false, phases = { from = 2, to = 2 }, questId = 10588, questName = "The Cipher of Damnation",
      places = {
        {
          role = "start",
          name = "Oronok Torn-heart",
          npc = 21183,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 53.9,
          y = 23.5,
        },
        {
          role = "turnin",
          name = "Earthmender Torlok",
          npc = 21024,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 42.2,
          y = 45.1,
        },
      },
      detail = "With all three fragments handed in, Oronok gives The Cipher of Damnation. Go to the Altar of Damnation (43.2, 44.8) and channel the Cipher for twenty seconds to summon Cyrukh the Firelord, a 369k health elemental; Oronok's sons and the earthmenders fight beside you, but bring a full group with a tank and healer. Hand in to Torlok next to the altar. Khadgar in Shattrath will only offer The Tempest Key once this is complete." },
    { key = "tempest_key_quest", kind = "QUEST", title = "Take The Tempest Key from Khadgar to A'dal", optional = false, phases = { from = 2, to = 2 }, questId = 10883, questName = "The Tempest Key",
      places = {
        {
          role = "start",
          name = "Khadgar",
          npc = 18166,
          zone = "Shattrath City",
          map = 1955,
          x = 54.8,
          y = 44.3,
        },
        { role = "turnin", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.7 },
      },
      detail = "Khadgar stands beside A'dal on the Terrace of Light in Shattrath (54.8, 44.3). Accept The Tempest Key and walk it over to A'dal (54.0, 44.7). A'dal then offers the three heroic trials at once: Mercy, Strength and Tenacity. They can be done in any order and all three must be handed in before the Magtheridon trial appears." },
    { key = "trial_mercy", kind = "ITEM", title = "Trial of Mercy: beat the heroic Shattered Halls timer", optional = false, phases = { from = 2, to = 2 }, questId = 10884, questName = "Trial of the Naaru: Mercy",
      item = { id = 31716, name = "Unused Axe of the Executioner", count = 1 },
      inside = { instance = 540, heroic = true, boss = "Shattered Hand Executioner", npcs = { 17301, 16807, 16808 } },
      places = {
        { role = "start", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.7 },
        { role = "turnin", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.7 },
        { role = "inside", name = "The Shattered Halls", instance = 540 },
      },
      detail = "Heroic Shattered Halls needs the Flamewrought Key (Honor Hold or Thrallmar). When Grand Warlock Nethekurse dies the group gains the Kargath's Executioner debuff, a 55 minute timer, and Kargath yells as he executes the three prisoners one by one as it runs down. The Shattered Hand Executioner appears only on heroic, standing with the prisoners in the Hall of Blades just before Warchief Kargath Bladefist; kill him before the timer ends and loot the Unused Axe of the Executioner (one per player on the quest). You can still get the axe if a prisoner or two have already died, so keep going even if the pace slips. Skip Warbringer O'mrogg's trash where you can and use crowd control on the legionnaire packs." },
    { key = "trial_strength_trident", kind = "ITEM", title = "Trial of Strength: Kalithresh's Trident, heroic Steamvault", optional = false, phases = { from = 2, to = 2 }, questId = 10885, questName = "Trial of the Naaru: Strength",
      item = { id = 31721, name = "Kalithresh's Trident", count = 1 },
      inside = { instance = 545, heroic = true, boss = "Warlord Kalithresh", npcs = { 17798 } },
      places = {
        { role = "start", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.7 },
        { role = "turnin", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.7 },
        { role = "inside", name = "The Steamvault", instance = 545 },
      },
      detail = "Trial of the Naaru: Strength wants two trophies, collected in either order; this is the first. Heroic Steamvault (Reservoir Key, Cenarion Expedition) ends with Warlord Kalithresh. Break the distillers he channels on, or he gains Warlord's Rage; on heroic the spite waves hit hard, so the group should stand spread. The trident is a quest item every group member on the quest can loot." },
    { key = "trial_strength_essence", kind = "ITEM", title = "Trial of Strength: Murmur's Essence, heroic Shadow Labyrinth", optional = false, phases = { from = 2, to = 2 }, questId = 10885, questName = "Trial of the Naaru: Strength",
      item = { id = 31722, name = "Murmur's Essence", count = 1 },
      inside = { instance = 555, heroic = true, boss = "Murmur", npcs = { 18708 } },
      places = {
        { role = "start", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.7 },
        { role = "turnin", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.7 },
        { role = "inside", name = "Shadow Labyrinth", instance = 555 },
      },
      detail = "The second Strength trophy comes from Murmur, the final boss of heroic Shadow Labyrinth in Auchindoun (Auchenai Key, Lower City). Run out when Sonic Boom is cast and keep the player with Murmur's Touch away from the group. Loot Murmur's Essence, then hand Strength in to A'dal once you have both items." },
    { key = "trial_tenacity", kind = "QUEST", title = "Trial of Tenacity: keep Millhouse Manastorm alive", optional = false, phases = { from = 2, to = 2 }, questId = 10886, questName = "Trial of the Naaru: Tenacity",
      inside = { instance = 552, heroic = true, boss = "Harbinger Skyriss", npcs = { 20912, 20977 } },
      places = {
        { role = "start", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.7 },
        { role = "turnin", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.7 },
        { role = "inside", name = "The Arcatraz", instance = 552 },
      },
      detail = "Heroic Arcatraz needs the Warpforged Key (The Sha'tar). In the final encounter Warden Mellichar opens the cells one by one; Millhouse Manastorm is released from the second cell and fights beside you against the remaining prisoners and Harbinger Skyriss. The objective Millhouse Manastorm Rescued is credited when Skyriss dies with Millhouse still alive, so a healer should keep him topped up and tanks should peel adds that turn on him. If he dies you must reset the instance and try again." },
    { key = "trial_magtheridon", kind = "KILL", title = "Trial of Magtheridon: slay Magtheridon and claim the key", optional = false, phases = { from = 2, to = 2 }, questId = 10888, questName = "Trial of the Naaru: Magtheridon",
      item = { id = 31704, name = "The Tempest Key", count = 1 },
      inside = {
        instance = 544,
        heroic = false,
        boss = "Magtheridon",
        npcs = { 17257 },
        encounters = { 651 },
        last = true,
      },
      places = {
        { role = "start", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.7 },
        { role = "turnin", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.7 },
        { role = "inside", name = "Magtheridon's Lair", instance = 544 },
      },
      detail = "After Mercy, Strength and Tenacity are all handed in, A'dal offers Trial of the Naaru: Magtheridon; the objective is simply Magtheridon slain, so you must be on the quest when he dies. Kill him in Magtheridon's Lair under Hellfire Citadel (five players click the Manticron Cubes to stop each Blast Nova). Return to A'dal for The Tempest Key item, which goes in your keyring and opens The Eye in Netherstorm (entrance about 73.7, 63.7). If you have also completed The Cudgel of Kar'desh you receive the title Champion of the Naaru." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "HYJAL_ATTUNEMENT", name = "Mount Hyjal", title = "Mount Hyjal: The Vials of Eternity",
  category = "RAID", order = 60, faction = "BOTH", gate = "HYJAL",
  phase = { introduced = 3, requiredUntil = 4,
            note = "Not needed since Phase 4 (22 Oct 2026): Mount Hyjal opens without it. The Vials of Eternity still exist and still pay Scale of the Sands reputation." },
  unlock = nil,
  accountWide = true, minLevel = 70, instance = 534, recurring = false,
  prerequisites = { { guide = "SSC_ATTUNEMENT", hard = false }, { guide = "TK_ATTUNEMENT", hard = false } },
  alternatives = nil,
  summary = "The Battle for Mount Hyjal was gated by one quest from Soridormi in the Caverns of Time: bring back the vial remnants carried by Lady Vashj, last boss of Serpentshrine Cavern, and Kael'thas Sunstrider, last boss of The Eye. In practice this means your guild must have cleared both Phase 2 raids. On Anniversary the gate was removed with the 22 October 2026 update, but the quest still opens the Scale of the Sands reputation and its Band of Eternity rings, and it is half of the Hand of A'dal title.",
  unlocks = "Entry to Hyjal Summit while the gate exists, three thousand Scale of the Sands reputation, access to the Band of Eternity ring line from Soridormi, and together with A Distraction for Akama the title Hand of A'dal.",
  steps = {
    { key = "accept_vials", kind = "QUEST", title = "Accept The Vials of Eternity from Soridormi", optional = false, accept = true, phases = { from = 3, to = 3 }, questId = 10445, questName = "The Vials of Eternity",
      places = {
        { role = "start", name = "Soridormi", npc = 19935, zone = "Tanaris", map = 1446, x = 58.9, y = 54.2 },
        { role = "turnin", name = "Soridormi", npc = 19935, zone = "Tanaris", map = 1446, x = 58.9, y = 54.2 },
      },
      detail = "Enter the Caverns of Time in eastern Tanaris (cave mouth around 65.7, 49.8) and follow the tunnel down to the main cavern. Soridormi, the bronze dragon consort, patrols a short loop near 58.9, 54.2 on the Tanaris map; Arazmodu can also start the quest. The quest requires level 70 and no reputation. Take it before your raids kill Vashj or Kael'thas, since the remnants only drop for players with the quest." },
    { key = "vashj_remnant", kind = "ITEM", title = "Loot Vashj's Vial Remnant from Lady Vashj", optional = false, phases = { from = 3, to = 3 }, consumedBy = "turn_in_vials",
      item = { id = 29906, name = "Vashj's Vial Remnant", count = 1 },
      inside = { instance = 548, heroic = false, boss = "Lady Vashj", npcs = { 21212 } },
      places = {
        { role = "inside", name = "Serpentshrine Cavern", instance = 548 },
      },
      detail = "Lady Vashj is the sixth and final boss of Serpentshrine Cavern, reachable after Hydross, Lurker, Leotheras, Karathress and Morogrim (since Phase 3 on Anniversary you may skip straight to her). The remnant is a quest item that every raid member on The Vials of Eternity can loot. Either remnant can be collected first." },
    { key = "kael_remnant", kind = "ITEM", title = "Loot Kael's Vial Remnant from Kael'thas Sunstrider", optional = false, phases = { from = 3, to = 3 }, consumedBy = "turn_in_vials",
      item = { id = 29905, name = "Kael's Vial Remnant", count = 1 },
      inside = { instance = 550, heroic = false, boss = "Kael'thas Sunstrider", npcs = { 19622 } },
      places = {
        { role = "inside", name = "Tempest Keep: The Eye", instance = 550 },
      },
      detail = "Kael'thas Sunstrider is the last boss of The Eye in Netherstorm, after Al'ar, Void Reaver and High Astromancer Solarian (skippable on Anniversary since Phase 3). The remnant is a quest item lootable by everyone on the quest. With both remnants in hand, return to the Caverns of Time." },
    { key = "turn_in_vials", kind = "QUEST", title = "Return both remnants to Soridormi", optional = false, phases = { from = 3, to = 3 }, questId = 10445, questName = "The Vials of Eternity",
      places = {
        { role = "start", name = "Soridormi", npc = 19935, zone = "Tanaris", map = 1446, x = 58.9, y = 54.2 },
        { role = "turnin", name = "Soridormi", npc = 19935, zone = "Tanaris", map = 1446, x = 58.9, y = 54.2 },
      },
      detail = "Handing in grants 13 gold 20 silver and three thousand Scale of the Sands reputation, which takes a fresh character to Friendly. From Friendly onwards Soridormi offers the Band of Eternity rings (Defender, Champion, Sage and Restorer lines; the Exalted versions are Band of the Eternal Defender, Champion, Sage and Restorer), each upgraded as your Hyjal reputation rises. The Hyjal Summit portal is inside the Caverns of Time. If you have also completed A Distraction for Akama you are granted the title Hand of A'dal." },
  },
}
end

