    { key = "akamas_promise", kind = "QUEST", title = "Bring Akama's Medallion of Karabor to A'dal", optional = false, phases = { from = 3, to = 3 }, questId = 11052, altQuestIds = { 10708 }, questName = "Akama's Promise",
