    { key = "distraction_for_akama", kind = "QUEST", title = "Escort Akama and Maiev into the Black Temple", optional = false, phases = { from = 3, to = 3 }, questId = 10985, questName = "A Distraction for Akama", questItem = { id = 32649, name = "Medallion of Karabor", count = 1 },
