do
D.guides[#D.guides + 1] = {
  key = "HEROIC_HELLFIRE", name = "Heroic Hellfire", title = "Heroic Hellfire Citadel: the Flamewrought Key",
  category = "HEROIC", order = 10, faction = "BOTH", gate = nil,
  phase = { introduced = 1, requiredUntil = false,
            note = "The key is needed for the whole of TBC; the standing it costs fell to Honored with the Zul'Aman update." },
  unlock = { items = { 30622, 30637, 265830, 265826 } },
  accountWide = false, minLevel = 70, instance = 540, recurring = false,
  prerequisites = {},
  alternatives = nil,
  summary = "Heroic Hellfire Ramparts, The Blood Furnace and The Shattered Halls open with the Flamewrought Key, sold by the Honor Hold or Thrallmar quartermaster once your standing is high enough. Reputation comes from the Hellfire Peninsula quest lines, the Hellfire Citadel dungeons themselves and the daily Hellfire Fortifications PvP quest. On Anniversary realms a main who has reached Revered can also buy a Communal pouch whose account bound key gives alts heroic access at Friendly.",
  unlocks = "Heroic difficulty for Hellfire Ramparts, The Blood Furnace and The Shattered Halls, plus the heroic daily quests that send you there.",
  steps = {
    { key = "level_70", kind = "LEVEL", title = "Reach level 70", optional = false, level = 70, phases = { from = 1, to = false },
      detail = "Heroic dungeons admit level 70 characters only, and the Hellfire Peninsula quest lines that pay the bulk of early Honor Hold or Thrallmar reputation run from 58 to 63. Finish the zone's hubs (Honor Hold or Thrallmar, then Expedition Point or Falcon Watch) as you level; the reputation they pay is banked towards the key. Everything else in this guide can be done in any order once you are 70." },
    { key = "fortifications_daily", kind = "QUEST", title = "Run the Hellfire Fortifications daily when you pass by", optional = true, daily = true, phases = { from = 1, to = false }, questId = { A = 10106, H = 10110 }, questName = "Hellfire Fortifications",
      places = {
        {
          A = {
            role = "start",
            name = "Warrant Officer Tracy Proudwell",
            npc = 18266,
            zone = "Hellfire Peninsula",
            map = 1944,
            x = 56.3,
            y = 62.8,
          },
          H = {
            role = "start",
            name = "Battlecryer Blackeye",
            npc = 18267,
            zone = "Hellfire Peninsula",
            map = 1944,
            x = 56,
            y = 39.2,
          },
        },
        {
          A = {
            role = "turnin",
            name = "Warrant Officer Tracy Proudwell",
            npc = 18266,
            zone = "Hellfire Peninsula",
            map = 1944,
            x = 56.3,
            y = 62.8,
          },
          H = {
            role = "turnin",
            name = "Battlecryer Blackeye",
            npc = 18267,
            zone = "Hellfire Peninsula",
            map = 1944,
            x = 56,
            y = 39.2,
          },
        },
      },
      detail = "Capture the Overlook, the Stadium and Broken Hill (the three PvP towers in central Hellfire Peninsula) while your faction holds them and hand in to the warrant officer in your town. It pays 150 reputation, 70 silver (1 gold 13 silver 50 copper at level 70) and three Marks of Honor Hold or Marks of Thrallmar. The marks are PvP currency spent at the same quartermasters on gear and consumables; there is no mark hand in for reputation in TBC. It is a daily, so it is a steady top up rather than a route on its own." },
    { key = "rep_revered", kind = "REP", title = "Reach Revered with Honor Hold or Thrallmar", optional = false, phases = { from = 1, to = 3 }, factionId = { A = 946, H = 947 }, factionName = { A = "Honor Hold", H = "Thrallmar" }, standing = 7,
      detail = "Before the Zul'Aman phase the key needs Revered, 21000 points past Neutral. The Hellfire Peninsula quest hubs carry most characters to Friendly or early Honored; Hellfire Ramparts and The Blood Furnace pay on normal only until Honored and then stop. From Honored the grind is The Shattered Halls (level 70, its door needs the Shattered Halls Key or a rogue with 350 lockpicking), which keeps paying on normal to Exalted, and Nether-Stalker Mah'duun's normal daily Wanted: Shattered Hand Centurions (250 reputation). Every Hellfire heroic also pays to Exalted, but each member needs the key to zone in, so heroics only help once you hold one. The Hellfire Fortifications daily adds 150 a day." },
    { key = "rep_honored", kind = "REP", title = "Reach Honored with Honor Hold or Thrallmar", optional = false, phases = { from = 4, to = false }, factionId = { A = 946, H = 947 }, factionName = { A = "Honor Hold", H = "Thrallmar" }, standing = 6,
      detail = "From the Zul'Aman phase the quartermaster sells the Flamewrought Key at Honored, 9000 points past Neutral. The Hellfire Peninsula quest lines plus a handful of Hellfire Ramparts and Blood Furnace runs reach it; those two dungeons stop paying at Honored, which is now exactly the standing you need. If you are short, The Shattered Halls on normal, the Hellfire Fortifications daily (150) and Mah'duun's Wanted: Shattered Hand Centurions daily (250) all count. Anniversary realms switched on 22 October 2026; TBC Classic 2021 switched on 22 March 2022." },
    { key = "buy_key", kind = "ITEM", title = "Buy the Flamewrought Key", optional = false, phases = { from = 1, to = false },
      item = {
        id = { A = 30622, H = 30637 },
        name = "Flamewrought Key",
        count = 1,
        anyOf = { A = { 30622, 265830 }, H = { 30637, 265826 } },
      },
      places = {
        {
          A = {
            role = "vendor",
            name = "Logistics Officer Ulrike",
            npc = 17657,
            zone = "Hellfire Peninsula",
            map = 1944,
            x = 56.7,
            y = 62.6,
          },
          H = {
            role = "vendor",
            name = "Quartermaster Urgronn",
            npc = 17585,
            zone = "Hellfire Peninsula",
            map = 1944,
            x = 54.9,
            y = 37.8,
          },
        },
      },
      detail = "Visit Logistics Officer Ulrike in Honor Hold (Alliance) or Quartermaster Urgronn outside the Thrallmar stronghold (Horde) and buy the Flamewrought Key for 10 gold. It binds when picked up, is unique and goes straight to your keyring; you never use it, holding it is the attunement. One key covers all three Hellfire Citadel heroics. The vendor gates the sale on your standing, Revered before phase 4 and Honored from phase 4." },
    { key = "communal_key", kind = "ITEM", title = "Alts: hold a Communal Flamewrought Key at Friendly", optional = true, phases = { from = 2, to = false }, pouch = { item = { A = 265842, H = 265829 }, name = "Communal Flamewrought Pouch", cost = "80 gold", standing = 7 },
      item = { id = { A = 265830, H = 265826 }, name = "Communal Flamewrought Key", count = 1 },
      places = {
        {
          A = {
            role = "vendor",
            name = "Logistics Officer Ulrike",
            npc = 17657,
            zone = "Hellfire Peninsula",
            map = 1944,
            x = 56.7,
            y = 62.6,
          },
          H = {
            role = "vendor",
            name = "Quartermaster Urgronn",
            npc = 17585,
            zone = "Hellfire Peninsula",
            map = 1944,
            x = 54.9,
            y = 37.8,
          },
        },
      },
      detail = "Anniversary realms only. Once a character on your account is Revered the same quartermaster also sells the Communal Flamewrought Pouch for 80 gold (Horde 265829 since patch 2.5.5, 13 Jan 2026; Alliance 265842 only since patch 2.5.6, 7 July 2026; before that the 12 Feb 2026 hotfix let the Horde key be used by either faction); opening it puts a Communal Flamewrought Key (265830 Alliance, 265826 Horde) in the keyring that binds to your Battle.net account and can be mailed between your characters. An alt needs only Friendly with Honor Hold or Thrallmar to hold it and enter heroics, and since the 12 February 2026 hotfix either faction's key works for a character that is Friendly with either faction. It is an item, not an account flag, so it must sit in the alt's keyring; pass it along as each alt earns its own key. Whether the pouch's own purchase requirement dropped to Honored on 22 October 2026 is not confirmed." },
    { key = "set_heroic", kind = "MANUAL", title = "Set the dungeon difficulty to Heroic", optional = false, phases = { from = 1, to = false }, auto = { dungeonDifficulty = 2 },
      detail = "Before anyone zones in, the party leader right clicks their own portrait, opens Dungeon Difficulty and chooses Heroic, or runs /run SetDungeonDifficultyID(2). The difficulty is taken from the leader, but every member who enters needs the key in their own keyring. Heroics require level 70, lock you to one run per dungeon per day and award a Badge of Justice from each boss. Since 22 October 2026 Anniversary heroics run at their final, reduced 2.4.3 difficulty." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "HEROIC_COILFANG", name = "Heroic Coilfang", title = "Heroic Coilfang Reservoir: the Reservoir Key",
  category = "HEROIC", order = 20, faction = "BOTH", gate = nil,
  phase = { introduced = 1, requiredUntil = false,
            note = "The key is needed for the whole of TBC; the standing it costs fell to Honored with the Zul'Aman update." },
  unlock = { items = { 30623, 265843 } },
  accountWide = false, minLevel = 70, instance = 545, recurring = false,
  prerequisites = {},
  alternatives = nil,
  summary = "Heroic Slave Pens, Underbog and Steamvault open with the Reservoir Key, sold by Fedryen Swiftspear at Cenarion Refuge once your Cenarion Expedition standing is high enough. Zangarmarsh quests, the Coilfang dungeons and two repeatable hand ins (Unidentified Plant Parts and Coilfang Armaments) feed the faction. On Anniversary realms a Revered main can buy a Communal pouch whose account bound key covers alts at Friendly.",
  unlocks = "Heroic difficulty for The Slave Pens, The Underbog and The Steamvault, plus their heroic daily quests.",
  steps = {
    { key = "level_70", kind = "LEVEL", title = "Reach level 70", optional = false, level = 70, phases = { from = 1, to = false },
      detail = "Heroics admit level 70 characters only. Quest through Zangarmarsh (Cenarion Refuge, Telredor or Zabra'jin, Orebor Harborage or Swamprat Post) at 60 to 64 and keep every Unidentified Plant Parts you loot from the zone's mobs; the Cenarion Expedition reputation and the plant parts both count towards the key later." },
    { key = "plants_of_zangarmarsh", kind = "QUEST", title = "Hand in your first ten Unidentified Plant Parts", optional = true, phases = { from = 1, to = false }, questId = 9802, questName = "Plants of Zangarmarsh", questItem = { id = 24401, name = "Unidentified Plant Parts", count = 10 },
      places = {
        {
          role = "start",
          name = "Lauranna Thar'well",
          npc = 17909,
          zone = "Zangarmarsh",
          map = 1946,
          x = 80.3,
          y = 64.2,
        },
        {
          role = "turnin",
          name = "Lauranna Thar'well",
          npc = 17909,
          zone = "Zangarmarsh",
          map = 1946,
          x = 80.3,
          y = 64.2,
        },
      },
      detail = "Bring ten Unidentified Plant Parts (dropped by most Zangarmarsh creatures and cheap on the auction house) to Lauranna Thar'well at Cenarion Refuge for 250 reputation and a Package of Identified Plants. This unlocks the repeatable Identify Plant Parts, ten parts for 250 reputation each time, available until Honored. Each package can contain an Uncatalogued Species that starts its own hand in (500 reputation) and still works after Honored. A stack of 360 parts is roughly Neutral to Honored on its own." },
    { key = "orders_from_lady_vashj", kind = "QUEST", title = "Deliver Orders from Lady Vashj", optional = true, phases = { from = 1, to = false }, questId = 9764, questName = "Orders from Lady Vashj",
      inside = { instance = 545, heroic = false },
      places = {
        { role = "start", item = 24367, name = "Orders from Lady Vashj" },
        {
          role = "turnin",
          name = "Ysiel Windsinger",
          npc = 17841,
          zone = "Zangarmarsh",
          map = 1946,
          x = 78.4,
          y = 62,
        },
        { role = "inside", name = "The Steamvault", instance = 545 },
      },
      detail = "The Orders from Lady Vashj (level 67) drop from the naga in The Steamvault: Coilfang Myrmidons, Engineers, Sirens, Sorceresses, Warriors, Oracles and Slavemasters. Right click the orders and deliver them to Ysiel Windsinger on the back porch of the Cenarion Refuge inn for 500 reputation. Ysiel then offers Preparing for War (one Coilfang Armament for 250 reputation), which opens the repeatable Coilfang Armaments, 75 reputation per armament all the way to Exalted." },
    { key = "preparing_for_war", kind = "QUEST", title = "Hand in your first Coilfang Armament", optional = true, phases = { from = 1, to = false }, questId = 9765, questName = "Preparing for War", questItem = { id = 24368, name = "Coilfang Armaments", count = 1 },
      places = {
        {
          role = "start",
          name = "Ysiel Windsinger",
          npc = 17841,
          zone = "Zangarmarsh",
          map = 1946,
          x = 78.4,
          y = 62,
        },
        {
          role = "turnin",
          name = "Ysiel Windsinger",
          npc = 17841,
          zone = "Zangarmarsh",
          map = 1946,
          x = 78.4,
          y = 62,
        },
      },
      detail = "Coilfang Armaments drop from the naga throughout Coilfang Reservoir, mostly in The Steamvault, and trade freely so they can be bought. One armament completes Preparing for War for 250 reputation and unlocks the repeatable Coilfang Armaments at 75 reputation each, which keeps paying through Exalted and is the usual filler between Steamvault runs. Keep every armament you loot from now on. Ysiel only offers Preparing for War after Orders from Lady Vashj is complete." },
    { key = "rep_revered", kind = "REP", title = "Reach Revered with the Cenarion Expedition", optional = false, phases = { from = 1, to = 3 }, factionId = 942, factionName = "Cenarion Expedition", standing = 7,
      detail = "Before the Zul'Aman phase the key needs Revered, 21000 points past Neutral. The Slave Pens and The Underbog pay reputation on normal only until Honored; The Steamvault (level 70) keeps paying on normal to Exalted at roughly 1100 to 1660 a full clear and is the main grind. Zangarmarsh quests give a few thousand, and Cenarion Expedition quests also appear at Cenarion Post in Hellfire, Cenarion Thicket in Terokkar and Evergrove in Blade's Edge. Repeatables: Identify Plant Parts (250 per ten parts, to Honored), Uncatalogued Species (500 each, any standing) and Coilfang Armaments (75 each, to Exalted). Nether-Stalker Mah'duun's normal Steamvault daily Wanted: Coilfang Myrmidons pays 250, and Wind Trader Zhareem's heroic dailies pay 350 once you hold the key." },
    { key = "rep_honored", kind = "REP", title = "Reach Honored with the Cenarion Expedition", optional = false, phases = { from = 4, to = false }, factionId = 942, factionName = "Cenarion Expedition", standing = 6,
      detail = "From the Zul'Aman phase the key is sold at Honored, 9000 points past Neutral. Zangarmarsh quests plus Slave Pens and Underbog runs reach it, and those two dungeons stop paying at exactly Honored. Identify Plant Parts (250 per ten Unidentified Plant Parts) is the quickest filler, since parts are cheap and the quest is available precisely until Honored. The Steamvault, Coilfang Armaments (75 each) and Mah'duun's Wanted: Coilfang Myrmidons daily (250) also count." },
    { key = "buy_key", kind = "ITEM", title = "Buy the Reservoir Key", optional = false, phases = { from = 1, to = false },
      item = { id = 30623, name = "Reservoir Key", count = 1, anyOf = { 30623, 265843 } },
      places = {
        {
          role = "vendor",
          name = "Fedryen Swiftspear",
          npc = 17904,
          zone = "Zangarmarsh",
          map = 1946,
          x = 79.3,
          y = 63.7,
        },
      },
      detail = "Fedryen Swiftspear, the Cenarion Expedition quartermaster at Cenarion Refuge, sells the Reservoir Key for 10 gold. It binds when picked up, is unique and sits in your keyring; holding it is the attunement for all three Coilfang heroics. The sale is gated on your standing, Revered before phase 4 and Honored from phase 4." },
    { key = "communal_key", kind = "ITEM", title = "Alts: hold a Communal Reservoir Key at Friendly", optional = true, phases = { from = 2, to = false }, pouch = { item = 265844, name = "Communal Reservoir Pouch", cost = "80 gold", standing = 7 },
      item = { id = 265843, name = "Communal Reservoir Key", count = 1 },
      places = {
        {
          role = "vendor",
          name = "Fedryen Swiftspear",
          npc = 17904,
          zone = "Zangarmarsh",
          map = 1946,
          x = 79.3,
          y = 63.7,
        },
      },
      detail = "Anniversary realms only. Once a character on the account is Revered, Fedryen also sells the Communal Reservoir Pouch for 80 gold; opening it yields a Communal Reservoir Key that binds to your Battle.net account and can be mailed between your characters. An alt needs only Friendly with the Cenarion Expedition to hold it and enter Coilfang heroics. It is an item, not an account flag, so it must sit in the alt's keyring. Whether the pouch's purchase requirement also dropped to Honored on 22 October 2026 is not confirmed." },
    { key = "set_heroic", kind = "MANUAL", title = "Set the dungeon difficulty to Heroic", optional = false, phases = { from = 1, to = false }, auto = { dungeonDifficulty = 2 },
      detail = "Before anyone zones in, the party leader right clicks their own portrait, opens Dungeon Difficulty and chooses Heroic, or runs /run SetDungeonDifficultyID(2). The difficulty is taken from the leader, but every member who enters needs the key in their own keyring. Heroics require level 70, lock you to one run per dungeon per day and award a Badge of Justice from each boss. Since 22 October 2026 Anniversary heroics run at their final, reduced 2.4.3 difficulty." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "HEROIC_AUCHINDOUN", name = "Heroic Auchindoun", title = "Heroic Auchindoun: the Auchenai Key",
  category = "HEROIC", order = 30, faction = "BOTH", gate = nil,
  phase = { introduced = 1, requiredUntil = false,
            note = "The key is needed for the whole of TBC; the standing it costs fell to Honored with the Zul'Aman update." },
  unlock = { items = { 30633, 265845 } },
  accountWide = false, minLevel = 70, instance = 555, recurring = false,
  prerequisites = {},
  alternatives = nil,
  summary = "Heroic Mana-Tombs, Auchenai Crypts, Sethekk Halls and Shadow Labyrinth open with the Auchenai Key, sold by Nakodu in Shattrath's Lower City once your Lower City standing is high enough. Terokkar Forest and Lower City quests, the Auchindoun dungeons and the repeatable Arakkoa Feather hand in feed the faction; Mana-Tombs pays the Consortium instead. On Anniversary realms a Revered main can buy a Communal pouch whose account bound key covers alts at Friendly.",
  unlocks = "Heroic difficulty for Mana-Tombs, Auchenai Crypts, Sethekk Halls and Shadow Labyrinth, plus their heroic daily quests.",
  steps = {
    { key = "level_70", kind = "LEVEL", title = "Reach level 70", optional = false, level = 70, phases = { from = 1, to = false },
      detail = "Heroics admit level 70 characters only. Quest through Terokkar Forest and Shattrath's Lower City at 62 to 65 and keep every Arakkoa Feather you loot from the arakkoa camps; both the quest reputation and the feathers count towards the key." },
    { key = "outcasts_plight", kind = "QUEST", title = "Hand in thirty Arakkoa Feathers to Vekax", optional = true, phases = { from = 1, to = false }, questId = 10917, questName = "The Outcast's Plight", questItem = { id = 25719, name = "Arakkoa Feather", count = 30 },
      places = {
        { role = "start", name = "Vekax", npc = 22429, zone = "Shattrath City", map = 1955, x = 46.2, y = 22.4 },
        { role = "turnin", name = "Vekax", npc = 22429, zone = "Shattrath City", map = 1955, x = 46.2, y = 22.4 },
      },
      detail = "Arakkoa Feathers drop from the arakkoa of Terokkar Forest (Veil Shienor, Veil Reskk, Veil Skith, Veil Shalas, Veil Lithic and the Skettis outskirts) and trade freely. Thirty of them to Vekax, the arakkoa outcast in Lower City, complete The Outcast's Plight for 250 reputation, 3 gold 30 silver and an Outcast's Cache. That unlocks the repeatable More Feathers, another 250 reputation per thirty feathers, available until Honored; the cache holds a random green, blue or occasionally better item. Roughly 1080 feathers take a fresh character to Honored with no dungeons at all." },
    { key = "rep_revered", kind = "REP", title = "Reach Revered with Lower City", optional = false, phases = { from = 1, to = 3 }, factionId = 1011, factionName = "Lower City", standing = 7,
      detail = "Before the Zul'Aman phase the key needs Revered, 21000 points past Neutral. Auchenai Crypts and Sethekk Halls pay on normal to Honored (since patch 2.3 Sethekk mobs keep paying into Exalted, and Anniversary now runs the final dungeon rules); Shadow Labyrinth (level 70, its door needs the Shadow Labyrinth Key from Talon King Ikiss or a rogue) pays on normal to Exalted and is the main grind. Mana-Tombs pays the Consortium on both difficulties, not Lower City, although the Auchenai Key still opens its heroic. Terokkar and Lower City quests total about 8200 reputation, More Feathers adds 250 per thirty feathers, Nether-Stalker Mah'duun's normal daily Wanted: Malicious Instructors (Shadow Labyrinth) pays 250, and Wind Trader Zhareem's heroic dailies pay 350 once you hold the key." },
    { key = "rep_honored", kind = "REP", title = "Reach Honored with Lower City", optional = false, phases = { from = 4, to = false }, factionId = 1011, factionName = "Lower City", standing = 6,
      detail = "From the Zul'Aman phase Nakodu sells the key at Honored, 9000 points past Neutral. Terokkar Forest and Lower City quests plus a few Auchenai Crypts and Sethekk Halls runs reach it, and feathers fill any gap: The Outcast's Plight then More Feathers pay 250 per thirty Arakkoa Feathers until Honored. Shadow Labyrinth and Mah'duun's Wanted: Malicious Instructors daily (250) also count. Mana-Tombs pays the Consortium, so it does not help here." },
    { key = "buy_key", kind = "ITEM", title = "Buy the Auchenai Key", optional = false, phases = { from = 1, to = false },
      item = { id = 30633, name = "Auchenai Key", count = 1, anyOf = { 30633, 265845 } },
      places = {
        { role = "vendor", name = "Nakodu", npc = 21655, zone = "Shattrath City", map = 1955, x = 62, y = 68.8 },
      },
      detail = "Nakodu, the Lower City quartermaster in the Lower City market of Shattrath, sells the Auchenai Key for 10 gold. It binds when picked up, is unique and sits in your keyring; holding it is the attunement for all four Auchindoun heroics, Mana-Tombs included. The sale is gated on your standing, Revered before phase 4 and Honored from phase 4." },
    { key = "communal_key", kind = "ITEM", title = "Alts: hold a Communal Auchenai Key at Friendly", optional = true, phases = { from = 2, to = false }, pouch = { item = 265846, name = "Communal Auchenai Pouch", cost = "80 gold", standing = 7 },
      item = { id = 265845, name = "Communal Auchenai Key", count = 1 },
      places = {
        { role = "vendor", name = "Nakodu", npc = 21655, zone = "Shattrath City", map = 1955, x = 62, y = 68.8 },
      },
      detail = "Anniversary realms only. Once a character on the account is Revered, Nakodu also sells the Communal Auchenai Pouch for 80 gold; opening it yields a Communal Auchenai Key that binds to your Battle.net account and can be mailed between your characters. An alt needs only Friendly with Lower City to hold it and enter Auchindoun heroics. It is an item, not an account flag, so it must sit in the alt's keyring. Whether the pouch's purchase requirement also dropped to Honored on 22 October 2026 is not confirmed." },
    { key = "set_heroic", kind = "MANUAL", title = "Set the dungeon difficulty to Heroic", optional = false, phases = { from = 1, to = false }, auto = { dungeonDifficulty = 2 },
      detail = "Before anyone zones in, the party leader right clicks their own portrait, opens Dungeon Difficulty and chooses Heroic, or runs /run SetDungeonDifficultyID(2). The difficulty is taken from the leader, but every member who enters needs the key in their own keyring. Heroics require level 70, lock you to one run per dungeon per day and award a Badge of Justice from each boss. Since 22 October 2026 Anniversary heroics run at their final, reduced 2.4.3 difficulty." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "HEROIC_TEMPEST_KEEP", name = "Heroic Tempest Keep", title = "Heroic Tempest Keep: the Warpforged Key",
  category = "HEROIC", order = 40, faction = "BOTH", gate = nil,
  phase = { introduced = 1, requiredUntil = false,
            note = "The key is needed for the whole of TBC; the standing it costs fell to Honored with the Zul'Aman update." },
  unlock = { items = { 30634, 265847 } },
  accountWide = false, minLevel = 70, instance = 552, recurring = false,
  prerequisites = {},
  alternatives = nil,
  summary = "Heroic Mechanar, Botanica and Arcatraz open with the Warpforged Key, sold by Almaador on Shattrath's Terrace of Light once your standing with The Sha'tar is high enough. The Tempest Keep dungeons are the main source, while every Aldor or Scryers quest spills half its reputation into The Sha'tar until Friendly is full. On Anniversary realms a Revered main can buy a Communal pouch whose account bound key covers alts at Friendly.",
