  steps = {
    { key = "level_70", kind = "LEVEL", title = "Reach level 70", optional = false, level = 70, phases = { from = 1, to = false },
      detail = "Heroics admit level 70 characters only, and the Tempest Keep dungeons are 67 to 70 content. Pick Aldor or Scryers when you reach Shattrath and quest for them through Nagrand, Shadowmoon Valley and Netherstorm; every one of those quests also pays half its reputation to The Sha'tar until you are at the top of Friendly." },
    { key = "rep_revered", kind = "REP", title = "Reach Revered with The Sha'tar", optional = false, phases = { from = 1, to = 3 }, factionId = 935, factionName = "The Sha'tar", standing = 7,
      detail = "Before the Zul'Aman phase the key needs Revered, 21000 points past Neutral. The Mechanar and The Botanica pay on normal until Honored (about 1600 and 2200 a full clear); The Arcatraz (level 70, needs the Key to the Arcatraz or a rogue) pays on normal to Exalted (about 1800 a clear) and is the main grind, with heroics paying about 2100, 3250 and 2600 once you hold the key. Aldor and Scryers hand ins (Marks of Sargeras or Firewing Signets, Fel Armaments or Arcane Tomes) spill half their reputation into The Sha'tar but only until 5999 into Friendly, so they get you to the doorstep of Honored and no further. Shattrath's own Sha'tar quests (the Arcatraz key chain How to Break Into the Arcatraz, Harbinger of Doom, Special Delivery to Shattrath City, the four Trial of the Naaru quests) add about 5000. Nether-Stalker Mah'duun's normal dailies Wanted: Sunseeker Channelers, Tempest-Forge Destroyers and Arcatraz Sentinels pay 250 each, and Wind Trader Zhareem's heroic dailies 350." },
    { key = "rep_honored", kind = "REP", title = "Reach Honored with The Sha'tar", optional = false, phases = { from = 4, to = false }, factionId = 935, factionName = "The Sha'tar", standing = 6,
      detail = "From the Zul'Aman phase Almaador sells the key at Honored, 9000 points past Neutral. The Aldor or Scryers spillover carries you to the end of Friendly on its own, so one or two Mechanar or Botanica clears, which pay until exactly Honored, finish the job. The Arcatraz, the Shattrath Sha'tar quests and Mah'duun's Tempest Keep dailies (250) also count." },
    { key = "buy_key", kind = "ITEM", title = "Buy the Warpforged Key", optional = false, phases = { from = 1, to = false },
      item = { id = 30634, name = "Warpforged Key", count = 1, anyOf = { 30634, 265847 } },
      places = {
        {
          role = "vendor",
          name = "Almaador",
          npc = 21432,
          zone = "Shattrath City",
          map = 1955,
          x = 51,
          y = 41.7,
        },
      },
      detail = "Almaador, the Sha'tari quartermaster under the central dome of Shattrath, sells the Warpforged Key for 10 gold. It binds when picked up, is unique and sits in your keyring; holding it is the attunement for all three Tempest Keep heroics. The sale is gated on your standing, Revered before phase 4 and Honored from phase 4." },
    { key = "communal_key", kind = "ITEM", title = "Alts: hold a Communal Warpforged Key at Friendly", optional = true, phases = { from = 2, to = false }, pouch = { item = 265848, name = "Communal Warpforged Pouch", cost = "80 gold", standing = 7 },
      item = { id = 265847, name = "Communal Warpforged Key", count = 1 },
      places = {
        {
          role = "vendor",
          name = "Almaador",
          npc = 21432,
          zone = "Shattrath City",
          map = 1955,
          x = 51,
          y = 41.7,
        },
      },
      detail = "Anniversary realms only. Once a character on the account is Revered, Almaador also sells the Communal Warpforged Pouch for 80 gold; opening it yields a Communal Warpforged Key that binds to your Battle.net account and can be mailed between your characters. An alt needs only Friendly with The Sha'tar, which the Aldor or Scryers spillover reaches quickly, to hold it and enter Tempest Keep heroics. It is an item, not an account flag, so it must sit in the alt's keyring. Whether the pouch's purchase requirement also dropped to Honored on 22 October 2026 is not confirmed." },
    { key = "set_heroic", kind = "MANUAL", title = "Set the dungeon difficulty to Heroic", optional = false, phases = { from = 1, to = false }, auto = { dungeonDifficulty = 2 },
      detail = "Before anyone zones in, the party leader right clicks their own portrait, opens Dungeon Difficulty and chooses Heroic, or runs /run SetDungeonDifficultyID(2). The difficulty is taken from the leader, but every member who enters needs the key in their own keyring. Heroics require level 70, lock you to one run per dungeon per day and award a Badge of Justice from each boss. Since 22 October 2026 Anniversary heroics run at their final, reduced 2.4.3 difficulty." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "HEROIC_CAVERNS_OF_TIME", name = "Heroic Caverns of Time", title = "Heroic Caverns of Time: the Key of Time",
  category = "HEROIC", order = 50, faction = "BOTH", gate = nil,
  phase = { introduced = 1, requiredUntil = false,
            note = "The key is needed for the whole of TBC; the standing it costs fell to Honored with the Zul'Aman update." },
  unlock = { items = { 30635, 265849 } },
  accountWide = false, minLevel = 70, instance = 269, recurring = false,
  prerequisites = {},
  alternatives = nil,
  summary = "Heroic Old Hillsbrad Foothills and The Black Morass open with the Key of Time, sold by Alurmi inside the Caverns of Time once your Keepers of Time standing is high enough. Almost all of that reputation comes from the two dungeons and their quest chain, which also gates entry to each of them. On Anniversary realms a Revered main can buy a Communal pouch whose account bound key covers alts at Friendly.",
  unlocks = "Heroic difficulty for Old Hillsbrad Foothills (Escape from Durnholde Keep) and The Black Morass, plus their heroic daily quests.",
  steps = {
    { key = "level_70", kind = "LEVEL", title = "Reach level 70", optional = false, level = 70, phases = { from = 1, to = false },
      detail = "Heroics admit level 70 characters only. The Caverns of Time chain opens at 66, so most characters do Old Hillsbrad while levelling and the Black Morass at 70; both pay Keepers of Time reputation that counts towards the key." },
    { key = "caverns_of_time", kind = "QUEST", title = "Take the Custodian's tour of the Caverns", optional = false, phases = { from = 1, to = false }, questId = 10277, questName = "The Caverns of Time",
      places = {
        {
          role = "start",
          name = "Andormu (child)",
          npc = 20130,
          zone = "Tanaris",
          map = 1446,
          x = 58.4,
          y = 54.3,
        },
        {
          role = "turnin",
          name = "Andormu (child)",
          npc = 20130,
          zone = "Tanaris",
          map = 1446,
          x = 58.4,
          y = 54.3,
        },
      },
      detail = "At the cavern mouth in eastern Tanaris the Steward of Time (66.0, 49.7) offers To The Master's Lair, which sends you down to the child Andormu at the bottom of the spiral. Andormu then gives The Caverns of Time: follow the Custodian of Time on a slow circuit of the cavern while it explains each portal, then speak to Andormu again for 250 reputation. Completing this tour is what lets you enter Old Hillsbrad Foothills, so do it before you queue for the dungeon." },
    { key = "return_to_andormu", kind = "QUEST", title = "Finish the Old Hillsbrad chain", optional = false, phases = { from = 1, to = false }, questId = 10285, questName = "Return to Andormu",
      inside = { instance = 560, heroic = false, boss = "Epoch Hunter" },
      places = {
        { role = "start", name = "Erozion", npc = 18723, zone = "Old Hillsbrad Foothills", instance = 560 },
        {
          role = "turnin",
          name = "Andormu (child)",
          npc = 20130,
          zone = "Tanaris",
          map = 1446,
          x = 58.4,
          y = 54.3,
        },
        { role = "inside", name = "Old Hillsbrad Foothills", instance = 560 },
      },
      detail = "Andormu's Old Hillsbrad sends you to Erozion just inside the Escape from Durnholde Keep instance. Erozion gives Taretha's Diversion (1000 reputation), which is handed in to Thrall in the Durnholde basement; Thrall then gives Escape from Durnholde (1000 reputation), handed in to Erozion, who offers Return to Andormu back to the Caverns for 3000 reputation and a choice of gloves (Tempest's Touch), boots (Southshore Sneakers), belt (Tarren Mill Defender's Cinch) or shoulders (Warchief's Mantle). A full normal clear pays about 1045 reputation (1199 if you clear Durnholde and Tarren Mill before starting the event); finishing this chain is also what lets you enter The Black Morass." },
    { key = "hero_of_the_brood", kind = "QUEST", title = "Defend Medivh in the Black Morass", optional = true, phases = { from = 1, to = false }, questId = 10298, questName = "Hero of the Brood",
      inside = { instance = 269, heroic = false, boss = "Aeonus" },
      places = {
        { role = "start", name = "Sa'at", npc = 20201, zone = "The Black Morass", instance = 269 },
        {
          role = "turnin",
          name = "Andormu (child)",
          npc = 20130,
          zone = "Tanaris",
          map = 1446,
          x = 58.4,
          y = 54.3,
        },
        { role = "inside", name = "The Black Morass", instance = 269 },
      },
      detail = "The adult Andormu (57.6, 59.0) gives The Black Morass (250 reputation) which sends you to Sa'at inside the Opening of the Dark Portal instance. Sa'at's The Opening of the Dark Portal is the whole dungeon: close eighteen time rifts, keep Medivh alive and kill Chrono Lord Deja, Temporus and Aeonus. Return to the child Andormu for Hero of the Brood, worth 8000 reputation, by far the largest single chunk towards the key, plus a choice of items. A full Black Morass clear pays about 1110 on normal and keeps paying to Exalted." },
    { key = "rep_revered", kind = "REP", title = "Reach Revered with the Keepers of Time", optional = false, phases = { from = 1, to = 3 }, factionId = 989, factionName = "Keepers of Time", standing = 7,
      detail = "Before the Zul'Aman phase the key needs Revered, 21000 points past Neutral. The quest chain alone pays 14020 (10 To The Master's Lair, 250 tour, 10 Old Hillsbrad, 1000 Taretha's Diversion, 1000 Escape from Durnholde, 3000 Return to Andormu, 250 The Black Morass, 500 The Opening of the Dark Portal, 8000 Hero of the Brood), which is Honored already. Old Hillsbrad Foothills pays on normal until Honored at about 1045 a clear; The Black Morass pays on normal to Exalted at about 1110 a clear and is the grind to Revered, with heroics paying about 2300 and 1725 once you hold the key. Nether-Stalker Mah'duun's normal daily Wanted: Rift Lords (Black Morass) pays 250 and Wind Trader Zhareem's heroic dailies (Epoch Hunter's Head, Aeonus's Hourglass) pay 350. Revered also lets Zephyr in Shattrath teleport you straight to the Caverns." },
    { key = "rep_honored", kind = "REP", title = "Reach Honored with the Keepers of Time", optional = false, phases = { from = 4, to = false }, factionId = 989, factionName = "Keepers of Time", standing = 6,
      detail = "From the Zul'Aman phase Alurmi sells the key at Honored, 9000 points past Neutral. Simply completing the chain, the Custodian's tour, the Old Hillsbrad escape with Return to Andormu and one Black Morass with Hero of the Brood, pays about 14000 (Taretha's Diversion and Escape from Durnholde are 1000 each, The Opening of the Dark Portal 500, on top of the four quests already counted) and takes you past Honored in a single evening. If you stop short of the Black Morass, a couple of Old Hillsbrad clears (about 1045 each, paying until Honored) finish it." },
    { key = "buy_key", kind = "ITEM", title = "Buy the Key of Time", optional = false, phases = { from = 1, to = false },
      item = { id = 30635, name = "Key of Time", count = 1, anyOf = { 30635, 265849 } },
      places = {
        { role = "vendor", name = "Alurmi", npc = 21643, zone = "Tanaris", map = 1446, x = 63.6, y = 57.6 },
      },
      detail = "Alurmi, the Keepers of Time quartermaster, stands inside the Caverns of Time near the Old Hillsbrad passage and sells the Key of Time for 10 gold. It binds when picked up, is unique and sits in your keyring; holding it is the attunement for both Caverns of Time heroics. The sale is gated on your standing, Revered before phase 4 and Honored from phase 4. The Caverns have no map of their own on this client, so the coordinates are on the Tanaris map." },
    { key = "communal_key", kind = "ITEM", title = "Alts: hold a Communal Key of Time at Friendly", optional = true, phases = { from = 2, to = false }, pouch = { item = 265850, name = "Communal Time Pouch", cost = "80 gold", standing = 7 },
      item = { id = 265849, name = "Communal Key of Time", count = 1 },
      places = {
        { role = "vendor", name = "Alurmi", npc = 21643, zone = "Tanaris", map = 1446, x = 63.6, y = 57.6 },
      },
      detail = "Anniversary realms only. Once a character on the account is Revered, Alurmi also sells the Communal Time Pouch for 80 gold; opening it yields a Communal Key of Time that binds to your Battle.net account and can be mailed between your characters. An alt needs only Friendly with the Keepers of Time, which the Custodian's tour and the Old Hillsbrad chain give, to hold it and enter Caverns of Time heroics. It is an item, not an account flag, so it must sit in the alt's keyring. Whether the pouch's purchase requirement also dropped to Honored on 22 October 2026 is not confirmed." },
    { key = "set_heroic", kind = "MANUAL", title = "Set the dungeon difficulty to Heroic", optional = false, phases = { from = 1, to = false }, auto = { dungeonDifficulty = 2 },
      detail = "Before anyone zones in, the party leader right clicks their own portrait, opens Dungeon Difficulty and chooses Heroic, or runs /run SetDungeonDifficultyID(2). The difficulty is taken from the leader, but every member who enters needs the key in their own keyring. Heroics require level 70, lock you to one run per dungeon per day and award a Badge of Justice from each boss. Since 22 October 2026 Anniversary heroics run at their final, reduced 2.4.3 difficulty." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "HEROIC_MAGISTERS_TERRACE", name = "Magisters' Terrace", title = "Heroic Magisters' Terrace: Hard to Kill",
  category = "HEROIC", order = 60, faction = "BOTH", gate = nil,
  phase = { introduced = 5, requiredUntil = false,
            note = "Magisters' Terrace arrives with Phase 5, Fury of the Sunwell, which has no announced date; Hard to Kill opens its heroic door." },
  unlock = { quest = 11492 },
  accountWide = false, minLevel = 70, instance = 585, recurring = false,
  prerequisites = {},
  alternatives = nil,
  summary = "Magisters' Terrace on the Isle of Quel'Danas has no key. Heroic access is granted by finishing the Hard to Kill chain, which starts in Shattrath with the Aldor or the Scryers, runs through the Shattered Sun Staging Area and ends with Kael'thas Sunstrider's head from the normal dungeon. It arrives with the Sunwell phase and gives the only heroic in TBC whose attunement is a quest flag rather than an item.",
  unlocks = "Heroic difficulty for Magisters' Terrace, its heroic daily quest, and the chance at Kael'thas' heroic only drops (Phoenix Hatchling, Swift White Hawkstrider).",
  steps = {
    { key = "level_70", kind = "LEVEL", title = "Reach level 70", optional = false, level = 70, phases = { from = 5, to = false },
      detail = "Every quest in the chain requires level 70 and the dungeon is tuned for raid ready characters. Nothing else is needed to start: no reputation, no earlier attunement and no key." },
    { key = "sunwell_summons", kind = "QUEST", title = "Answer the call to the Sunwell", optional = true, phases = { from = 5, to = false }, questId = 11481, altQuestIds = { 11482 }, questName = { ALDOR = "Crisis at the Sunwell", SCRYER = "Duty Calls" }, impliedBy = { 11488, 11490, 11492 },
      places = {
        {
          ALDOR = {
            role = "start",
            name = "Adyen the Lightwarden",
            npc = 18537,
            zone = "Shattrath City",
            map = 1955,
            x = 30.7,
            y = 34.6,
          },
          SCRYER = {
            role = "start",
            name = "Dathris Sunstriker",
            npc = 18594,
            zone = "Shattrath City",
            map = 1955,
            x = 54.6,
            y = 80.7,
          },
        },
        {
          role = "turnin",
          name = "Exarch Larethor",
          npc = 24813,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 47.4,
          y = 30.7,
        },
      },
      detail = "Take whichever version matches your Shattrath faction: Adyen the Lightwarden on the Aldor Rise offers Crisis at the Sunwell, Dathris Sunstriker outside the inn on the Scryer's Tier offers Duty Calls. Both simply send you to Exarch Larethor at the Shattered Sun Staging Area on the Isle of Quel'Danas, reached by the portal in the middle of Shattrath or the flight from Silvermoon or Ironforge, and both pay 10 Shattered Sun Offensive reputation. Either one leads into the same chain." },
    { key = "find_tyrith", kind = "QUEST", title = "Find Tyrith inside Magisters' Terrace", optional = false, phases = { from = 5, to = false }, questId = 11488, questName = "Magisters' Terrace",
      inside = { instance = 585, heroic = false, npcs = { 24822 } },
      places = {
        {
          role = "start",
          name = "Exarch Larethor",
          npc = 24813,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 47.4,
          y = 30.7,
        },
        { role = "turnin", name = "Tyrith", npc = 24822, zone = "Magisters' Terrace", instance = 585 },
        { role = "inside", name = "Magisters' Terrace", instance = 585 },
      },
      detail = "Larethor asks you to search Magisters' Terrace for Tyrith, a blood elf spy. Enter the dungeon on normal difficulty (the entrance is on the north east of the Isle, at the far end of the Terrace from the staging area) and fight through to Tyrith, who waits inside past the first boss Selin Fireheart. Hand in to him for 250 reputation; he immediately offers the next step." },
    { key = "scryers_scryer", kind = "QUEST", title = "Use the Scrying Orb and speak with Kalecgos", optional = false, phases = { from = 5, to = false }, questId = 11490, questName = "The Scryer's Scryer",
      inside = { instance = 585, heroic = false, npcs = { 24848 } },
      places = {
        { role = "start", name = "Tyrith", npc = 24822, zone = "Magisters' Terrace", instance = 585 },
        { role = "turnin", name = "Kalecgos", npc = 24848, zone = "Magisters' Terrace", instance = 585 },
        { role = "inside", name = "Magisters' Terrace", instance = 585 },
      },
      detail = "Tyrith wants you to activate the Scrying Orb on the open balcony further into the dungeon, past Vexallus. Clear to the orb and use it; an image of Kalecgos appears in his half elven form and shows Kael'thas scheming at the top of the Terrace. Speak to Kalecgos to complete the quest for 250 reputation and take Hard to Kill from him before the image fades." },
    { key = "hard_to_kill", kind = "QUEST", title = "Kill Kael'thas and bring his head to Larethor", optional = false, phases = { from = 5, to = false }, questId = 11492, questName = "Hard to Kill", questItem = { id = 34157, name = "Head of Kael'thas", count = 1 },
      inside = { instance = 585, heroic = false, boss = "Kael'thas Sunstrider", npcs = { 24664 } },
      places = {
        { role = "start", name = "Kalecgos", npc = 24848, zone = "Magisters' Terrace", instance = 585 },
        {
          role = "turnin",
          name = "Exarch Larethor",
          npc = 24813,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 47.4,
          y = 30.7,
        },
        { role = "inside", name = "Magisters' Terrace", instance = 585 },
      },
      detail = "Kill Kael'thas Sunstrider at the top of Magisters' Terrace on normal difficulty, after Priestess Delrissa's party, and loot the Head of Kael'thas. Kael'thas casts Flame Strike, summons a Phoenix that must be killed and its egg destroyed, and at low health begins Gravity Lapse, lifting everyone into the air; swim away from his Arcane Spheres and keep damage going. Take the head back to Exarch Larethor at the Shattered Sun Staging Area for 250 reputation and 19 gold 58 silver (4g40s base plus the 15g18s level-70 conversion; the quest is level 70 only, so the player always receives the full amount) and a choice of a Bright Crimson Spinel, a Runed Crimson Spinel or a Teardrop Crimson Spinel. Completing this quest is the heroic attunement itself; no key item exists." },
    { key = "set_heroic", kind = "MANUAL", title = "Set the dungeon difficulty to Heroic", optional = false, phases = { from = 5, to = false }, auto = { dungeonDifficulty = 2 },
      detail = "With Hard to Kill complete, the party leader right clicks their portrait, opens Dungeon Difficulty and chooses Heroic, or runs /run SetDungeonDifficultyID(2). Every member must have completed Hard to Kill themselves; the flag is per character and is not account wide on Anniversary. Heroic Magisters' Terrace locks you to one run per day, awards a Badge of Justice per boss, and is the dungeon behind Wind Trader Zhareem's heroic daily Wanted: The Signet Ring of Prince Kael'thas (Nether-Stalker Mah'duun's normal daily Wanted: Sisters of Torment needs no attunement)." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "CAVERNS_OF_TIME_ACCESS", name = "Caverns of Time", title = "Caverns of Time Access: Old Hillsbrad and the Black Morass",
  category = "DUNGEON", order = 10, faction = "BOTH", gate = nil,
  phase = { introduced = 1, requiredUntil = false,
            note = "The Old Hillsbrad chain has gated the Black Morass since Phase 1 and is never relaxed in TBC." },
  unlock = { quest = 10285 },
  accountWide = false, minLevel = 66, instance = 269, recurring = false,
  prerequisites = {},
  alternatives = nil,
  summary = "The bronze dragonflight will not let you into their timeways until you have introduced yourself. A short chain at the bottom of the Caverns of Time in Tanaris opens Old Hillsbrad Foothills, and rescuing Thrall there opens The Black Morass. The Karazhan attunement cannot be finished without this chain, because Medivh is only reachable inside the Black Morass.",
  unlocks = "Finishing Return to Andormu lets you zone into The Black Morass on normal difficulty, which the Karazhan chain needs for The Master's Touch, and it carries you most of the way to Friendly with the Keepers of Time.",
  steps = {
    { key = "level_66", kind = "LEVEL", title = "Reach level 66", optional = false, level = 66, phases = { from = 1, to = false },
      detail = "Every quest in this chain has a minimum level of 66, and the Old Hillsbrad and Black Morass portals refuse anyone lower. The dungeons themselves are tuned for 66 to 68 and 68 to 70 respectively, so most players do the Old Hillsbrad half at 66 to 68 and save the Black Morass for 70. If you are only here for the Karazhan key you can wait until 70 and do the whole thing in one evening." },
    { key = "to_the_masters_lair", kind = "QUEST", title = "Speak to the Steward of Time at the cavern mouth", optional = false, phases = { from = 1, to = false }, questId = 10279, questName = "To The Master's Lair", impliedBy = { 10277, 10282, 10283, 10284, 10285, 10296, 10297, 10298 },
      places = {
        { role = "start", name = "Steward of Time", npc = 20142, zone = "Tanaris", map = 1446, x = 66, y = 49.6 },
        { role = "turnin", name = "Andormu", npc = 20130, zone = "Tanaris", map = 1446, x = 58.5, y = 54.2 },
      },
      detail = "The Caverns of Time entrance is the cave in the eastern mountains of Tanaris at about 65.7, 49.8; the Steward of Time stands just inside the tunnel. Take To The Master's Lair from him. He also offers a free dragon ride that drops you at the bottom of the cavern, which is far quicker than walking the spiral. Turn the quest in to the child Andormu, the small bronze dragon in the middle of the floor. The quest is identical for both factions and pays 10 Keepers of Time reputation." },
    { key = "the_caverns_of_time", kind = "QUEST", title = "Follow the Custodian of Time around the cavern", optional = false, phases = { from = 1, to = false }, questId = 10277, questName = "The Caverns of Time", impliedBy = { 10282, 10283, 10284, 10285, 10296, 10297, 10298 },
      places = {
        { role = "start", name = "Andormu", npc = 20130, zone = "Tanaris", map = 1446, x = 58.5, y = 54.2 },
        { role = "turnin", name = "Andormu", npc = 20130, zone = "Tanaris", map = 1446, x = 58.5, y = 54.2 },
      },
      detail = "Andormu asks you to follow the Custodian of Time on a guided tour of the cavern that takes roughly eight minutes. Stay with the Custodian until he finishes talking at each stop; the objective 'Caverns of Time Explained' completes when the tour ends. The tour is shared, so if several people are waiting one Custodian walks everyone round together. Turn in to Andormu for 250 Keepers of Time reputation. This is the quest Blizzard's own portal message names when it refuses entry to Old Hillsbrad." },
    { key = "old_hillsbrad", kind = "QUEST", title = "Enter Old Hillsbrad and find Erozion", optional = false, phases = { from = 1, to = false }, questId = 10282, questName = "Old Hillsbrad", impliedBy = { 10283, 10284, 10285, 10296, 10297, 10298 },
      inside = { instance = 560, heroic = false, npcs = { 18723 } },
      places = {
        { role = "start", name = "Andormu", npc = 20130, zone = "Tanaris", map = 1446, x = 58.5, y = 54.2 },
        { role = "turnin", name = "Erozion", npc = 18723, zone = "Old Hillsbrad Foothills", instance = 560 },
        { role = "inside", name = "Old Hillsbrad Foothills", instance = 560 },
      },
      detail = "Andormu now sends you into Old Hillsbrad Foothills. The portal is in the cavern below at about 55.5, 53.3 on the Tanaris map, the north west timeway. Walk the entrance tunnel to Erozion, the bronze drake disguised as a human, and hand in the quest; he is a few yards inside, before the first humans. Everybody in the group should turn this in and take the next quest themselves, because Erozion does not share it automatically." },
    { key = "tarethas_diversion", kind = "QUEST", title = "Burn the five internment lodges at Durnholde", optional = false, phases = { from = 1, to = false }, questId = 10283, questName = "Taretha's Diversion", questItem = { id = 25853, name = "Pack of Incendiary Bombs", count = 1 }, impliedBy = { 10284, 10285, 10296, 10297, 10298 },
      inside = { instance = 560, heroic = false, boss = "Lieutenant Drake", npcs = { 17848 } },
      places = {
        { role = "start", name = "Erozion", npc = 18723, zone = "Old Hillsbrad Foothills", instance = 560 },
        { role = "turnin", name = "Thrall", npc = 17876, zone = "Old Hillsbrad Foothills", instance = 560 },
        { role = "inside", name = "Old Hillsbrad Foothills", instance = 560 },
      },
      detail = "Erozion gives you a Pack of Incendiary Bombs; if you ever lose it, talk to him again. Speak to the drake Brazen next to him for a flight to Durnholde Keep, or ride along the road. Inside the keep, use the pack on the barrel in each of the five internment lodges on the lower terrace; each use plants a charge and the lodge goes up in flames. When all five burn, the objective 'Internment Lodges Set Ablaze' completes and Lieutenant Drake comes out to fight. Then go up into the keep, take the stairs by the central room down to the prison and hand in to Thrall in his cell." },
    { key = "escape_from_durnholde", kind = "QUEST", title = "Escort Thrall to Tarren Mill and kill the Epoch Hunter", optional = false, phases = { from = 1, to = false }, questId = 10284, questName = "Escape from Durnholde", impliedBy = { 10285, 10296, 10297, 10298 },
      inside = { instance = 560, heroic = false, boss = "Epoch Hunter", npcs = { 17862, 18096 } },
      places = {
        { role = "start", name = "Thrall", npc = 17876, zone = "Old Hillsbrad Foothills", instance = 560 },
        { role = "turnin", name = "Erozion", npc = 18723, zone = "Old Hillsbrad Foothills", instance = 560 },
        { role = "inside", name = "Old Hillsbrad Foothills", instance = 560 },
      },
      detail = "Make sure every party member has accepted the quest before anyone tells Thrall to go, because the event only credits players on the quest. Thrall fights his way out of the keep, is ambushed on the road by Captain Skarloc and his guards, then rides to Tarren Mill where you clear the town, free Taretha at the inn and finally kill the Epoch Hunter when it lands outside. Keep Thrall alive and let him lead; if he dies the event resets and you talk to him in the prison again after a short wait. Taretha's cutscene completes 'Thrall's Destiny Fulfilled'. Run back to Erozion at the instance entrance to turn in for 1000 Keepers of Time reputation." },
    { key = "return_to_andormu", kind = "QUEST", title = "Return to Andormu to open the Black Morass", optional = false, phases = { from = 1, to = false }, questId = 10285, questName = "Return to Andormu", impliedBy = { 10296, 10297, 10298 },
      places = {
        { role = "start", name = "Erozion", npc = 18723, zone = "Old Hillsbrad Foothills", instance = 560 },
        { role = "turnin", name = "Andormu", npc = 20130, zone = "Tanaris", map = 1446, x = 58.5, y = 54.2 },
      },
      detail = "Erozion sends you back to the child Andormu on the cavern floor. Turning this in is the actual gate: the Black Morass portal checks that Return to Andormu is complete, and refuses with the message that you must first save Thrall. Pick one of Warchief's Mantle, Tempest's Touch, Southshore Sneakers or Tarren Mill Defender's Cinch and collect 3000 Keepers of Time reputation. From this moment you may zone into The Black Morass on normal difficulty." },
    { key = "the_black_morass", kind = "QUEST", title = "Take The Black Morass from the adult Andormu", optional = true, phases = { from = 1, to = false }, questId = 10296, questName = "The Black Morass", impliedBy = { 10297, 10298 },
      inside = { instance = 269, heroic = false, npcs = { 20201 } },
      places = {
        { role = "start", name = "Andormu", npc = 19932, zone = "Tanaris", map = 1446, x = 57.6, y = 59 },
        { role = "turnin", name = "Sa'at", npc = 20201, zone = "The Black Morass", instance = 269 },
        { role = "inside", name = "The Black Morass", instance = 269 },
      },
      detail = "Not needed for access, but take it before your first run. After Return to Andormu the adult Andormu (a second, level 70 Andormu standing a little south of the child at about 57.6, 59.0) offers The Black Morass. The portal is the south west timeway at about 57.1, 63.1 on the Tanaris map. Inside, Sa'at waits at the entrance; hand in to him for 250 reputation and he gives the next quest. Everyone who wants the Keepers of Time reputation from the dungeon quests needs this." },
    { key = "opening_of_the_dark_portal", kind = "QUEST", title = "Defend Medivh through eighteen waves", optional = true, phases = { from = 1, to = false }, questId = 10297, questName = "The Opening of the Dark Portal", questItem = { id = 24289, name = "Chrono-beacon", count = 1 }, impliedBy = { 10298 },
      inside = { instance = 269, heroic = false, boss = "Aeonus", npcs = { 17879, 17880, 17881, 15608 } },
      places = {
        { role = "start", name = "Sa'at", npc = 20201, zone = "The Black Morass", instance = 269 },
        { role = "turnin", name = "Sa'at", npc = 20201, zone = "The Black Morass", instance = 269 },
        { role = "inside", name = "The Black Morass", instance = 269 },
      },
      detail = "Sa'at hands you a Chrono-beacon. The event starts when someone walks within about ten yards of Medivh at the Dark Portal, after which time rifts open at four points and eighteen waves of infinite dragonkin come for him. Kill each Rift Lord or Rift Keeper fast, because the portal keeps spawning adds until it dies, and keep everything off Medivh's shield. Chrono Lord Deja comes at wave six, Temporus at twelve and Aeonus at eighteen. If Medivh dies the event resets after five minutes and Sa'at gives a new beacon. Return to Sa'at for 500 reputation." },
    { key = "hero_of_the_brood", kind = "QUEST", title = "Report to Andormu as Hero of the Brood", optional = true, phases = { from = 1, to = false }, questId = 10298, questName = "Hero of the Brood",
      places = {
        { role = "start", name = "Sa'at", npc = 20201, zone = "The Black Morass", instance = 269 },
        { role = "turnin", name = "Andormu", npc = 20130, zone = "Tanaris", map = 1446, x = 58.5, y = 54.2 },
      },
      detail = "Sa'at sends you back to the child Andormu with the news. The reward is a choice of Band of the Guardian, Time-bending Gem, Keeper's Ring of Piety or Andormu's Tear plus 8000 Keepers of Time reputation, which is the single biggest reputation payment in the whole Caverns of Time. Heroic Black Morass needs this quest done as well as the Key of Time, so finish it before you buy the key." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "SHADOW_LABYRINTH_KEY", name = "Shadow Labyrinth Key", title = "Shadow Labyrinth Key",
  category = "DUNGEON", order = 20, faction = "BOTH", gate = nil,
  phase = { introduced = 1, requiredUntil = false,
            note = "The normal mode key is needed in every phase; the Zul'Aman update changed heroic keys only." },
  unlock = { items = { 27991 } },
  accountWide = false, minLevel = 65, instance = 555, recurring = false,
  prerequisites = {},
  alternatives = { door = { groups = { { "kill_ikiss", "loot_key" }, { "lockpick_alt" } }, prefer = {} } },
  summary = "The Shadow Labyrinth is the hardest wing of Auchindoun and sits behind a locked gate on the south side of the courtyard. The key is not a quest reward: it waits in the Talon King's Coffer that appears when Talon King Ikiss dies in Sethekk Halls, and every party member who does not yet own one may take one. Only one person in a group needs it, and a rogue with 350 Lockpicking can open the gate instead.",
  unlocks = "Opens the south gate of Auchindoun so your party can enter the Shadow Labyrinth on normal difficulty (heroic additionally needs the Auchenai Key from Lower City reputation).",
  steps = {
    { key = "level_65", kind = "LEVEL", title = "Reach level 65", optional = false, level = 65, phases = { from = 1, to = false },
      detail = "Sethekk Halls is tuned for levels 67 to 69 and the Shadow Labyrinth for 70 (the group finder lists them from 66 and 69), so plan the run at 68 or later. Sethekk Halls is the eastern wing of Auchindoun in the Bone Wastes of Terokkar Forest; the Shadow Labyrinth gate is the southern one in the same courtyard." },
    { key = "kill_ikiss", kind = "KILL", title = "Defeat Talon King Ikiss in Sethekk Halls", optional = false, phases = { from = 1, to = false },
      inside = {
        instance = 556,
        heroic = false,
        boss = "Talon King Ikiss",
        npcs = { 18473 },
        encounters = { 1902 },
        last = true,
      },
      places = {
        { role = "inside", name = "Sethekk Halls", instance = 556 },
      },
      detail = "Enter Sethekk Halls (east wing of Auchindoun, Terokkar Forest, any difficulty) and clear through Darkweaver Syth to the final room, the Halls of Mourning, where Talon King Ikiss waits. Ikiss blinks across the room and follows each blink with a large Arcane Explosion, so spread out, keep health high, and break line of sight behind the pillars when he vanishes; he also polymorphs a random player. Normal mode is enough, and the coffer appears on heroic too. Bring the usual five with a tank, healer and three damage dealers; at 70 in dungeon gear the fight is short." },
    { key = "loot_key", kind = "ITEM", title = "Take the key from the Talon King's Coffer", optional = false, phases = { from = 1, to = false },
      item = { id = 27991, name = "Shadow Labyrinth Key", count = 1 },
      places = {
        { role = "object", name = "The Talon King's Coffer", object = 187372, instance = 556 },
      },
      detail = "When Ikiss dies, The Talon King's Coffer spawns beside his body in the Halls of Mourning. Walk up and open it: it hands a Shadow Labyrinth Key to every party member who does not already own one, so nobody needs to roll. The key binds when picked up, is unique and lives on the keyring. Do not leave the room before everyone has opened the coffer, because a player who misses it must kill Ikiss again on another run." },
    { key = "lockpick_alt", kind = "SKILL", title = "Or bring a rogue with 350 Lockpicking", optional = false, classes = { "ROGUE" }, phases = { from = 1, to = false }, skill = { name = "Lockpicking", line = 633, rank = 350 },
      detail = "The Shadow Labyrinth Gate is a lock-level 350 object, so a rogue whose Lockpicking is 350 can open it for the whole party without any key. This step and the key step are alternatives: either one satisfies the gate. Lockpicking caps at 350 at level 70 and is raised quickly on the locked adamantite chests in Outland dungeons or the footlockers in Zangarmarsh and Netherstorm." },
    { key = "open_gate", kind = "MANUAL", title = "Open the south gate of Auchindoun", optional = true, phases = { from = 1, to = false }, auto = { enteredInstance = 555, heroic = false },
      detail = "Ride into the Auchindoun courtyard in the Bone Wastes of Terokkar Forest (the Ring of Observance, roughly 40, 66 on the zone map) and go to the southern gate at about 39.6, 73.8, which carries the Shadow Labyrinth name. With the key on your keyring simply right-click the gate; it opens for everyone with you, and the instance portal behind it performs no key check of its own. Only one key per party is needed, so one holder can escort a fresh group." },
  },
}
end

do
