    { key = "level_68", kind = "LEVEL", title = "Reach level 68", optional = false, level = 68, phases = { from = 1, to = false },
      detail = "The Primed Key Mold requires level 68 to begin its quest and Hotter than Hell is a level 70 group quest, so start this chain at 68 and expect to finish it at 70. Smith Gorlunk is a level 69 humanoid who can be soloed by most classes at 70, while the Fel Reaver is a level 70 elite that wants a small group." },
