    { key = "entry_into_citadel", kind = "QUEST", title = "Turn in Entry Into the Citadel at your Hellfire base", optional = false, phases = { from = 1, to = false }, questId = { A = 10754, H = 10755 }, questName = "Entry Into the Citadel", impliedBy = { 10762, 10756, 10763, 10757, 10764, 10758 },
      places = {
