    { key = "grand_master_smith", kind = "QUEST", title = "Show the mould to Grand Master Dumphry or Rohok", optional = false, phases = { from = 1, to = false }, questId = { A = 10762, H = 10756 }, questName = { A = "Grand Master Dumphry", H = "Grand Master Rohok" }, impliedBy = { 10763, 10757, 10764, 10758 },
