    { key = "smiths_request", kind = "QUEST", title = "Bring Fel Iron, Arcane Dust and Motes of Fire", optional = false, phases = { from = 1, to = false }, questId = { A = 10763, H = 10757 }, questName = { A = "Dumphry's Request", H = "Rohok's Request" }, impliedBy = { 10764, 10758 },
