    { key = "hotter_than_hell", kind = "QUEST", title = "Fire the mould in a dead Fel Reaver", optional = false, phases = { from = 1, to = false }, questId = { A = 10764, H = 10758 }, questName = "Hotter than Hell", needs = { id = 31252, name = "Charred Key Mold" }, provided = { id = 31251, name = "Unfired Key Mold" },
