          role = "kill",
          name = "Fel Reaver",
          npc = 18733,
          zone = "Hellfire Peninsula",
          map = 1944,
          x = 48,
          y = 55,
        },
      },
      detail = "Hotter than Hell is a level 70 three-player group quest. Find a Fel Reaver, the giant level 70 elite machine that stomps across the whole of Hellfire Peninsula (it has more than five hundred spawn points, from the far west near Expedition Point to the eastern Throne of Kil'jaeden; listen for its roar and look for a giant on the minimap). Pull it with a tank and healer, kill it, and immediately use the Unfired Key Mold while standing at its remains; the mould turns into the Charred Key Mold. Use the mould straight away because the corpse does not last long, and every player on the quest can plunge their own mould into the same corpse. Return the charred mould to the smith and he hands over the Shattered Halls Key." },
    { key = "shattered_halls_key", kind = "ITEM", title = "Hold the Shattered Halls Key", optional = false, phases = { from = 1, to = false },
      item = { id = 28395, name = "Shattered Halls Key", count = 1 },
      detail = "The reward for Hotter than Hell is the Shattered Halls Key, bind-on-pickup, unique, stored on the keyring. One key per party is enough: the locked door stands outside the instance portal, so whoever holds it opens the way and the rest simply walk through. If you destroy it, the smith does not offer the chain again, so keep it on the keyring." },
    { key = "lockpick_alt", kind = "SKILL", title = "Or bring a rogue with 350 Lockpicking", optional = true, classes = { "ROGUE" }, phases = { from = 1, to = false }, skill = { name = "Lockpicking", line = 633, rank = 350 },
      detail = "The Shattered Halls Door is lock level 350, so a level 70 rogue with maxed Lockpicking opens it for the party without the key. This and the key step are alternatives; a group needs one or the other, not both." },
    { key = "open_door", kind = "MANUAL", title = "Open the Shattered Halls door atop Hellfire Citadel", optional = true, phases = { from = 1, to = false }, auto = { enteredInstance = 540, heroic = false },
