      detail = "Khay'ji wants an Arklon Crystal Artifact. Ride south-east from Area 52 to the Arklon Ruins (42, 72), the old draenei ruins on the plateau, and kill Pentatharon, a level 69 dreadlord who patrols among the ruins' demons; he drops the artifact roughly nine times in ten. He is soloable at 68 to 70 with a defensive cooldown, and the ruins are shared with other Area 52 quests so do them in one trip. Return to Khay'ji." },
    { key = "heap_of_ethereals", kind = "QUEST", title = "Collect 10 Zaxxis Insignias at The Heap", optional = false, phases = { from = 1, to = false }, questId = 10262, questName = "A Heap of Ethereals", needs = { id = 29209, name = "Zaxxis Insignia", count = 10 },
      places = {
        {
          role = "start",
          name = "Nether-Stalker Khay'ji",
          npc = 19880,
          zone = "Netherstorm",
          map = 1953,
          x = 32.4,
          y = 64.2,
        },
        {
          role = "turnin",
          name = "Nether-Stalker Khay'ji",
          npc = 19880,
          zone = "Netherstorm",
          map = 1953,
          x = 32.4,
          y = 64.2,
        },
        { role = "spot", name = "The Heap", zone = "Netherstorm", map = 1953, x = 27, y = 79 },
      },
      detail = "Go to The Heap, the ethereal scrapyard south-west of Area 52 (about 26 to 29, 77 to 81), and kill Zaxxis Raiders, Zaxxis Stalkers and Zaxxis Ambushers until you hold 10 Zaxxis Insignias (roughly a 60 percent drop). Do this together with the next step, because Warp-Raider Nesaad lives in the same camp and also carries insignias. Spare insignias are not wasted: Khay'ji later takes them in the repeatable Another Heap of Ethereals for Consortium reputation." },
    { key = "warp_raider_nesaad", kind = "QUEST", title = "Kill Warp-Raider Nesaad", optional = false, phases = { from = 1, to = false }, questId = 10205, questName = "Warp-Raider Nesaad",
      places = {
        {
          role = "start",
          name = "Nether-Stalker Khay'ji",
          npc = 19880,
          zone = "Netherstorm",
          map = 1953,
          x = 32.4,
          y = 64.2,
        },
        {
          role = "turnin",
          name = "Nether-Stalker Khay'ji",
          npc = 19880,
          zone = "Netherstorm",
          map = 1953,
          x = 32.4,
          y = 64.2,
        },
        {
          role = "kill",
          name = "Warp-Raider Nesaad",
          npc = 19641,
          zone = "Netherstorm",
          map = 1953,
          x = 28,
          y = 78.4,
        },
      },
      detail = "Warp-Raider Nesaad is a level 69 ethereal who walks among the Zaxxis at The Heap (28, 78), south-west of Area 52. He hits harder than his guards but is soloable; pull him away from the Stalkers and Ambushers, or kill the nearby pack first. This quest can be taken at the same time as A Heap of Ethereals and the two are done in one visit. Report back to Khay'ji." },
    { key = "request_for_assistance", kind = "QUEST", title = "Report to Gahruj at Eco-Dome Midrealm", optional = false, phases = { from = 1, to = false }, questId = 10266, questName = "Request for Assistance",
      places = {
        {
          role = "start",
          name = "Nether-Stalker Khay'ji",
          npc = 19880,
          zone = "Netherstorm",
          map = 1953,
          x = 32.4,
          y = 64.2,
        },
        { role = "turnin", name = "Gahruj", npc = 20066, zone = "Netherstorm", map = 1953, x = 46.6, y = 57 },
      },
      detail = "Khay'ji sends you to Gahruj at the Midrealm Post, the small Consortium camp just inside the southern entrance of Eco-Dome Midrealm (46.6, 57.0), north-east of Area 52 along the road. Simply speak to him to complete the quest and pick up Rightful Repossession." },
    { key = "rightful_repossession", kind = "QUEST", title = "Recover 10 Boxes of Surveying Equipment at Manaforge Duro", optional = false, phases = { from = 1, to = false }, questId = 10267, questName = "Rightful Repossession", needs = { id = 28913, name = "Box of Surveying Equipment", count = 10 },
      places = {
        { role = "start", name = "Gahruj", npc = 20066, zone = "Netherstorm", map = 1953, x = 46.6, y = 57 },
        { role = "turnin", name = "Gahruj", npc = 20066, zone = "Netherstorm", map = 1953, x = 46.6, y = 57 },
        { role = "spot", name = "Manaforge Duro", zone = "Netherstorm", map = 1953, x = 60, y = 62 },
      },
      detail = "Follow the road south-east out of Eco-Dome Midrealm to Manaforge Duro, the blood elf manaforge on the floating island directly west of Tempest Keep. The Boxes of Surveying Equipment (stackable to 20) are crates lying on the ground around the manaforge and its camps, guarded by Sunfury blood elves of level 68 to 70; loot ten of them. Clear the elves near each crate rather than fighting through the whole base, and pick up the other Duro quests from the Stormspire first if you want to save a trip. Return to Gahruj." },
    { key = "audience_with_prince", kind = "QUEST", title = "Deliver the equipment to the Image of Nexus-Prince Haramad", optional = false, phases = { from = 1, to = false }, questId = 10268, questName = "An Audience with the Prince",
      places = {
        { role = "start", name = "Gahruj", npc = 20066, zone = "Netherstorm", map = 1953, x = 46.6, y = 57 },
        {
          role = "turnin",
          name = "Image of Nexus-Prince Haramad",
          npc = 20084,
          zone = "Netherstorm",
          map = 1953,
          x = 45.8,
          y = 36,
        },
      },
      detail = "Carry the surveying equipment north to the Stormspire, the ethereal city in the middle of northern Netherstorm. Take the ramps to the top; the Image of Nexus-Prince Haramad (45.8, 36.0) floats inside the building beside the flight master. Speak to him to finish the quest; he then gives you the Triangulation Device and the two triangulation quests." },
    { key = "triangulation_one", kind = "QUEST", title = "Find Triangulation Point One near Manaforge Ultris", optional = false, phases = { from = 1, to = false }, questId = 10269, questName = "Triangulation Point One", provided = { id = 29018, name = "Triangulation Device" },
      places = {
        {
          role = "start",
          name = "Image of Nexus-Prince Haramad",
          npc = 20084,
          zone = "Netherstorm",
          map = 1953,
          x = 45.8,
          y = 36,
        },
        {
          role = "turnin",
          name = "Dealer Hazzin",
          npc = 20092,
          zone = "Netherstorm",
          map = 1953,
          x = 58.4,
          y = 31.4,
        },
        { role = "spot", name = "Netherstorm", zone = "Netherstorm", map = 1953, x = 66, y = 33.8 },
      },
      detail = "Fly or ride east from the Stormspire across the bridge to the Manaforge Ultris island. Within about a hundred yards of the first point (roughly 66.0, 33.8, east of the manaforge) use the Triangulation Device (five second cooldown); it faces you toward the point and, once you are close, projects a holographic marker. Walk into the marker to get credit for First triangulation point discovered, then hand in to Dealer Hazzin at the Protectorate Watch Post by the north-west bridge of the island (58.4, 31.4). Watch for the void creatures around Ultris." },
    { key = "triangulation_two", kind = "QUEST", title = "Find Triangulation Point Two near Manaforge Ara", optional = false, phases = { from = 1, to = false }, questId = 10275, questName = "Triangulation Point Two",
      places = {
        {
          role = "start",
          name = "Dealer Hazzin",
          npc = 20092,
          zone = "Netherstorm",
          map = 1953,
          x = 58.4,
          y = 31.4,
        },
        {
          role = "turnin",
          name = "Wind Trader Tuluman",
          npc = 20112,
          zone = "Netherstorm",
          map = 1953,
          x = 34.4,
          y = 38,
        },
        { role = "spot", name = "Netherstorm", zone = "Netherstorm", map = 1953, x = 28.9, y = 41.2 },
      },
      detail = "Cross Netherstorm to the far west: Manaforge Ara sits on the western island, reached by the bridge from Tuluman's Landing. The second point is at roughly 28.9, 41.2 beside the manaforge; use the Triangulation Device again within a hundred yards, follow the arrow, and step into the holographic marker. Then return across the bridge to Wind Trader Tuluman at Tuluman's Landing (34.4, 38.0) to report the second point. Manaforge Ara is full of level 68 to 70 Sunfury and fel orcs, so skirt the edges." },
    { key = "full_triangle", kind = "QUEST", title = "Kill Culuthas for the Ata'mal Crystal", optional = false, phases = { from = 1, to = false }, questId = 10276, questName = "Full Triangle", needs = { id = 29026, name = "Ata'mal Crystal", count = 1 },
      places = {
        {
          role = "start",
          name = "Wind Trader Tuluman",
          npc = 20112,
          zone = "Netherstorm",
          map = 1953,
          x = 34.4,
          y = 38,
        },
        {
          role = "turnin",
          name = "Image of Nexus-Prince Haramad",
          npc = 20084,
          zone = "Netherstorm",
          map = 1953,
          x = 45.8,
          y = 36,
        },
        { role = "kill", name = "Culuthas", npc = 20138, zone = "Netherstorm", map = 1953, x = 53.4, y = 21.4 },
      },
      detail = "The triangle points to the Ruins of Farahlon in north-eastern Netherstorm. Culuthas, a level 70 elite demon, stands among the ruins at about 53.4, 21.4 guarded by packs of Hounds and Eyes of Culuthas (49 to 52, 19 to 25). This is a group quest: bring at least one partner, or a well geared level 70 with cooldowns, and pull Culuthas away from the hounds. He drops the Ata'mal Crystal about nine times in ten. Take the crystal back to the Image of Nexus-Prince Haramad at the Stormspire." },
    { key = "special_delivery", kind = "QUEST", title = "Deliver the Ata'mal Crystal to A'dal in Shattrath", optional = false, phases = { from = 1, to = false }, questId = 10280, questName = "Special Delivery to Shattrath City", provided = { id = 29106, name = "Ata'mal Crystal" },
      places = {
        {
          role = "start",
          name = "Image of Nexus-Prince Haramad",
          npc = 20084,
          zone = "Netherstorm",
          map = 1953,
          x = 45.8,
          y = 36,
        },
        { role = "turnin", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.6 },
      },
      detail = "Haramad asks you to carry the crystal to A'dal, the naaru in the centre of the Terrace of Light in Shattrath City (54.0, 44.6). Take the Stormspire or Area 52 flight path to Shattrath and speak to A'dal; he explains that the crystal is one of the ata'mal shards and offers How to Break Into the Arcatraz." },
    { key = "kill_warp_splinter", kind = "KILL", title = "Kill Warp Splinter in the Botanica for the Top Shard", optional = false, level = 70, phases = { from = 1, to = false }, questId = 10704, needs = { id = 31085, name = "Top Shard of the Arcatraz Key", count = 1 },
      inside = {
        instance = 553,
        heroic = false,
        boss = "Warp Splinter",
        npcs = { 17977 },
        encounters = { 1929 },
        last = true,
      },
      places = {
        { role = "inside", name = "The Botanica", instance = 553 },
      },
      detail = "With How to Break Into the Arcatraz in your log, fly up to the Botanica, the garden satellite of Tempest Keep in eastern Netherstorm, and clear it to the final boss Warp Splinter, a level 72 elite treant. He summons saplings that walk to him and heal him, so kill or kite the saplings away and burn him between summons. He drops the Top Shard of the Arcatraz Key for everyone on the quest. This step and the Mechanar step can be done in either order; both instances are level 70 dungeons (the group finder lists the Mechanar from 68 and the Botanica from 69) and need flying to reach, or a warlock summon." },
    { key = "kill_pathaleon", kind = "KILL", title = "Kill Pathaleon in the Mechanar for the Bottom Shard", optional = false, level = 70, phases = { from = 1, to = false }, questId = 10704, needs = { id = 31086, name = "Bottom Shard of the Arcatraz Key", count = 1 },
      inside = {
        instance = 554,
        heroic = false,
        boss = "Pathaleon the Calculator",
        npcs = { 19220 },
        encounters = { 1931 },
        last = true,
      },
      places = {
        { role = "inside", name = "The Mechanar", instance = 554 },
      },
      detail = "Fly to the Mechanar, the lower satellite of Tempest Keep, and clear it past the Gatewatchers, Nethermancer Sepethrea and the elevator gauntlet to Pathaleon the Calculator, a level 72 elite blood elf. He summons Nether Wraiths that must be killed quickly and later mind-controls a player; at low health he enrages with Disgruntled Anger, so save cooldowns for the end. He drops the Bottom Shard of the Arcatraz Key for everyone on the quest. Do this in either order with the Botanica step." },
    { key = "break_into_arcatraz", kind = "QUEST", title = "Return both shards to A'dal", optional = false, level = 70, phases = { from = 1, to = false }, questId = 10704, questName = "How to Break Into the Arcatraz",
      places = {
        { role = "start", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.6 },
        { role = "turnin", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.6 },
      },
      detail = "Once you hold both the Top and Bottom Shards, return to A'dal on the Terrace of Light. He fuses them into the Key to the Arcatraz and hands it over. This quest requires level 70 and is the last required step; the Arcatraz quest Harbinger of Doom that follows is optional." },
    { key = "arcatraz_key", kind = "ITEM", title = "Hold the Key to the Arcatraz", optional = false, phases = { from = 1, to = false },
      item = { id = 31084, name = "Key to the Arcatraz", count = 1 },
      detail = "The Key to the Arcatraz (bind-on-pickup, unique, keyring) unlocks the Arcatraz satellite of Tempest Keep. One key per party is enough because the locked door stands outside the instance portal. If you ever lose it, A'dal will give a replacement to a character who completed the quest." },
    { key = "lockpick_alt", kind = "SKILL", title = "Or bring a rogue with 350 Lockpicking", optional = false, classes = { "ROGUE" }, phases = { from = 1, to = false }, skill = { name = "Lockpicking", line = 633, rank = 350 },
      detail = "The Arcatraz Door is lock level 350; a level 70 rogue with Lockpicking at 350 opens it for the whole party without the key. This and the key step are alternatives. The rogue still needs flying or a summon to reach the platform." },
    { key = "open_door", kind = "MANUAL", title = "Open the Arcatraz door on Tempest Keep", optional = true, phases = { from = 1, to = false }, auto = { enteredInstance = 552, heroic = false },
      detail = "Tempest Keep is the great naaru fortress in eastern Netherstorm (around 74, 65). Fly up to the Arcatraz satellite, the tallest of the three dungeon platforms; the locked Arcatraz door stands in front of the instance portal on its landing. Right-click it with the key on your keyring and the party can enter. Players without flying can be summoned by a warlock inside, or through the meeting stone once two party members are already on the platform." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "ALDOR_SCRYER_CHOICE", name = "Aldor or Scryers", title = "Shattrath: Choose the Aldor or the Scryers",
  category = "UNLOCK", order = 10, faction = "BOTH", gate = nil,
  phase = { introduced = 1, requiredUntil = false,
            note = "The choice has been open since Phase 1 and is never removed; Draenei lean Aldor and Blood Elves lean Scryers, but either side can be chosen." },
  unlock = nil,
  accountWide = false, minLevel = 60, instance = nil, recurring = false,
  prerequisites = {},
  alternatives = nil,
  summary = "Every character entering Shattrath City is asked to pick a side between the Aldor and the Scryers. The short introduction from the Haggard War Veteran leads to A'dal and Khadgar, whose City of Light tour ends with the two Allegiance quests. The choice sets your starting standing with both factions and decides which quartermaster, inscriptions and later Netherwing and Sunwell quests you will see.",
  unlocks = "Friendly standing with your chosen Shattrath faction (3500 reputation), access to its rise, quartermaster and repeatable turn-ins, and half-value spillover reputation with the Sha'tar up to the top of Friendly.",
  steps = {
    { key = "adal", kind = "QUEST", title = "Speak with A'dal in the Terrace of Light", optional = false, level = 60, phases = { from = 1, to = false }, questId = 10210, questName = "A'dal", impliedBy = { 10211, 10551, 10552, 10554, 10553 },
      places = {
        {
          role = "start",
          name = "Haggard War Veteran",
          npc = 19684,
          zone = "Shattrath City",
          map = 1955,
          x = 72.7,
          y = 55.2,
        },
        { role = "turnin", name = "A'dal", npc = 18481, zone = "Shattrath City", map = 1955, x = 54, y = 44.8 },
      },
      detail = "A Haggard War Veteran stands at each entrance to Shattrath City (south-east gate 72.7, 55.2; also 61.8, 9.9 and 77.2, 43.4) and offers A'dal from level 60. Walk into the Terrace of Light and speak with the naaru A'dal at its centre. The quest pays 10 Sha'tar reputation and opens City of Light." },
    { key = "city_of_light", kind = "QUEST", title = "Follow Khadgar's servant on the City of Light tour", optional = false, phases = { from = 1, to = false }, questId = 10211, questName = "City of Light", impliedBy = { 10551, 10552, 10554, 10553 },
      places = {
        {
          role = "start",
          name = "Khadgar",
          npc = 18166,
          zone = "Shattrath City",
          map = 1955,
          x = 54.8,
          y = 44.3,
        },
        {
          role = "turnin",
          name = "Khadgar",
          npc = 18166,
          zone = "Shattrath City",
          map = 1955,
          x = 54.8,
          y = 44.3,
        },
      },
      detail = "Khadgar stands beside A'dal. Accept City of Light and follow his servant as it walks the whole city, stopping at Lower City, the Aldor Rise and the Scryer's Tier while telling Shattrath's story. The tour takes several minutes and cannot be sped up; stay close to the servant or it waits for you. Return to Khadgar when the credit City of Light appears in your log. This quest is also a hard prerequisite for the Netherwing quest Kill Them All! much later." },
    { key = "allegiance", kind = "QUEST", title = "Pledge allegiance to the Aldor or the Scryers", optional = false, phases = { from = 1, to = false }, questId = 10551, altQuestIds = { 10552 }, questName = { ALDOR = "Allegiance to the Aldor", SCRYER = "Allegiance to the Scryers" }, impliedBy = { 10554, 10553 },
      choice = {
        { questId = 10551, name = "Allegiance to the Aldor", factionId = 932 },
        { questId = 10552, name = "Allegiance to the Scryers", factionId = 934 },
      },
      places = {
        {
          role = "start",
          name = "Khadgar",
          npc = 18166,
          zone = "Shattrath City",
          map = 1955,
          x = 54.8,
          y = 44.3,
        },
        {
          role = "turnin",
          name = "Khadgar",
          npc = 18166,
          zone = "Shattrath City",
          map = 1955,
          x = 54.8,
          y = 44.3,
        },
      },
      detail = "After City of Light Khadgar offers both Allegiance to the Aldor and Allegiance to the Scryers; accepting and completing one locks out the other. Each gives 3500 reputation with the chosen faction, putting you at Friendly, and makes the other side hostile. The Aldor favour priests, paladins and holy-themed inscriptions and sit on the Aldor Rise in the north-west; the Scryers favour blood elf lore and arcane inscriptions and sit on the Scryer's Tier in the south-east. Both sides turn in the same marks later (Marks of Kil'jaeden or Sargeras and Fel Armaments for the Aldor; Firewing or Sunfury Signets and Arcane Tomes for the Scryers). The choice can be reversed later only by grinding the other side back to Neutral through repeatable turn-ins in Lower City (Sha'nir at 64.5, 15.1 for the Aldor; Arcanist Adyria at 55.0, 22.5 for the Scryers), which wipes the first faction's progress." },
    { key = "meet_your_leader", kind = "QUEST", title = "Report to Ishanah or Voren'thal the Seer", optional = true, phases = { from = 1, to = false }, questId = 10554, altQuestIds = { 10553 }, questName = { ALDOR = "Ishanah", SCRYER = "Voren'thal the Seer" },
      places = {
        {
          role = "start",
          name = "Khadgar",
          npc = 18166,
          zone = "Shattrath City",
          map = 1955,
          x = 54.8,
          y = 44.3,
        },
        {
          ALDOR = {
            role = "turnin",
            name = "Ishanah",
            npc = 18538,
            zone = "Shattrath City",
            map = 1955,
            x = 24,
            y = 29.7,
          },
          SCRYER = {
            role = "turnin",
            name = "Voren'thal the Seer",
            npc = 18530,
            zone = "Shattrath City",
            map = 1955,
            x = 42.8,
            y = 91.7,
          },
        },
      },
      detail = "Khadgar immediately follows up with a breadcrumb to your new faction's leader: Ishanah in the Shrine of Unending Light on the Aldor Rise at 24.0, 29.7, or Voren'thal the Seer in the Seer's Library on the Scryer's Tier at 42.8, 91.7. Turning it in pays 10 reputation with your faction and 5 with the Sha'tar and introduces the first real Aldor or Scryer quests in Shattrath, Netherstorm and Shadowmoon Valley." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "OGRILA_UNLOCK", name = "Ogri'la", title = "Ogri'la: the Blade's Edge ogre plateau",
  category = "UNLOCK", order = 20, faction = "BOTH", gate = nil,
  phase = { introduced = 2, requiredUntil = false,
            note = "Ogri'la opened with Phase 2 on 14 May 2026 and is never removed; every quest needs level 70 and a flying mount." },
  unlock = nil,
  accountWide = false, minLevel = 70, instance = nil, recurring = false,
  prerequisites = { { guide = "FLYING", hard = true } },
  alternatives = nil,
  summary = "Mog'dorg the Wizened, atop the tower at the Circle of Blood, sends you after four of Gruul's sons and the warlock Vim'gol before Skulloc Soulgrinder can be destroyed. Only then does he point you to Chu'a'lor at Ogri'la, a plateau in western Blade's Edge reachable only by flying, where The Crystals opens the Apexis relic game, the Skyguard Outpost and four daily quests. Ogri'la reputation is earned almost entirely through those dailies, with Banish the Demons added at Honored.",
  unlocks = "Access to the Ogri'la and Skyguard Outpost daily quests, Apexis Shard and Crystal vendors (Jho'nass) at every standing, Sha'tari Skyguard reputation from the shared dailies, and Exalted gear and tabard.",
  steps = {
    { key = "speak_with_ogre", kind = "QUEST", title = "Hear V'eru's call and find Grok in Lower City", optional = true, phases = { from = 2, to = false }, questId = 10984, questName = "Speak with the Ogre",
      places = {
        { role = "start", name = "V'eru", npc = 22497, zone = "Shattrath City", map = 1955, x = 56.5, y = 49.1 },
        { role = "turnin", name = "Grok", npc = 22940, zone = "Shattrath City", map = 1955, x = 64.9, y = 68.1 },
      },
      detail = "The naaru V'eru in the Terrace of Light offers Speak with the Ogre at level 70. Grok, an ogre in the eastern Lower City near the Scryer's Tier lift, takes it and hands out Mog'dorg the Wizened. This is only a breadcrumb." },
    { key = "mogdorg_wizened", kind = "QUEST", title = "Meet Mog'dorg atop the Circle of Blood tower", optional = false, phases = { from = 2, to = false }, questId = 10983, altQuestIds = { 10989, 11057 }, questName = "Mog'dorg the Wizened",
      places = {
        { role = "start", name = "Grok", npc = 22940, zone = "Shattrath City", map = 1955, x = 64.9, y = 68.1 },
        {
          role = "turnin",
          name = "Mog'dorg the Wizened",
          npc = 22941,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 55.5,
          y = 44.9,
        },
      },
      detail = "Fly to the Circle of Blood arena in central Blade's Edge and land on top of the stone tower at 55.5, 44.9, where Mog'dorg the Wizened waits. Three breadcrumbs lead here and any one of them opens his chain: Mog'dorg the Wizened from Grok, the same-named quest from the ogre Chort beside the tower, or The Trouble Below from Chu'a'lor if you fly straight to Ogri'la first." },
    { key = "grulloc", kind = "QUEST", title = "Take Grulloc's Dragon Skull (group)", optional = false, phases = { from = 2, to = false }, questId = 10995, questName = "Grulloc Has Two Skulls",
      places = {
