        },
      },
      detail = "Mog'dorg hands out Grulloc Has Two Skulls, Maggoc's Treasure Chest and Even Gronn Have Standards together; do them in any order. Grulloc, Son of Gruul, paces the valley east of the Circle of Blood around 60.9, 47.6 and is a five-player elite gronn. Kill him and loot Grulloc's Dragon Skull from the sack he leaves behind. Kiting classes can solo him with patience, but a group is the intended route." },
    { key = "maggoc", kind = "QUEST", title = "Steal Maggoc's Treasure Chest (group)", optional = false, phases = { from = 2, to = false }, questId = 10996, questName = "Maggoc's Treasure Chest",
      places = {
        {
          role = "start",
          name = "Mog'dorg the Wizened",
          npc = 22941,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 55.5,
          y = 44.9,
        },
        {
          role = "turnin",
          name = "Mog'dorg the Wizened",
          npc = 22941,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 55.5,
          y = 44.9,
        },
        {
          role = "kill",
          name = "Maggoc",
          npc = 20600,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 58.6,
          y = 60.8,
        },
      },
      detail = "Maggoc, Son of Gruul, wanders the southern reaches of Blade's Edge near 58.6, 60.8, south of the Circle of Blood toward Mok'Nathal Village. He is another five-player gronn; kill him and take Maggoc's Treasure Chest from the sack he drops. Can be done before or after Grulloc and Slaag." },
    { key = "slaag", kind = "QUEST", title = "Bring Slaag's Standard from the Barrier Hills (group)", optional = false, phases = { from = 2, to = false }, questId = 10997, questName = "Even Gronn Have Standards",
      places = {
        {
          role = "start",
          name = "Mog'dorg the Wizened",
          npc = 22941,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 55.5,
          y = 44.9,
        },
        {
          role = "turnin",
          name = "Mog'dorg the Wizened",
          npc = 22941,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 55.5,
          y = 44.9,
        },
        { role = "kill", name = "Slaag", npc = 22199, zone = "Terokkar Forest", map = 1952, x = 20.2, y = 18.1 },
      },
      detail = "Slaag, Son of Gruul, lives in the Barrier Hills, the plateau above Shattrath City that is reachable only by flying (Terokkar Forest 20.2, 18.1, among the Gordunni ogres). Kill him with a group and loot Slaag's Standard. The Gordunni ogres here are also the targets of the Skyguard quest Threat from Above, so the two guides overlap nicely." },
    { key = "grimoire_business", kind = "QUEST", title = "Summon Vim'gol the Vile for his grimoire (5 players)", optional = false, phases = { from = 2, to = false }, questId = 10998, questName = "Grim(oire) Business",
      places = {
        {
          role = "start",
          name = "Mog'dorg the Wizened",
          npc = 22941,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 55.5,
          y = 44.9,
        },
        {
          role = "turnin",
          name = "Mog'dorg the Wizened",
          npc = 22941,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 55.5,
          y = 44.9,
        },
        {
          role = "kill",
          name = "Vim'gol the Vile",
          npc = 22911,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 77.5,
          y = 31.2,
        },
      },
      detail = "Once all three gronn quests are in, Mog'dorg offers Grim(oire) Business. Fly to Vim'gol's Circle in north-eastern Blade's Edge (77.5, 31.2), a ring of five small summoning circles. Five players must each stand in a circle at the same time to summon Vim'gol the Vile; while he casts Unholy Growth everyone must again stand in the circles to interrupt it. Kill him and loot Vim'gol's Grimoire." },
    { key = "soulgrinder", kind = "QUEST", title = "Destroy Skulloc Soulgrinder (group)", optional = false, phases = { from = 2, to = false }, questId = 11000, questName = "Into the Soulgrinder",
      places = {
        {
          role = "start",
          name = "Mog'dorg the Wizened",
          npc = 22941,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 55.5,
          y = 44.9,
        },
        {
          role = "turnin",
          name = "Mog'dorg the Wizened",
          npc = 22941,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 55.5,
          y = 44.9,
        },
        {
          role = "kill",
          name = "Skulloc Soulgrinder",
          npc = 22910,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 60.7,
          y = 25.5,
        },
      },
      detail = "Take Vim'gol's Grimoire to the Soulgrinder, a great machine north-east of Bladespire Hold at about 60.7, 25.5. Reading the grimoire there calls Skulloc Soulgrinder, a huge gronn spirit, while ogre spirits channel at the surrounding stones. The fight is tuned for a full group of five. Loot Skulloc's Soul and carry it back to Mog'dorg, who then sends you to Ogri'la." },
    { key = "ogre_heaven", kind = "QUEST", title = "Fly to Ogri'la and speak with Chu'a'lor", optional = false, phases = { from = 2, to = false }, questId = 11009, questName = "Ogre Heaven",
      places = {
        {
          role = "start",
          name = "Mog'dorg the Wizened",
          npc = 22941,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 55.5,
          y = 44.9,
        },
        {
          role = "turnin",
          name = "Chu'a'lor",
          npc = 23233,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.8,
          y = 57.4,
        },
      },
      detail = "Ogre Heaven sends you west to Ogri'la, the ogre camp on the high plateau at the western edge of Blade's Edge between Forge Camp: Terror and Forge Camp: Wrath (28.8, 57.4). It can only be reached by flying mount or flight form. Chu'a'lor, the camp leader, takes the quest for 25 reputation. A Bladespire Supplicant near the Circle of Blood tower (55.8, 46.4) also offers the breadcrumb Speak with Mog'dorg if you lose track." },
    { key = "the_crystals", kind = "QUEST", title = "Gather 5 Apexis Shards for The Crystals", optional = false, phases = { from = 2, to = false }, questId = 11025, questName = "The Crystals", questItem = { id = 32569, name = "Apexis Shard", count = 5 },
      places = {
        {
          role = "start",
          name = "Chu'a'lor",
          npc = 23233,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.8,
          y = 57.4,
        },
        {
          role = "turnin",
          name = "Chu'a'lor",
          npc = 23233,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.8,
          y = 57.4,
        },
      },
      detail = "Chu'a'lor asks for 5 Apexis Shards. They drop from almost every mob on the plateau (Apexis Flayers and the demons at the forge camps) and are also looted from the shard piles scattered across the plateau. The turn-in pays 250 Ogri'la reputation and unlocks every other Ogri'la and Skyguard Outpost quest in this guide." },
    { key = "apexis_relic", kind = "QUEST", title = "Win the Apexis Relic game once", optional = false, phases = { from = 2, to = false }, questId = 11058, questName = "An Apexis Relic",
      places = {
        {
          role = "start",
          name = "Chu'a'lor",
          npc = 23233,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.8,
          y = 57.4,
        },
        {
          role = "turnin",
          name = "Chu'a'lor",
          npc = 23233,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.8,
          y = 57.4,
        },
      },
      detail = "Carry an Apexis Shard to any Apexis Relic on the plateau (the glowing pedestals surrounded by four coloured crystals) and start the memory game: repeat the sequence of colours the relic flashes, which grows each round. Four rounds of success grant the Apexis Vibrations buff that completes the quest; failing a round damages you. The first completion pays 250 Ogri'la and 250 Sha'tari Skyguard reputation and unlocks the daily version." },
    { key = "relic_emanation_daily", kind = "QUEST", title = "Daily: The Relic's Emanation (350 Ogri'la)", optional = false, daily = true, phases = { from = 2, to = false }, questId = 11080, questName = "The Relic's Emanation",
      places = {
        {
          role = "start",
          name = "Chu'a'lor",
          npc = 23233,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.8,
          y = 57.4,
        },
        {
          role = "turnin",
          name = "Chu'a'lor",
          npc = 23233,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.8,
          y = 57.4,
        },
      },
      detail = "The daily repeat of the relic game: use one Apexis Shard at a relic and win enough rounds to gain Apexis Emanations, then return to Chu'a'lor for 350 Ogri'la reputation. With a group of five, 35 shards at a relic instead summon a dragon or demon that drops an Apexis Crystal, the currency for Revered and Exalted rewards." },
    { key = "skyguard_ranger", kind = "QUEST", title = "Help Torkus: Our Boy Wants To Be A Skyguard Ranger", optional = false, phases = { from = 2, to = false }, questId = 11030, questName = "Our Boy Wants To Be A Skyguard Ranger",
      places = {
        {
          role = "start",
          name = "Torkus",
          npc = 23316,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.4,
          y = 57.6,
        },
        {
          role = "turnin",
          name = "Torkus",
          npc = 23316,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.4,
          y = 57.6,
        },
      },
      detail = "Torkus, beside Chu'a'lor, wants an Unstable Flask of the Beast. The flasks come from Shard-Hide Boars, Apexis Flayers and the plateau's other beasts, which drop them readily. Pays 250 Ogri'la reputation and is the prerequisite for The Skyguard Outpost, so it is not optional. Its follow-ups A Father's Duty (Unstable Flask of the Sorcerer from the forge camp demons, 250) and A Fel Whip For Gahk (Gahk at 28.5, 58.1, 500) are optional reputation." },
    { key = "skyguard_outpost", kind = "QUEST", title = "Report to Sky Commander Keller at the Skyguard Outpost", optional = false, phases = { from = 2, to = false }, questId = 11062, questName = "The Skyguard Outpost",
      places = {
        {
          role = "start",
          name = "Chu'a'lor",
          npc = 23233,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.8,
          y = 57.4,
        },
        {
          role = "turnin",
          name = "Sky Commander Keller",
          npc = 23334,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 27.4,
          y = 52.7,
        },
      },
      detail = "Chu'a'lor sends you to the Sha'tari Skyguard camp just north of Ogri'la (27.4, 52.7). Sky Commander Keller takes the quest for 10 Skyguard reputation and opens the Outpost's quests: Bombing Run from Sky Sergeant Vanderlip and, through Chu'a'lor, Guardian of the Monument." },
    { key = "guardian_monument", kind = "QUEST", title = "Kill an Apexis Guardian for Guardian of the Monument (group)", optional = false, phases = { from = 2, to = false }, questId = 11059, questName = "Guardian of the Monument",
      places = {
        {
          role = "start",
          name = "Chu'a'lor",
          npc = 23233,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.8,
          y = 57.4,
        },
        {
          role = "turnin",
          name = "Chu'a'lor",
          npc = 23233,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.8,
          y = 57.4,
        },
        {
          role = "kill",
          name = "Apexis Guardian",
          npc = 22275,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 27.4,
          y = 68.6,
        },
      },
      detail = "Take a group of five to an Apexis Monument (the large relic sites at 27.4, 68.6; 31.8, 63.6; 28.4, 46.4; 33.5, 51.5; or far north at 60.0, 9.2; 64.4, 10.4 and 69.2, 14.0), spend 35 Apexis Shards and win six rounds of the relic game; the Apexis Guardian then spawns. Kill it and loot the Apexis Guardian's Head. The turn-in pays 500 Ogri'la and 500 Sha'tari Skyguard reputation, the largest single one-time reward here." },
    { key = "bombing_run", kind = "QUEST", title = "Bomb 15 Fel Cannonball Stacks (Bombing Run)", optional = false, phases = { from = 2, to = false }, questId = 11010, altQuestIds = { 11102 }, questName = "Bombing Run",
      places = {
        {
          role = "start",
          name = "Sky Sergeant Vanderlip",
          npc = 23120,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 27.6,
          y = 52.9,
        },
        {
          role = "turnin",
          name = "Sky Sergeant Vanderlip",
          npc = 23120,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 27.6,
          y = 52.9,
        },
      },
      detail = "Sky Sergeant Vanderlip gives you Skyguard Bombs. Fly over Forge Camp: Wrath (north of Ogri'la) or Forge Camp: Terror (south) and drop a bomb on 15 Fel Cannonball Stacks; the Legion's cannons fire at low fliers, so stay high and dive. Druids receive the flight-form version 11102 instead of 11010. Pays 500 Ogri'la and 500 Skyguard reputation and unlocks the daily Bomb Them Again! and Skyguard Khatie's Wrangle Some Aether Rays!" },
    { key = "bomb_again_daily", kind = "QUEST", title = "Daily: Bomb Them Again! (500 Ogri'la, 500 Skyguard)", optional = false, daily = true, phases = { from = 2, to = false }, questId = 11023, questName = "Bomb Them Again!",
      places = {
        {
          role = "start",
          name = "Sky Sergeant Vanderlip",
          npc = 23120,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 27.6,
          y = 52.9,
        },
        {
          role = "turnin",
          name = "Sky Sergeant Vanderlip",
          npc = 23120,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 27.6,
          y = 52.9,
        },
      },
      detail = "Same run as Bombing Run, every day: 15 Fel Cannonball Stacks at either forge camp. It is the best-paying daily on the plateau for both factions at once, so it anchors the daily loop together with Wrangle More Aether Rays!, The Relic's Emanation and, from Honored, Banish More Demons." },
    { key = "wrangle_rays", kind = "QUEST", title = "Wrangle Some Aether Rays!", optional = false, phases = { from = 2, to = false }, questId = 11065, questName = "Wrangle Some Aether Rays!",
      places = {
        {
          role = "start",
          name = "Skyguard Khatie",
          npc = 23335,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 27.9,
          y = 51.5,
        },
        {
          role = "turnin",
          name = "Skyguard Khatie",
          npc = 23335,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 27.9,
          y = 51.5,
        },
      },
      detail = "Skyguard Khatie gives you a Wrangling Rope. Fight the Aether Rays drifting over the plateau south and east of Ogri'la down to low health, then use the rope on them to leash a ray; lead it back to the Outpost. Five rays complete the quest for 350 Ogri'la and 350 Skyguard reputation, unlocking the daily Wrangle More Aether Rays! (same rewards) and Keller's To Rule The Skies (Dragon Teeth, 500 Skyguard)." },
    { key = "wrangle_more_daily", kind = "QUEST", title = "Daily: Wrangle More Aether Rays! (350 Ogri'la, 350 Skyguard)", optional = false, daily = true, phases = { from = 2, to = false }, questId = 11066, questName = "Wrangle More Aether Rays!",
      places = {
        {
          role = "start",
          name = "Skyguard Khatie",
          npc = 23335,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 27.9,
          y = 51.5,
        },
        {
          role = "turnin",
          name = "Skyguard Khatie",
          npc = 23335,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 27.9,
          y = 51.5,
        },
      },
      detail = "Daily repeat: rope five more Aether Rays back to Khatie for 350 Ogri'la and 350 Sha'tari Skyguard reputation. Combine with Bomb Them Again! and The Relic's Emanation for about 1200 Ogri'la a day before Honored." },
    { key = "friendly", kind = "REP", title = "Reach Friendly with Ogri'la", optional = false, phases = { from = 2, to = false }, factionId = 1038, factionName = "Ogri'la", standing = 5,
      detail = "About two days of dailies from Neutral. Friendly unlocks Jho'nass's Red and Blue Ogre Brew Special and the small thank-you quest A Special Thank You (Chu'a'lor to Jho'nass at 28.1, 58.7, 10 reputation). Jho'nass also sells Crystal Healing and Mana Potions for 50 Apexis Shards and 40 silver each." },
    { key = "honored", kind = "REP", title = "Reach Honored with Ogri'la", optional = false, phases = { from = 2, to = false }, factionId = 1038, factionName = "Ogri'la", standing = 6,
      detail = "Roughly five more days of dailies. Honored adds the Ogre Brews at Jho'nass and, more importantly, unlocks Kronk's Banish the Demons chain, which adds a fourth daily to the loop. Honored with the Sha'tari Skyguard (earned in parallel) also opens the Skyguard flight between Blackwind Landing and Ogri'la." },
    { key = "banish_demons", kind = "QUEST", title = "Banish the Demons at the forge camps (Honored)", optional = false, phases = { from = 2, to = false }, questId = 11026, questName = "Banish the Demons",
      places = {
        {
          role = "start",
          name = "Kronk",
          npc = 23253,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.9,
          y = 57.9,
        },
        {
          role = "turnin",
          name = "Kronk",
          npc = 23253,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.9,
          y = 57.9,
        },
      },
      detail = "Kronk, next to Chu'a'lor, only speaks to Honored allies. He gives a Banishing Crystal: fight the demons at Forge Camp: Wrath or Forge Camp: Terror down to low health and use the crystal to banish them, 15 in all. Pays 350 Ogri'la reputation and unlocks the daily Banish More Demons. The side quest A Crystalforged Darkrune (Gahk) belongs to the Shartuul's Transporter event and is optional." },
    { key = "banish_more_daily", kind = "QUEST", title = "Daily: Banish More Demons (350 Ogri'la)", optional = false, daily = true, phases = { from = 2, to = false }, questId = 11051, questName = "Banish More Demons",
      places = {
        {
          role = "start",
          name = "Kronk",
          npc = 23253,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.9,
          y = 57.9,
        },
        {
          role = "turnin",
          name = "Kronk",
          npc = 23253,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 28.9,
          y = 57.9,
        },
      },
      detail = "Daily repeat of the banishing run for 350 Ogri'la reputation. With all four dailies the plateau pays about 1550 Ogri'la a day, so Revered follows in about eight days and Exalted in about fourteen more." },
    { key = "revered", kind = "REP", title = "Reach Revered with Ogri'la", optional = false, phases = { from = 2, to = false }, factionId = 1038, factionName = "Ogri'la", standing = 7,
      detail = "Revered opens Jho'nass's epic pieces: Apexis Cloak, Crystalforged Trinket, Ogri'la Aegis and Cerulean Crystal Rod, each for 1 Apexis Crystal and 50 Apexis Shards. Crystals come from the 35-shard group summons at any Apexis Relic." },
    { key = "exalted", kind = "REP", title = "Reach Exalted with Ogri'la", optional = false, phases = { from = 2, to = false }, factionId = 1038, factionName = "Ogri'la", standing = 8,
      detail = "Exalted sells the Crystalline Crossbow, Crystal Orb of Enlightenment, Shard-bound Bracers and Vortex Walking Boots for 4 Apexis Crystals and 100 Shards each, plus the Ogri'la Tabard for 10 shards. There is no mount; the Skyguard side of the plateau is where the nether rays come from." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "SKYGUARD_SKETTIS", name = "Sha'tari Skyguard", title = "Sha'tari Skyguard: Skettis and Terokk",
  category = "UNLOCK", order = 30, faction = "BOTH", gate = nil,
  phase = { introduced = 2, requiredUntil = false,
            note = "Skettis opened with Phase 2 on 14 May 2026 and is never removed; every quest needs level 70 and Expert Riding." },
  unlock = nil,
  accountWide = false, minLevel = 70, instance = nil, recurring = false,
  prerequisites = { { guide = "FLYING", hard = true } },
  alternatives = nil,
  summary = "Yuula in Shattrath recruits fliers with Expert Riding to kill ogres in the Barrier Hills, then sends them to Blackwind Landing above Skettis in Terokkar Forest. Two dailies, Fires Over Skettis and Escape from Skettis, carry the reputation, while the Severin and Hazzik chain through the Talonpriests ends with summoning Terokk himself. Skyguard reputation also flows from the Ogri'la plateau quests, and Exalted buys the five nether ray mounts from Grella.",
  unlocks = "Sha'tari Skyguard reputation, the Skyguard flight between Blackwind Landing and Ogri'la at Honored, the Terokk summon, and at Exalted the Riding Nether Ray mounts and Nether Ray Fry pet from Grella.",
  steps = {
    { key = "threat_from_above", kind = "QUEST", title = "Kill 20 Gordunni Ogres in the Barrier Hills", optional = false, phases = { from = 2, to = false }, questId = 11096, questName = "Threat from Above",
      places = {
        { role = "start", name = "Yuula", npc = 23449, zone = "Shattrath City", map = 1955, x = 64.3, y = 42.3 },
        { role = "turnin", name = "Yuula", npc = 23449, zone = "Shattrath City", map = 1955, x = 64.3, y = 42.3 },
      },
      detail = "Yuula, the Skyguard Recruitment Officer beside the Shattrath flight master, offers Threat from Above only to level 70 characters with Expert Riding. Fly up to the Barrier Hills, the plateau directly above Shattrath, and kill any 20 Gordunni Ogres (Slaag, the gronn for the Ogri'la quest Even Gronn Have Standards, roams here too). Return for 250 Skyguard reputation." },
    { key = "to_skettis", kind = "QUEST", title = "Deliver the Explosives Package to Blackwind Landing", optional = false, phases = { from = 2, to = false }, questId = 11098, questName = "To Skettis!",
      places = {
        { role = "start", name = "Yuula", npc = 23449, zone = "Shattrath City", map = 1955, x = 64.3, y = 42.3 },
        {
          role = "turnin",
          name = "Sky Sergeant Doryn",
          npc = 23048,
          zone = "Terokkar Forest",
          map = 1952,
          x = 64.5,
          y = 66.7,
        },
      },
      detail = "Carry the Explosives Package to Sky Sergeant Doryn at Blackwind Landing, the Skyguard camp on the mountain ridge north of Skettis in south-eastern Terokkar Forest (64.5, 66.7). Pays 10 reputation and unlocks the two dailies and the camp's one-time quests." },
    { key = "fires_over_skettis_daily", kind = "QUEST", title = "Daily: Fires Over Skettis (350 Skyguard)", optional = false, daily = true, phases = { from = 2, to = false }, questId = 11008, questName = "Fires Over Skettis",
      places = {
        {
          role = "start",
          name = "Sky Sergeant Doryn",
          npc = 23048,
          zone = "Terokkar Forest",
          map = 1952,
          x = 64.5,
          y = 66.7,
        },
        {
          role = "turnin",
          name = "Sky Sergeant Doryn",
          npc = 23048,
          zone = "Terokkar Forest",
          map = 1952,
          x = 64.5,
          y = 66.7,
        },
      },
      detail = "Doryn gives Skyguard Blasting Charges. Fly low over the arakkoa huts of Skettis and drop charges on the Monstrous Kaliri Eggs sitting on the rooftops; 20 eggs complete it. Monstrous Kaliri birds patrol the air and dismount anyone they catch, so bomb from above and keep moving. 350 reputation a day." },
    { key = "escape_from_skettis_daily", kind = "QUEST", title = "Daily: Escape from Skettis (150 Skyguard)", optional = false, daily = true, phases = { from = 2, to = false }, questId = 11085, questName = "Escape from Skettis",
      places = {
        {
          role = "start",
          name = "Skyguard Prisoner",
          npc = 23383,
          zone = "Terokkar Forest",
          map = 1952,
          x = 68.4,
          y = 74.1,
        },
        {
          role = "turnin",
          name = "Sky Sergeant Doryn",
          npc = 23048,
          zone = "Terokkar Forest",
          map = 1952,
          x = 64.5,
          y = 66.7,
        },
      },
      detail = "A caged Skyguard Prisoner spawns at one of three cages in Skettis (68.4, 74.1; 75.1, 86.3; 61.0, 75.5). Free him and escort him on foot to the exit while arakkoa ambush along the path; stay mounted on the ground to keep pace. Report to Doryn for 150 reputation. Only one escort can be done per day." },
    { key = "hungry_nether_rays", kind = "QUEST", title = "Feed the Hungry Nether Ray", optional = true, phases = { from = 2, to = false }, questId = 11093, questName = "Hungry Nether Rays",
      places = {
        {
          role = "start",
          name = "Skyguard Handler Deesak",
          npc = 23415,
          zone = "Terokkar Forest",
          map = 1952,
          x = 63.5,
          y = 65.8,
        },
        {
          role = "turnin",
          name = "Skyguard Handler Deesak",
          npc = 23415,
          zone = "Terokkar Forest",
          map = 1952,
          x = 63.5,
          y = 65.8,
        },
      },
      detail = "Deesak hands you a Nether Ray Cage. Place it in the woods just south of Blackwind Landing and kill Blackwind Warp Chasers next to the released Hungry Nether Ray so it can feed; ten meals complete it for 250 reputation. One-time only." },
    { key = "world_of_shadows", kind = "QUEST", title = "Collect 6 Shadow Dust for Severin", optional = false, phases = { from = 2, to = false }, questId = 11004, questName = "World of Shadows",
      places = {
        { role = "start", name = "Severin", npc = 23042, zone = "Terokkar Forest", map = 1952, x = 64, y = 66.9 },
        {
          role = "turnin",
          name = "Severin",
          npc = 23042,
          zone = "Terokkar Forest",
          map = 1952,
          x = 64,
          y = 66.9,
        },
      },
      detail = "Severin, the Skyguard Medic, wants 6 Shadow Dust from the arakkoa of Skettis. The dust drops from every arakkoa in the town. He turns it into an Elixir of Shadows, a 20-minute buff that lets you see the shadow arakkoa and the Talonpriests. Pays 250 reputation and unlocks Secrets of the Talonpriests plus the repeatable More Shadow Dust (6 dust for another elixir and 150 reputation)." },
    { key = "secrets_talonpriests", kind = "QUEST", title = "Slay Talonpriests Ishaal, Skizzik and Zellek", optional = false, phases = { from = 2, to = false }, questId = 11005, questName = "Secrets of the Talonpriests",
      places = {
        {
          role = "start",
          name = "Sky Commander Adaris",
          npc = 23038,
          zone = "Terokkar Forest",
          map = 1952,
          x = 64.1,
          y = 66.9,
        },
        {
          role = "turnin",
          name = "Sky Commander Adaris",
          npc = 23038,
          zone = "Terokkar Forest",
          map = 1952,
          x = 64.1,
          y = 66.9,
        },
      },
      detail = "Drink an Elixir of Shadows in Skettis and hunt the three Talonpriests, who are invisible without it: Ishaal, Skizzik and Zellek each stand on a different hut platform in the town. Kill all three and return to Adaris for 250 reputation. Talonpriest Ishaal drops Ishaal's Almanac, which starts the next quest." },
    { key = "ishaals_almanac", kind = "QUEST", title = "Bring Ishaal's Almanac to Adaris", optional = false, phases = { from = 2, to = false }, questId = 11021, questName = "Ishaal's Almanac", questItem = { id = 32523, name = "Ishaal's Almanac", count = 1 },
      places = {
        {
          role = "turnin",
          name = "Sky Commander Adaris",
          npc = 23038,
          zone = "Terokkar Forest",
          map = 1952,
          x = 64.1,
          y = 66.9,
        },
      },
      detail = "Ishaal's Almanac drops from Talonpriest Ishaal and starts a quest when read. Hand it to Sky Commander Adaris for 75 reputation; he cannot decipher it and sends you to Shattrath." },
    { key = "ally_lower_city", kind = "QUEST", title = "Take the almanac to Rilak the Redeemed", optional = false, phases = { from = 2, to = false }, questId = 11024, questName = "An Ally in Lower City",
      places = {
        {
          role = "start",
          name = "Sky Commander Adaris",
          npc = 23038,
          zone = "Terokkar Forest",
          map = 1952,
          x = 64.1,
          y = 66.9,
        },
        {
          role = "turnin",
          name = "Rilak the Redeemed",
          npc = 22292,
          zone = "Shattrath City",
          map = 1955,
          x = 52.5,
          y = 21,
        },
      },
      detail = "Fly to Shattrath and find Rilak the Redeemed, the arakkoa in the north-western Lower City (52.5, 21.0). He reads the almanac and warns that Terokk's return is near. 75 reputation." },
    { key = "countdown_to_doom", kind = "QUEST", title = "Return to Adaris with news of Terokk", optional = false, phases = { from = 2, to = false }, questId = 11028, questName = "Countdown to Doom",
      places = {
        {
          role = "start",
          name = "Rilak the Redeemed",
          npc = 22292,
          zone = "Shattrath City",
          map = 1955,
          x = 52.5,
          y = 21,
        },
        {
          role = "turnin",
          name = "Sky Commander Adaris",
          npc = 23038,
          zone = "Terokkar Forest",
          map = 1952,
          x = 64.1,
          y = 66.9,
        },
      },
      detail = "Carry Rilak's warning back to Sky Commander Adaris at Blackwind Landing for 75 reputation. Adaris passes you to Hazzik, the arakkoa defector standing in the camp." },
    { key = "hazziks_bargain", kind = "QUEST", title = "Fetch Hazzik's Package from eastern Skettis", optional = false, phases = { from = 2, to = false }, questId = 11056, questName = "Hazzik's Bargain",
      places = {
        { role = "start", name = "Hazzik", npc = 23306, zone = "Terokkar Forest", map = 1952, x = 64.2, y = 67 },
        { role = "turnin", name = "Hazzik", npc = 23306, zone = "Terokkar Forest", map = 1952, x = 64.2, y = 67 },
      },
      detail = "Hazzik wants the package he left in his old dwelling in eastern Skettis. Fly to the eastern huts, loot Hazzik's Package from inside and bring it back. 75 reputation." },
    { key = "shabby_disguise", kind = "QUEST", title = "Use the Shabby Arakkoa Disguise on Sahaak", optional = false, phases = { from = 2, to = false }, questId = 11029, questName = "A Shabby Disguise",
      places = {
        { role = "start", name = "Hazzik", npc = 23306, zone = "Terokkar Forest", map = 1952, x = 64.2, y = 67 },
        { role = "turnin", name = "Hazzik", npc = 23306, zone = "Terokkar Forest", map = 1952, x = 64.2, y = 67 },
      },
      detail = "Put on the Shabby Arakkoa Disguise in Skettis and walk, not fly, to the arakkoa Sahaak, who guards the Adversarial Bloodlines scroll on one of the central platforms. In disguise he will talk to you and hand over the Bloodlines; attacking or mounting breaks the disguise. 150 reputation." },
    { key = "adversarial_blood", kind = "QUEST", title = "Summon and defeat the four descendants (group)", optional = false, phases = { from = 2, to = false }, questId = 11885, altQuestIds = { 11072 }, questName = "Adversarial Blood", questItem = { id = 32620, name = "Time-Lost Scroll", count = 40 },
      places = {
        { role = "start", name = "Hazzik", npc = 23306, zone = "Terokkar Forest", map = 1952, x = 64.2, y = 67 },
        { role = "turnin", name = "Hazzik", npc = 23306, zone = "Terokkar Forest", map = 1952, x = 64.2, y = 67 },
      },
      detail = "Collect Time-Lost Scrolls from the time-lost arakkoa, the shadowy ones visible only under the Elixir of Shadows. Ten scrolls used at the Skull Pile in the middle of a Skettis summoning circle call one of Terokk's adversaries' descendants: Akkarai, Karrog, Gezzarak the Huntress and Vakkiz the Windrager, each a group-worth elite. Kill all four (Darkscreecher Akkarai, Karrog, Gezzarak the Huntress, Vakkiz the Windrager) and return to Hazzik for 350 reputation; the live quest 11885 counts the kills (whole group gets credit) and needs no tokens. The tokens (Akkarai's Talons, Karrog's Spine, Gezzarak's Claws, Vakkiz's Scale) are only turned in for the repeatable Tokens of the Descendants (350 reputation), which lets you repeat the summons for more reputation." },
    { key = "terokks_downfall", kind = "QUEST", title = "Summon and defeat Terokk (group)", optional = false, phases = { from = 2, to = false }, questId = 11073, questName = "Terokk's Downfall", questItem = { id = 32720, name = "Time-Lost Offering", count = 1 },
      places = {
        {
          role = "start",
          name = "Sky Commander Adaris",
          npc = 23038,
          zone = "Terokkar Forest",
          map = 1952,
          x = 64.1,
          y = 66.9,
        },
        {
          role = "turnin",
          name = "Sky Commander Adaris",
          npc = 23038,
          zone = "Terokkar Forest",
          map = 1952,
          x = 64.1,
          y = 66.9,
        },
        { role = "kill", name = "Terokk", npc = 21838, zone = "Terokkar Forest", map = 1952, x = 66.2, y = 77.5 },
      },
      detail = "Hazzik prepares a Time-Lost Offering. Use it at the Ancient Skull Pile on Terokk's Rest, the island summoning circle in Blackwind Lake at the centre of Skettis (66.2, 77.5), to call Terokk, a level 72 elite meant for five players. He casts Shadow Bolt Volley, marks a Chosen One, and at low health shields himself; drag him into the blue smoke where Skyguard bombers strike to shatter the shield before his Frenzy ends the fight. Loot includes the Time-Lost Figurine; the turn-in pays 1000 Skyguard reputation." },
    { key = "honored", kind = "REP", title = "Reach Honored with the Sha'tari Skyguard", optional = false, phases = { from = 2, to = false }, factionId = 1031, factionName = "Sha'tari Skyguard", standing = 6,
      detail = "Honored unlocks Skyguard Rations at Grella and the Skyguard flight path between Blackwind Landing and the Skyguard Outpost at Ogri'la. The Ogri'la plateau quests pay Skyguard reputation at the same time as Ogri'la reputation, so running both hubs is the fastest route." },
    { key = "revered", kind = "REP", title = "Reach Revered with the Sha'tari Skyguard", optional = false, phases = { from = 2, to = false }, factionId = 1031, factionName = "Sha'tari Skyguard", standing = 7,
      detail = "Revered opens the two cloaks at Grella: Skyguard's Drape and Skywitch's Drape." },
    { key = "exalted", kind = "REP", title = "Reach Exalted and buy a Riding Nether Ray", optional = false, phases = { from = 2, to = false }, factionId = 1031, factionName = "Sha'tari Skyguard", standing = 8,
      item = { anyOf = { 32314, 32316, 32317, 32318, 32319 } },
      detail = "Grella, Skyguard Quartermaster at Blackwind Landing (64.3, 66.2), sells the Green, Purple, Red, Silver and Blue Riding Nether Rays for 160 gold at Exalted (200 gold before the standing discount), the Nether Ray Fry pet (40 gold; added in patch 2.4.3, so not before the Sunwell phase on Anniversary), the Skyguard Silver Cross, Airman's Ribbon of Gallantry and the Skyguard Tabard. The rays are 280 percent mounts and need Artisan Riding." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "NETHERWING_DAILIES", name = "Netherwing", title = "Netherwing: from Mordenai to a Nether Drake",
  category = "UNLOCK", order = 40, faction = "BOTH", gate = nil,
  phase = { introduced = 3, requiredUntil = false,
            note = "Netherwing opened with Phase 3 on 27 Aug 2026 and is never removed; the Blood Oath needs Artisan Riding." },
