    { key = "neltharakus_tale", kind = "QUEST", title = "Listen to Neltharaku's Tale", optional = false, phases = { from = 3, to = false }, questId = 10814, questName = "Neltharaku's Tale",
      places = {
        {
          role = "start",
          name = "Neltharaku",
          npc = 21657,
          zone = "Shadowmoon Valley",
