    { key = "ally_of_netherwing", kind = "QUEST", title = "Return to Mordenai as Ally of the Netherwing", optional = false, phases = { from = 3, to = false }, questId = 10870, altQuestIds = { 10871 }, questName = "Ally of the Netherwing",
