    { key = "artisan_riding_gate", kind = "SKILL", title = "Have Artisan Riding (300) before the Blood Oath", optional = false, phases = { from = 3, to = false }, spellId = 34091, skill = { name = "Riding", line = 762, rank = 300 },
      detail = "Blood Oath of the Netherwing and Enter the Taskmaster both carry a Riding 300 requirement in the quest data; Mordenai will not offer the oath without it. See the Flying guide for trainers and costs." },
    { key = "blood_oath", kind = "QUEST", title = "Swear the Blood Oath of the Netherwing", optional = false, phases = { from = 3, to = false }, questId = 11012, questName = "Blood Oath of the Netherwing",
