      },
      detail = "Yarzill, a goblin at the camp who is secretly a Netherwing drake in disguise, reveals himself after In Service of the Illidari. Turning in his quest opens A Slow Death, The Not-So-Friendly Skies..., The Great Netherwing Egg Hunt and, at Friendly, Rise, Overseer!" },
    { key = "neutral_dailies", kind = "QUEST", title = "Daily loop at Neutral: Netherwing Crystals and friends", optional = false, daily = true, phases = { from = 3, to = false }, questId = 11015, questName = "Netherwing Crystals", related = { dailies = { 11016, 11017, 11018, 11020, 11035 } },
      places = {
        {
          role = "start",
          name = "Taskmaster Varkule Dragonbreath",
          npc = 23140,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 66.1,
          y = 86.4,
        },
        {
          role = "turnin",
          name = "Taskmaster Varkule Dragonbreath",
          npc = 23140,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 66.1,
          y = 86.4,
        },
      },
      detail = "From Neutral the dailies are: Netherwing Crystals (30 crystals from mobs and nodes on the ledge, 250); one gathering daily matched to your profession at 350 skill, Nethercite Ore (Mining), Netherdust Pollen (Herbalism) or Nethermine Flayer Hide (Skinning), 250 each; Yarzill's A Slow Death (poison 12 Dragonmaw Peon Camps with Yarzill's Mutton and Fel Glands from the flayers, 250); and The Not-So-Friendly Skies... (shoot down Dragonmaw Transporters with the flare gun and loot 10 Netherwing Relics, 250). Each is 250 reputation a day." },
    { key = "egg_hunt", kind = "QUEST", title = "Find a Netherwing Egg and keep handing them in", optional = false, phases = { from = 3, to = false }, questId = 11049, questName = "The Great Netherwing Egg Hunt", questItem = { id = 32506, name = "Netherwing Egg", count = 1 },
      places = {
        {
          role = "start",
          name = "Yarzill the Merc",
          npc = 23141,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 66,
          y = 86.5,
        },
        {
          role = "turnin",
          name = "Yarzill the Merc",
          npc = 23141,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 66,
          y = 86.5,
        },
      },
      detail = "Netherwing Eggs spawn randomly on the ledge, in the Netherwing Mines and in Dragonmaw Fortress, and occasionally drop from mobs or gathering nodes. The first egg completes The Great Netherwing Egg Hunt for 350 reputation; after that Accepting All Eggs takes every further egg for 250 each with no daily limit, which is the fastest way to shorten the grind." },
    { key = "friendly", kind = "REP", title = "Reach Friendly with the Netherwing", optional = false, phases = { from = 3, to = false }, factionId = 1015, factionName = "Netherwing", standing = 5,
      detail = "About one day of dailies after the chain. Friendly unlocks Rise, Overseer!, the Netherwing Mines dailies and the Booterang daily, lifting the daily income to roughly 1800 a day." },
    { key = "rise_overseer", kind = "QUEST", title = "Rise, Overseer! (Friendly)", optional = false, phases = { from = 3, to = false }, questId = 11053, questName = "Rise, Overseer!",
      places = {
        {
          role = "start",
          name = "Taskmaster Varkule Dragonbreath",
