          map = 1948,
          x = 66.3,
          y = 85.6,
        },
      },
      detail = "At Friendly the Taskmaster promotes you: speak with Overlord Mor'ghor for 250 reputation and the Overseer's Badge, a trinket that summons a Dragonmaw peon to fight for you in Shadowmoon Valley. The promotion opens Chief Overseer Mudlump's quests and The Netherwing Mines." },
    { key = "overseeing_booterang", kind = "QUEST", title = "Overseeing and You, then the daily Booterang", optional = false, phases = { from = 3, to = false }, questId = 11054, questName = "Overseeing and You: Making the Right Choices", related = { dailies = { 11055 } },
      places = {
        {
