        },
        {
          role = "turnin",
          name = "Chief Overseer Mudlump",
          npc = 23291,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 66.9,
          y = 86.1,
        },
      },
      detail = "Mudlump wants 10 Knothide Leather and a Hardened Hide of Tyrantus (Tyrantus is the elite devilsaur in Netherstorm's Eco-Dome Farfield; the hide is also sold on the auction house). Turning it in (250) gives you the Booterang and unlocks the daily The Booterang: A Cure For The Common Worthless Peon (350 reputation): throw it at 20 lazy or sleeping Dragonmaw Peons around the mines and camp." },
    { key = "netherwing_mines", kind = "QUEST", title = "The Netherwing Mines and its dailies", optional = false, phases = { from = 3, to = false }, questId = 11075, questName = "The Netherwing Mines", related = { dailies = { 11076, 11077 } },
      places = {
