      detail = "Speak with Mor'ghor for 500 reputation and the Captain's Badge, whose peon follows you in every zone. Opens Disrupting the Twilight Portal, Illidari Lord Balthas's Soul Cannon quests and Ja'y Nosliw's Earning Your Wings..." },
    { key = "twilight_portal_daily", kind = "QUEST", title = "Daily: Disrupting the Twilight Portal (500)", optional = false, daily = true, phases = { from = 3, to = false }, questId = 11086, questName = "Disrupting the Twilight Portal",
