    { key = "dragonmaw_races", kind = "QUEST", title = "Win the six Dragonmaw Races", optional = true, phases = { from = 3, to = false }, questId = 11063, questName = "Earning Your Wings...", related = { quests = { 11064, 11067, 11068, 11069, 11070, 11071 } },
      places = {
        {
          role = "start",
          name = "Ja'y Nosliw",
