        },
        {
          role = "turnin",
          name = "Ja'y Nosliw",
          npc = 22433,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 65.9,
          y = 87.2,
        },
      },
      detail = "Ja'y Nosliw, the Skybreaker General, challenges you to six flying races against his riders, who stand in a line at about 65.2, 85 and each hand out their race: The Ballad of Oldie McOld (350 reputation), Trope the Filth-Belcher (350 reputation), Corlok the Vet (500 reputation), Wing Commander Ichman (500 reputation), Wing Commander Mulverick (500 reputation) and Captain Skyshatter (1000 reputation). Follow the racer closely as he flies a course over Shadowmoon Valley while dropping bombs and fire on you; falling too far behind fails the race. Each race must be won in order and reported to Ja'y. Together they pay 3200 reputation." },
    { key = "revered", kind = "REP", title = "Reach Revered with the Netherwing", optional = false, phases = { from = 3, to = false }, factionId = 1015, factionName = "Netherwing", standing = 7,
      detail = "Revered (around day seven) promotes you to Commander and adds the Shattrath-faction quests and the group daily The Deadliest Trap Ever Laid." },
