      detail = "Speak with Mor'ghor for 500 reputation and the Commander's Badge (45 Stamina trinket). This unlocks Kill Them All!" },
    { key = "kill_them_all", kind = "QUEST", title = "Kill Them All! and the Commander (Aldor or Scryers)", optional = false, phases = { from = 3, to = false }, questId = 11099, altQuestIds = { 11094 }, questName = "Kill Them All!",
