      detail = "Anchorite Ceyla (Aldor) or Arcanist Thelis (Scryers) sends you on to the officer who commands the outpost's defenders: Commander Arcus at the Altar of Sha'tar for the Aldor, Commander Hobb at the Sanctum of the Stars for the Scryers. He takes the warning and hands you the Dragonmaw Flare for the daily that follows. No reputation." },
    { key = "deadliest_trap_daily", kind = "QUEST", title = "Daily group quest: The Deadliest Trap Ever Laid (500)", optional = false, daily = true, phases = { from = 3, to = false }, questId = 11101, altQuestIds = { 11097 }, questName = "The Deadliest Trap Ever Laid",
