          y = 85.6,
        },
      },
      detail = "Fire the flare gun at the Altar of Sha'tar (Aldor) or the Sanctum of the Stars (Scryers) to call the Dragonmaw assault, then help the defenders kill every wave of Dragonmaw forces. The waves hit hard and the quest is tagged for a group. Bring the Aldor Medals or Scryer Medals back to Mor'ghor, who believes the attack failed; 500 reputation a day." },
    { key = "exalted", kind = "REP", title = "Reach Exalted with the Netherwing", optional = false, phases = { from = 3, to = false }, factionId = 1015, factionName = "Netherwing", standing = 8,
      detail = "Exalted, usually two weeks after the chain if every daily is done (fewer with eggs), unlocks Bow to the Highlord. Drake Dealer Hurlunk (at the camp 65.6, 85.9) also opens his stock of all six Reins of the Netherwing Drake." },
    { key = "bow_to_highlord", kind = "QUEST", title = "Bow to the Highlord and meet Illidan", optional = false, phases = { from = 3, to = false }, questId = 11107, questName = "Bow to the Highlord",
      places = {
        {
          role = "start",
          name = "Taskmaster Varkule Dragonbreath",
          npc = 23140,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 66.1,
          y = 86.4,
