        {
          role = "turnin",
          name = "Overlord Mor'ghor",
          npc = 23139,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 66.3,
          y = 85.6,
        },
      },
      detail = "Speak with Mor'ghor, then accept Lord Illidan Stormrage: Illidan lands at the camp, sees through your disguise and the Netherwing drakes rise against the Dragonmaw in a scripted scene that ends with Mor'ghor dead and you flung into the air; a drake catches you and the quest credit Meeting with Illidan Stormrage is granted. Lord Illidan Stormrage pays 1000 reputation and sends you to Barthamus on the ridge above Shattrath's Lower City (66.6, 16.4)." },
    { key = "lord_illidan", kind = "QUEST", title = "Lord Illidan Stormrage: survive the scene, find Barthamus", optional = false, phases = { from = 3, to = false }, questId = 11108, questName = "Lord Illidan Stormrage",
      places = {
        {
          role = "start",
          name = "Overlord Mor'ghor",
          npc = 23139,
          zone = "Shadowmoon Valley",
          map = 1948,
          x = 66.3,
          y = 85.6,
