          zone = "Shattrath City",
          map = 1955,
          x = 66.6,
          y = 16.4,
        },
      },
      detail = "Accept Lord Illidan Stormrage from Mor'ghor at Exalted. Illidan lands at the camp, sees through your disguise and the Netherwing drakes rise against the Dragonmaw in a scripted scene that ends with Mor'ghor dead and you flung into the air; a drake catches you and sets you down. Hand in to Barthamus on the ridge above Shattrath's Lower City (66.6, 16.4) for 1000 reputation; the six drake quests all require it." },
    { key = "choose_drake", kind = "QUEST", title = "Choose your free Netherwing drake in Shattrath", optional = false, phases = { from = 3, to = false }, questId = 11109, altQuestIds = { 11110, 11111, 11112, 11113, 11114 }, questName = "Jorus the Cobalt Netherwing Drake",
      item = { anyOf = { 32857, 32858, 32859, 32860, 32861, 32862 } },
      places = {
        { role = "start", name = "Jorus", npc = 23462, zone = "Shattrath City", map = 1955, x = 67.9, y = 17 },
        { role = "turnin", name = "Jorus", npc = 23462, zone = "Shattrath City", map = 1955, x = 67.9, y = 17 },
      },
      detail = "Six Netherwing drakes rest beside Barthamus on the ridge above Shattrath (66 to 68, 17 to 19). Each offers its own quest and completing one rewards that drake's reins while locking out the other five: Jorus (Cobalt), Malfas (Purple), Onyxien (Onyx), Suraku (Azure), Voranaku (Violet) and Zoya (Veridian). The remaining colours can be bought from Drake Dealer Hurlunk at Dragonmaw Base Camp for 200 gold each (160 with the Exalted discount). The drakes are 280 percent mounts and need Artisan Riding." },
  },
}
