do
D.guides[#D.guides + 1] = {
  key = "SHATTERED_SUN_OFFENSIVE", name = "Shattered Sun Offensive", title = "Shattered Sun Offensive: Isle of Quel'Danas",
  category = "UNLOCK", order = 50, faction = "BOTH", gate = nil,
  phase = { introduced = 5, requiredUntil = false,
