    { key = "intro_shattrath", kind = "QUEST", title = "Crisis at the Sunwell or Duty Calls", optional = false, phases = { from = 5, to = false }, questId = 11481, altQuestIds = { 11482 }, questName = { ALDOR = "Crisis at the Sunwell", SCRYER = "Duty Calls" },
