      places = {
        {
          role = "start",
          name = "Exarch Larethor",
          npc = 24813,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 47.4,
          y = 30.7,
        },
        { role = "turnin", name = "Tyrith", npc = 24822, zone = "Magisters' Terrace", instance = 585 },
        { role = "inside", name = "Magisters' Terrace", instance = 585 },
      },
      detail = "Larethor sends you into normal Magisters' Terrace (entrance 61.2, 30.9) to find the spy Tyrith (turn in to Tyrith inside, 250), who passes you to Kalecgos in The Scryer's Scryer (250 reputation). Kalecgos's Hard to Kill (250 reputation) asks for the Head of Kael'thas from the final boss on normal difficulty and, when turned in to Larethor, grants access to Heroic Magisters' Terrace. The Lower City dailies Wanted: The Signet Ring of Prince Kael'thas (heroic only, 350) and Wanted: Sisters of Torment (250 reputation) then pay Shattered Sun and Lower City reputation, and a heroic clear is worth about 2800 reputation. Magisters' Terrace is handed in to Tyrith inside the instance; Exarch Larethor only gives it." },
    { key = "scryers_scryer", kind = "QUEST", title = "Use the Scrying Orb and speak with Kalecgos", optional = true, phases = { from = 5, to = false }, questId = 11490, questName = "The Scryer's Scryer",
      inside = { instance = 585, heroic = false, npcs = { 24848 } },
      places = {
        { role = "start", name = "Tyrith", npc = 24822, zone = "Magisters' Terrace", instance = 585 },
