        { role = "inside", name = "Magisters' Terrace", instance = 585 },
      },
      detail = "Tyrith wants you to activate the Scrying Orb on the open balcony further into the dungeon, past Vexallus. Clear to the orb and use it; an image of Kalecgos appears in his half elven form and shows Kael'thas scheming at the top of the Terrace. Speak to Kalecgos to complete the quest for 250 reputation and take Hard to Kill from him before the image fades." },
    { key = "hard_to_kill", kind = "QUEST", title = "Kill Kael'thas and bring his head to Larethor", optional = true, phases = { from = 5, to = false }, questId = 11492, questName = "Hard to Kill", questItem = { id = 34157, name = "Head of Kael'thas", count = 1 },
      inside = { instance = 585, heroic = false, boss = "Kael'thas Sunstrider", npcs = { 24664 } },
      places = {
        { role = "start", name = "Kalecgos", npc = 24848, zone = "Magisters' Terrace", instance = 585 },
        {
          role = "turnin",
          name = "Exarch Larethor",
          npc = 24813,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 47.4,
          y = 30.7,
        },
        { role = "inside", name = "Magisters' Terrace", instance = 585 },
      },
      detail = "Kill Kael'thas Sunstrider at the top of Magisters' Terrace on normal difficulty, after Priestess Delrissa's party, and loot the Head of Kael'thas. Kael'thas casts Flame Strike, summons a Phoenix that must be killed and its egg destroyed, and at low health begins Gravity Lapse, lifting everyone into the air; swim away from his Arcane Spheres and keep damage going. Take the head back to Exarch Larethor at the Shattered Sun Staging Area for 250 reputation and 19 gold 58 silver (4g40s base plus the 15g18s level-70 conversion; the quest is level 70 only, so the player always receives the full amount) and a choice of a Bright Crimson Spinel, a Runed Crimson Spinel or a Teardrop Crimson Spinel. Completing this quest is the heroic attunement itself; no key item exists." },
    { key = "stage1_sanctum", kind = "QUEST", title = "Daily: Erratic Behavior (Stage 1, the Sanctum)", optional = false, daily = true, phases = { from = 5, to = false }, questId = 11524, questName = "Erratic Behavior", related = { dailies = { 11496, 11525, 11523 } },
      places = {
        {
          role = "start",
          name = "Vindicator Xayann",
          npc = 24965,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 47.1,
          y = 30.7,
        },
        {
          role = "turnin",
          name = "Vindicator Xayann",
          npc = 24965,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 47.1,
          y = 30.7,
        },
      },
      detail = "The first realm objective is the Sanctum. Two progress dailies advance it: Erratic Behavior (Vindicator Xayann: place Attuned Crystal Cores in 5 defeated Erratic Sentries, 150) and The Sanctum Wards (Captain Theris Dawnhearth at 47.5, 30.6: 4 Mana Remnants from Wretched Fiends and Devourers, then energize a Crystal Ward, 150). When the realm finishes the Sanctum these are replaced by the permanent dailies Further Conversions and Arm the Wards!, same tasks and rewards. Also from day one: The Missing Magistrix (Theris Dawnhearth, 75) leads through the portal at Dawning Square to Magistrix Seyla at the Throne of Kil'jaeden in Hellfire Peninsula (58.2, 17.6), who offers the Outland dailies Blood for Blood (250 reputation) and Blast the Gateway (250 reputation)." },
    { key = "stage2_armory", kind = "QUEST", title = "Daily: The Battle for the Sun's Reach Armory (Stage 2)", optional = false, daily = true, phases = { from = 5, to = false }, questId = 11538, questName = "The Battle for the Sun's Reach Armory", related = { dailies = { 11532, 11537, 11533 } },
      places = {
        {
          role = "start",
          name = "Harbinger Inuuro",
          npc = 25061,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 47.6,
          y = 35.1,
        },
        {
          role = "turnin",
          name = "Harbinger Inuuro",
          npc = 25061,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 47.6,
          y = 35.1,
        },
      },
      detail = "After the Sanctum the quest givers move inside it and the Armory becomes the objective. Progress dailies: The Battle for the Sun's Reach Armory (Harbinger Inuuro: 6 Burning Legion demons and impale the Emissary of Hate with the Shattered Sun Banner, 250) and Distraction at the Dead Scar (Battlemage Arynna at 47.5, 35.1: ride Ayren Cloudbreaker's dragonhawk over the Dead Scar and bomb 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers with Arcane Charges, 150). Completion replaces them with The Battle Must Go On (250 reputation) and The Air Strikes Must Continue (150 reputation) and opens the Armory's Exotic Gear Purveyors (badge and token gear)." },
    { key = "stage2b_portal", kind = "QUEST", title = "Daily: Intercepting the Mana Cells (Stage 2b, the portal)", optional = false, daily = true, phases = { from = 5, to = false }, questId = 11513, questName = "Intercepting the Mana Cells", related = { dailies = { 11514, 11547, 11517, 11534 } },
      places = {
        {
          role = "start",
          name = "Exarch Nasuun",
          npc = 24932,
          zone = "Shattrath City",
          map = 1955,
          x = 49.1,
          y = 42.5,
        },
        {
          role = "turnin",
          name = "Exarch Nasuun",
          npc = 24932,
          zone = "Shattrath City",
          map = 1955,
          x = 49.1,
          y = 42.5,
        },
      },
      detail = "Once the Armory is taken, Tradesman Portanuus on the isle (47.3, 35.0) offers the breadcrumb Report to Nasuun (10 reputation). Exarch Nasuun on the Terrace of Light in Shattrath gives the progress daily Intercepting the Mana Cells (use the Bash'ir Phasing Device at Bash'ir Landing in Blade's Edge Mountains to loot 10 Smuggled Mana Cells, 250). Enough realm completions open the one-way portal from Shattrath (the alcove behind Nasuun) to the Sun's Reach Sanctum, after which the daily becomes Maintaining the Sunwell Portal (250 reputation) and Astromancer Darnarian in the Sanctum (47.5, 35.4) adds Know Your Ley Lines (250 reputation), which rewards a one-use scroll back to Shattrath." },
    { key = "stage3_harbor", kind = "QUEST", title = "Daily: Intercept the Reinforcements (Stage 3, the harbour)", optional = false, daily = true, phases = { from = 5, to = false }, questId = 11542, questName = "Intercept the Reinforcements", related = { dailies = { 11539, 11543, 11540 } },
      places = {
        {
          role = "start",
          name = "Vindicator Kaalan",
          npc = 25108,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 50.6,
          y = 39,
        },
        {
          role = "turnin",
          name = "Vindicator Kaalan",
          npc = 25108,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 50.6,
          y = 39,
        },
      },
      detail = "Progress dailies from the Armory: Intercept the Reinforcements (Vindicator Kaalan: ride Ayren Cloudbreaker's dragonhawk and burn the sails of the Sin'loren, Bloodoath and Dawnchaser with Flaming Oil, then kill 6 Dawnblade Reservists, 250) and Taking the Harbor (Magister Ilastar at 49.3, 40.4: 6 Dawnblade Summoners, 6 Blood Knights, 3 Marksmen, 250). When the Harbor falls they become Keeping the Enemy at Bay (250 reputation) and Crush the Dawnblade (250 reputation), and Captain Valindria aboard the Silvermoon's Pride (53.8, 34.3) adds Disrupt the Greengill Coast (free 10 Greengill Slaves with the Orb of Murloc Control, 250)." },
    { key = "stage3b_anvil", kind = "QUEST", title = "Daily: Making Ready (Stage 3b, Hauthaa's anvil)", optional = false, daily = true, phases = { from = 5, to = false }, questId = 11535, questName = "Making Ready", related = { dailies = { 11536, 11544 } },
      places = {
        {
          role = "start",
          name = "Smith Hauthaa",
          npc = 25046,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 50.6,
          y = 40.8,
        },
        {
          role = "turnin",
          name = "Smith Hauthaa",
          npc = 25046,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 50.6,
          y = 40.8,
        },
      },
      detail = "Smith Hauthaa behind the Armory offers the progress daily Making Ready (kill Darkspine Myrmidons on the eastern shore, take their keys and loot 3 Darkspine Iron Ore from their chests, 250). When the realm completes the anvil she becomes the Badge of Justice vendor and the daily turns into Don't Stop Now.... (250 reputation) plus Ata'mal Armaments (collect 5 Ata'mal Armaments from the Ashtongue in Shadowmoon Valley and cleanse them on her anvil, 350; rewards a weapon coating)." },
    { key = "stage4_alchemy_lab", kind = "QUEST", title = "Daily: Discovering Your Roots (Stage 4, the Alchemy Lab)", optional = false, daily = true, phases = { from = 5, to = false }, questId = 11520, questName = "Discovering Your Roots", related = { dailies = { 11521, 11546 } },
      places = {
        {
          role = "start",
          name = "Mar'nah",
          npc = 24975,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 51.5,
          y = 32.5,
        },
        {
          role = "turnin",
          name = "Mar'nah",
          npc = 24975,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 51.5,
          y = 32.5,
        },
      },
      detail = "Mar'nah the alchemist at Sun's Reach Harbor gives the progress daily Discovering Your Roots (fly to Razorthorn Rise in Terokkar Forest, use Razorthorn Flayer Glands to make the flayers dig up 5 Razorthorn Roots, 350). When the lab is built it becomes Rediscovering Your Roots (350 reputation) and Open for Business (5 Bloodberries from bushes on the isle, 250, rewards a Bloodberry Elixir). Shaani (51.5, 32.5) then sells epic gems and jewelcrafting designs." },
    { key = "stage4b_monument", kind = "QUEST", title = "Daily: A Charitable Donation (Stage 4b, the Monument)", optional = false, daily = true, phases = { from = 5, to = false }, questId = 11545, questName = "A Charitable Donation", related = { dailies = { 11548 } },
      places = {
        {
          role = "start",
          name = "Anchorite Ayuri",
          npc = 25112,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 48.6,
          y = 37.7,
        },
        {
          role = "turnin",
          name = "Anchorite Ayuri",
          npc = 25112,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 48.6,
          y = 37.7,
        },
      },
      detail = "Anchorite Ayuri at Sun's Reach takes a 10 gold donation a day: A Charitable Donation (150 reputation) while the monument is being raised, then Your Continued Support (150 reputation) afterwards. Both stop being offered at Exalted. The finished monument grants a buff to everyone on the isle. A Charitable Donation is a daily worth 150 reputation and is offered only below Exalted." },
    { key = "outland_dailies", kind = "QUEST", title = "Outland dailies: Sunfury Attack Plans and company", optional = true, daily = true, phases = { from = 5, to = false }, questId = 11877, questName = "Sunfury Attack Plans", related = { dailies = { 11875, 11880, 11515, 11516 } },
      places = {
        {
          role = "start",
          name = "Lord Torvos",
          npc = 25140,
          zone = "Shattrath City",
          map = 1955,
          x = 62.8,
          y = 36,
        },
        {
          role = "turnin",
          name = "Lord Torvos",
          npc = 25140,
          zone = "Shattrath City",
          map = 1955,
          x = 62.8,
          y = 36,
        },
      },
      detail = "Three Shattrath dailies pay 250 each from the start of the phase: Sunfury Attack Plans (Lord Torvos: loot the plans from Sunfury blood elves in Netherstorm), Gaining the Advantage (Emissary Mordin at 62.8, 35.6: 8 Nether Residue gathered with Herbalism, Mining or Skinning in Outland; gatherers only) and The Multiphase Survey (Harbinger Haronem at 61.6, 52.2: 6 readings with the Multiphase Spectrographic Goggles around Oshu'gun in Nagrand). With Blood for Blood and Blast the Gateway from Magistrix Seyla these add 1250 a day on top of the isle." },
    { key = "friendly", kind = "REP", title = "Reach Friendly with the Shattered Sun Offensive", optional = false, phases = { from = 5, to = false }, factionId = 1077, factionName = "Shattered Sun Offensive", standing = 5,
      detail = "Everyone starts Neutral. Friendly unlocks Naaru Rations at Eldara Dawnrunner, the quartermaster near the staging area (47.2, 30.8)." },
    { key = "honored", kind = "REP", title = "Reach Honored with the Shattered Sun Offensive", optional = false, phases = { from = 5, to = false }, factionId = 1077, factionName = "Shattered Sun Offensive", standing = 6,
      detail = "Honored unlocks the enchanting formulas (Void Shatter, Enchant Chest - Defense) and the first jewelcrafting designs at Eldara Dawnrunner." },
    { key = "revered", kind = "REP", title = "Reach Revered with the Shattered Sun Offensive", optional = false, phases = { from = 5, to = false }, factionId = 1077, factionName = "Shattered Sun Offensive", standing = 7,
      detail = "Revered opens the weapon list (Legionfoe, Seeker's Gavel, Archmage's Guile, Truestrike Crossbow, K'iru's Presage, Bombardier's Blade, The Sunbreaker, Inuuro's Blade) and the meta-gem and figurine designs." },
    { key = "exalted", kind = "REP", title = "Reach Exalted with the Shattered Sun Offensive", optional = false, phases = { from = 5, to = false }, factionId = 1077, factionName = "Shattered Sun Offensive", standing = 8,
      detail = "Exalted sells the Sunward Crest and Dawnforged Defender shields, the Shattered Sun Pendants of Acumen, Might, Resolve and Restoration, the four Alchemist Stone recipes and the Tabard of the Shattered Sun (1 gold). About 20 dailies a day plus heroic Magisters' Terrace make this a two to three week grind." },
    { key = "title_quest", kind = "QUEST", title = "Donate 1000 gold for the title of the Shattered Sun", optional = true, phases = { from = 5, to = false }, questId = 11549, questName = "A Magnanimous Benefactor",
      places = {
        {
          role = "start",
          name = "Anchorite Kairthos",
          npc = 25163,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 51.2,
          y = 33.1,
        },
        {
          role = "turnin",
          name = "Anchorite Kairthos",
          npc = 25163,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 51.2,
          y = 33.1,
        },
      },
      detail = "At Exalted, Anchorite Kairthos at Sun's Reach Harbor offers A Magnanimous Benefactor: donate 1000 gold to Anchorite Ayuri's cause. The quest text itself promises the title of the Shattered Sun on completion, plus a final 500 reputation. It is one-time and the title is the only way to earn it. A Magnanimous Benefactor needs Exalted, is one-time, pays 500 reputation and grants the title of the Shattered Sun." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "FLYING", name = "Flying", title = "Flying: Expert and Artisan Riding",
  category = "FLYING", order = 10, faction = "BOTH", gate = nil,
  phase = { introduced = 1, requiredUntil = false,
            note = "Flying has been available at level 70 since Phase 1; Swift Flight Form for druids came with Phase 2." },
  unlock = nil,
  accountWide = false, minLevel = 68, instance = nil, recurring = false,
  prerequisites = {},
  alternatives = {
    flight60 = { groups = { { "expert_riding", "flying_mount" }, { "flight_form" } }, prefer = { DRUID = 2 } },
    flight280 = {
      groups = { { "artisan_riding", "epic_flying_mount" }, { "artisan_riding", "swift_flight_form" } },
      prefer = { DRUID = 2 },
    },
  },
  summary = "Outland flight is bought in two steps from the riding trainers in Shadowmoon Valley at level 70. Expert Riding (225) and a 60 percent mount open the sky; Artisan Riding (300) and a 280 percent mount are the real investment at roughly 5200 gold. The Netherwing, Skyguard and Ogri'la daily hubs all assume you can fly, and the Netherwing Blood Oath refuses you without Artisan Riding.",
  unlocks = "Riding skill 300 and an epic flying mount, which satisfy the Blood Oath of the Netherwing requirement, the Skyguard Skettis quests (225) and let you reach the Ogri'la plateau and Netherwing Ledge.",
  steps = {
    { key = "level_70", kind = "LEVEL", title = "Reach level 70, or 68 as a druid", optional = false, level = 70, levelByClass = { DRUID = 68 }, phases = { from = 1, to = false },
      detail = "Both flying ranks require level 70. Journeyman Riding (150) is also a prerequisite for Expert Riding, so finish your 60 percent ground mount training first. Save gold while levelling: Expert Riding plus a mount is 900 gold and Artisan Riding plus an epic mount is 5200 gold." },
    { key = "learning_to_fly", kind = "QUEST", title = "Take Nutral's breadcrumb to the riding trainer", optional = true, phases = { from = 4, to = false }, questId = { A = 11497, H = 11498 }, questName = "Learning to Fly",
      places = {
        { role = "start", name = "Nutral", npc = 18940, zone = "Shattrath City", map = 1955, x = 64.1, y = 41.1 },
        {
          A = {
            role = "turnin",
            name = "Ilsa Blusterbrew",
            npc = 20511,
            zone = "Shadowmoon Valley",
            map = 1948,
            x = 37.5,
            y = 56.3,
          },
          H = {
            role = "turnin",
            name = "Olrokk",
            npc = 20500,
            zone = "Shadowmoon Valley",
            map = 1948,
            x = 29.3,
            y = 29.3,
          },
        },
      },
      detail = "Nutral hands out Learning to Fly at level 70 only to characters who have not yet trained Expert Riding. The quest was added in patch 2.3.0, so on Anniversary realms it exists from Phase 4 (22 October 2026), not from launch. It points Alliance players to Ilsa Blusterbrew at Wildhammer Stronghold and Horde players to Olrokk at Shadowmoon Village. It is only a signpost and gives no riding skill; skip it if you already know where the trainers are." },
    { key = "expert_riding", kind = "SKILL", title = "Train Expert Riding (225) for 800 gold", optional = false, phases = { from = 1, to = false }, cost = "800 gold", spellId = 34090, skill = { name = "Riding", line = 762, rank = 225 },
      places = {
        {
          A = {
            role = "trainer",
            name = "Ilsa Blusterbrew",
            npc = 20511,
            zone = "Shadowmoon Valley",
            map = 1948,
            x = 37.4,
            y = 56.2,
          },
          H = {
            role = "trainer",
            name = "Olrokk",
            npc = 20500,
            zone = "Shadowmoon Valley",
            map = 1948,
            x = 29.2,
            y = 29.2,
          },
        },
      },
      detail = "Travel to Shadowmoon Valley. Alliance players learn Expert Riding from Ilsa Blusterbrew at the gryphon stables of Wildhammer Stronghold (37.4, 56.2); Horde players from Olrokk at the wyvern stables of Shadowmoon Village (29.2, 29.2). The skill costs 800 gold at level 70 and raises riding to 225, which allows 60 percent speed flight in Outland only. On the Anniversary client there are no flying trainers in Hellfire Peninsula: Hargen Bronzewing and Wind Rider Jahubo were added in Wrath patch 3.2 and do not exist on this client. Artisan Riding (5000 gold) is the later upgrade to 280 percent flight. No reputation discount applies to Expert or Artisan Riding on this client; faction discounts for flying trainers only arrived in patch 3.2.0." },
    { key = "flying_mount", kind = "ITEM", title = "Buy a 60 percent flying mount, or better", optional = false, phases = { from = 1, to = false }, cost = "100 gold",
      item = {
        count = 1,
        anyOf = {
          A = { 25470, 25471, 25472, 34060, 25473, 25527, 25528, 25529, 32857, 32858, 32859, 32860, 32861, 32862, 32314, 32316, 32317, 32318, 32319, 33999, 32458, 34061 },
          H = { 25474, 25475, 25476, 34060, 25477, 25531, 25532, 25533, 32857, 32858, 32859, 32860, 32861, 32862, 32314, 32316, 32317, 32318, 32319, 33999, 32458, 34061 },
        },
        name = "a flying mount",
      },
      places = {
        {
          A = {
            role = "vendor",
            name = "Brunn Flamebeard",
            npc = 20510,
            zone = "Shadowmoon Valley",
            map = 1948,
            x = 37.4,
            y = 56,
          },
          H = {
            role = "vendor",
            name = "Dama Wildmane",
            npc = 20494,
            zone = "Shadowmoon Valley",
            map = 1948,
            x = 29.2,
            y = 29.4,
          },
        },
      },
      detail = "The mount vendor stands beside the trainer. Brunn Flamebeard at Wildhammer Stronghold sells the Golden, Ebon and Snowy Gryphons to the Alliance, and Dama Wildmane at Shadowmoon Village sells the Tawny, Blue and Green Windriders to the Horde; each costs 100 gold and needs riding skill 225. The mount is an item on the TBC client, so keep it in your bags; using it casts the matching summon spell. Engineers at 350 can build a Flying Machine Control instead. The epic 280 percent mounts cost 200 gold on top of Artisan Riding." },
    { key = "flight_form", kind = "SPELL", title = "Druids: learn Flight Form at 68 instead", optional = false, classes = { "DRUID" }, phases = { from = 1, to = false }, spellId = 33943,
      detail = "Druids train Flight Form from any druid trainer at level 68 for a few gold; it is an instant shapeshift giving 60 percent flight in Outland and does not require Expert Riding on the TBC client. A druid with Flight Form can skip the trainer and the mount purchase entirely and still reach Tempest Keep. Swift Flight Form (280 percent) at level 70 needs Artisan Riding plus the Phase 2 quest chain." },
    { key = "artisan_riding", kind = "SKILL", title = "Train Artisan Riding (300) for 5000 gold", optional = false, level = 70, phases = { from = 1, to = false }, spellId = 34091, skill = { name = "Riding", line = 762, rank = 300 },
      places = {
        {
          A = {
            role = "trainer",
            name = "Ilsa Blusterbrew",
            npc = 20511,
            zone = "Shadowmoon Valley",
            map = 1948,
            x = 37.5,
            y = 56.3,
          },
          H = {
            role = "trainer",
            name = "Olrokk",
            npc = 20500,
            zone = "Shadowmoon Valley",
            map = 1948,
            x = 29.3,
            y = 29.3,
          },
        },
      },
      detail = "The same two trainers teach Artisan Riding for 5000 gold once you have Expert Riding and are level 70. It raises flight speed to 280 percent and is the single requirement that Blood Oath of the Netherwing checks. No faction discount applies. Budget for the mount too, since the skill alone does not change your 60 percent mount." },
    { key = "epic_flying_mount", kind = "ITEM", title = "Buy a 280 percent flying mount", optional = false, level = 70, phases = { from = 1, to = false },
      item = {
        name = "a 280 percent flying mount",
        count = 1,
        anyOf = {
          A = { 25473, 25527, 25528, 25529, 32857, 32858, 32859, 32860, 32861, 32862, 32314, 32316, 32317, 32318, 32319, 33999, 32458, 34061 },
          H = { 25477, 25531, 25532, 25533, 32857, 32858, 32859, 32860, 32861, 32862, 32314, 32316, 32317, 32318, 32319, 33999, 32458, 34061 },
        },
      },
      places = {
        {
          A = {
            role = "vendor",
            name = "Brunn Flamebeard",
            npc = 20510,
            zone = "Shadowmoon Valley",
            map = 1948,
            x = 37.6,
            y = 56,
          },
          H = {
            role = "vendor",
            name = "Dama Wildmane",
            npc = 20494,
            zone = "Shadowmoon Valley",
            map = 1948,
            x = 29.1,
            y = 29.5,
          },
        },
      },
      detail = "Brunn Flamebeard sells the Swift Blue, Red, Green and Purple Gryphons; Dama Wildmane sells the Swift Red, Green, Yellow and Purple Windriders. Each is 200 gold. Later alternatives at the same speed are the Netherwing drakes (one free from Barthamus at Netherwing Exalted, the rest from Drake Dealer Hurlunk), the Skyguard nether rays (160 gold at Skyguard Exalted from Grella) and the Cenarion War Hippogryph." },
    { key = "swift_flight_form", kind = "SPELL", title = "Druids: learn Swift Flight Form instead of a 280 mount", optional = false, level = 70, classes = { "DRUID" }, phases = { from = 2, to = false }, spellId = 40120,
      detail = "Druids at level 70 who hold Artisan Riding can learn Swift Flight Form, 280 percent flight, through the quest chain that begins with Morthis Whisperwing at the Cenarion Refuge and ends with Anzu in heroic Sethekk Halls; it came with Phase 2 and replaces the epic mount purchase. Artisan Riding is still required." },
    { key = "reach_tempest_keep", kind = "MANUAL", title = "Fly to the Tempest Keep dungeon platforms", optional = true, note = true, phases = { from = 1, to = false },
      places = {
        { role = "spot", name = "Tempest Keep", zone = "Netherstorm", map = 1953, x = 74, y = 65 },
      },
      detail = "Tempest Keep floats in eastern Netherstorm (around 74, 65) and its three satellites hold the Mechanar, the Botanica and the Arcatraz, all three tuned for level 70 (group finder from 68-69; the door level lock is not verified). There is no ground path: mount up and fly to the platform in front of the portal you need, with the Arcatraz being the highest. Players without flying can be summoned by a warlock already inside, or through the meeting stone once two group members stand on the platform, as was true on original TBC from patch 2.4 and remains true on the Anniversary realms. The Botanica and Mechanar are also where the Arcatraz key shards and the second Karazhan key fragment pieces come from." },
  },
}
end

do
D.guides[#D.guides + 1] = {
  key = "BADGES", name = "Badges of Justice", title = "Badges of Justice: where they drop and what to buy, phase by phase",
  category = "BADGES", order = 10, faction = "BOTH", gate = nil,
  phase = { introduced = 1, requiredUntil = false,
            note = "Badges of Justice are earned every lockout; where they drop and what G'eras sells change with each phase." },
  unlock = nil,
  accountWide = false, minLevel = 70, instance = nil, recurring = true,
  prerequisites = {},
  alternatives = nil,
  summary = "Badges of Justice drop from every heroic dungeon boss and from Wind Trader Zhareem's heroic daily in every phase; from the Zul'Aman update every boss in Karazhan, Zul'Aman, Gruul's Lair, Magtheridon's Lair, Serpentshrine Cavern and Tempest Keep drops them too, as do Doom Lord Kazzak and Doomwalker, and the Sunwell phase adds Magisters' Terrace and the Isle of Quel'Danas vendors. This guide never finishes: it lists what to earn each lockout and what G'eras and the Isle vendors sell this phase.",
  unlocks = "G'eras's catalogue in Shattrath, expanded in Phase 4, and the Sunwell tier gear, gems and PvP pieces of the Isle of Quel'Danas vendors in Phase 5.",
  steps = {
    { key = "heroic_daily", kind = "QUEST", title = "Do Zhareem's heroic daily: 2 badges", optional = false, daily = true, phases = { from = 1, to = 5 }, questIds = { 11354, 11362, 11363, 11368, 11369, 11370, 11372, 11373, 11374, 11375, 11378, 11382, 11384, 11386, 11388, 11499 }, questMode = "ANY", questName = "Wanted",
      places = {
        {
          role = "start",
          name = "Wind Trader Zhareem",
          npc = 24369,
          zone = "Shattrath City",
          map = 1955,
          x = 75.1,
          y = 36.7,
        },
        {
          role = "turnin",
          name = "Wind Trader Zhareem",
          npc = 24369,
          zone = "Shattrath City",
          map = 1955,
          x = 75.1,
          y = 36.7,
        },
      },
      detail = "Each day Wind Trader Zhareem in Shattrath's Lower City offers one random Wanted quest that is completable only on Heroic difficulty and pays 2 Badges of Justice, gold and 350 reputation with the Consortium and the dungeon's faction. The pool is one quest per heroic: Nazan's Riding Crop (Ramparts), Keli'dan's Feathered Stave (Blood Furnace), Bladefist's Seal (Shattered Halls), The Heart of Quagmirran (Slave Pens), A Black Stalker Egg (Underbog), The Warlord's Treatise (Steamvault), The Headfeathers of Ikiss (Sethekk), Shaffar's Wondrous Pendant (Mana-Tombs), The Exarch's Soul Gem (Auchenai Crypts), Murmur's Whisper (Shadow Labyrinth), The Epoch Hunter's Head (Old Hillsbrad), Aeonus's Hourglass (Black Morass), A Warp Splinter Clipping (Botanica), Pathaleon's Projector (Mechanar) and The Scroll of Skyriss (Arcatraz). The item drops from the end boss, so the daily is also a full heroic clear worth 2 to 5 more badges. Nether-Stalker Mah'duun's normal daily next to him pays an Ethereum Prison Key, not badges. Seven dailies a week is 14 badges on its own." },
    { key = "heroics_overview", kind = "MANUAL", title = "Lap the heroics: 1 badge per boss", optional = false, note = true, phases = { from = 1, to = false },
      list = {
        { name = "Hellfire Ramparts", instance = 543, badges = 3 },
        { name = "The Blood Furnace", instance = 542, badges = 3 },
        { name = "The Shattered Halls", instance = 540, badges = 4, bonus = 1 },
        { name = "The Slave Pens", instance = 547, badges = 3 },
        { name = "The Underbog", instance = 546, badges = 4 },
        { name = "The Steamvault", instance = 545, badges = 3 },
        { name = "Mana-Tombs", instance = 557, badges = 3, bonus = 1 },
        { name = "Auchenai Crypts", instance = 558, badges = 2 },
        { name = "Sethekk Halls", instance = 556, badges = 2, bonus = 1 },
        { name = "Shadow Labyrinth", instance = 555, badges = 4 },
        { name = "Old Hillsbrad Foothills", instance = 560, badges = 3 },
        { name = "The Black Morass", instance = 269, badges = 3 },
        { name = "The Mechanar", instance = 554, badges = 4 },
        { name = "The Botanica", instance = 553, badges = 5 },
        { name = "The Arcatraz", instance = 552, badges = 4 },
        { name = "Magisters' Terrace", instance = 585, badges = 4, from = 5 },
      },
      detailByPhase = {
        [1] = "Every boss in a heroic dungeon drops exactly one Badge of Justice for each player, and each heroic can be entered once per day per character. Full-clear totals: Ramparts 3, Blood Furnace 3, Shattered Halls 4 (5 if the Shattered Hand Executioner is killed before he executes the prisoners), Slave Pens 3, Underbog 4, Steamvault 3, Mana-Tombs 3 (4 with Yor), Auchenai Crypts 2, Sethekk Halls 2 (3 with Anzu), Shadow Labyrinth 4, Old Hillsbrad 3, Black Morass 3, Mechanar 4, Botanica 5 and Arcatraz 4, which is 50 badges for one lap of all fifteen or 53 with the bonus bosses. In Phase 1 heroic keys still need Revered with the dungeon's faction (Honor Hold or Thrallmar, Cenarion Expedition, Lower City, Keepers of Time, the Sha'tar). Pick the dungeons with the most badges per hour: Mechanar, Botanica, Shattered Halls, Underbog, Shadow Labyrinth and Arcatraz.",
        [2] = "Every heroic boss still drops one badge per player and every heroic locks once a day. Totals per full clear: Ramparts 3, Blood Furnace 3, Shattered Halls 4 plus 1 for the Executioner, Slave Pens 3, Underbog 4, Steamvault 3, Mana-Tombs 3 plus 1 for Yor, Auchenai Crypts 2, Sethekk 2 plus 1 for Anzu, Shadow Labyrinth 4, Old Hillsbrad 3, Black Morass 3, Mechanar 4, Botanica 5, Arcatraz 4: 50 badges for the lap, 53 with bonus bosses. Phase 2 raiders in SSC and TK gear clear Mechanar, Botanica, Arcatraz, Underbog and Shadow Labyrinth quickly, so those five are the badge-per-hour picks. Karazhan, Gruul, Magtheridon, SSC and TK drop no badges in this phase.",
        [3] = "One badge per heroic boss, one lockout per heroic per day. Full-clear totals are unchanged: Ramparts 3, Blood Furnace 3, Shattered Halls 4 (plus the Executioner), Slave Pens 3, Underbog 4, Steamvault 3, Mana-Tombs 3 (plus Yor), Auchenai Crypts 2, Sethekk 2 (plus Anzu), Shadow Labyrinth 4, Old Hillsbrad 3, Black Morass 3, Mechanar 4, Botanica 5, Arcatraz 4, so 50 for the lap and 53 with the bonus bosses. Tier 5 and Tier 6 groups can chain Mechanar, Botanica, Arcatraz, Underbog and Shadow Labyrinth in under three hours for 21 badges. Hyjal and Black Temple bosses drop no badges in this phase.",
        [4] = "Heroics are unchanged at one badge per boss (50 for a full lap, 53 with Yor, Anzu and the Executioner) but Phase 4 lowers the key requirement to Honored and tunes every heroic to its final 2.4.3 difficulty, so alts and fresh 70s can join the badge economy at once. With raids now paying, heroics become the top-up: Mechanar (4), Botanica (5) and Shattered Halls (5) remain the best per hour.",
        [5] = "Sixteen heroics now, one badge per boss and one lockout each per day: the fifteen Outland heroics total 50 (53 with Yor, Anzu and the Executioner) and Magisters' Terrace adds 4. Keys need Honored. With raids paying most of the weekly total, heroics are the fill-in for off-nights and the way alts catch up; Magisters' Terrace, Mechanar and Botanica are the best per hour.",
      } },
    { key = "heroic_mechanar", kind = "KILL", title = "Clear heroic Mechanar: 4 badges", optional = true, weekly = true, phases = { from = 1, to = 1 },
      inside = {
        instance = 554,
        heroic = true,
        boss = "Pathaleon the Calculator",
        npcs = { 19220 },
        encounters = { 1931 },
        last = true,
      },
      places = {
        { role = "inside", name = "The Mechanar", instance = 554 },
      },
      detail = "The Mechanar is the fastest heroic for a geared five: Gatewatcher Gyro-Kill, Gatewatcher Iron-Hand, Nethermancer Sepethrea and Pathaleon the Calculator each drop a badge, four in about half an hour. Entry needs the Warpforged Key from the Sha'tar. Pathaleon's Projector drops from the last boss. Bring interrupts for the Sunseeker Astromages and kill the Legion Cache groups cleanly before the Sepethrea stairs." },
    { key = "heroic_botanica", kind = "KILL", title = "Clear heroic Botanica: 5 badges", optional = true, weekly = true, phases = { from = 1, to = 1 },
      inside = {
        instance = 553,
        heroic = true,
        boss = "Warp Splinter",
        npcs = { 17977 },
        encounters = { 1929 },
        last = true,
      },
      places = {
        { role = "inside", name = "The Botanica", instance = 553 },
      },
      detail = "The Botanica has five bosses (Commander Sarannis, High Botanist Freywinn, Thorngrin the Tender, Laj, Warp Splinter), the most badges of any heroic, though the long corridors make it slower than Mechanar. A Warp Splinter Clipping drops from Warp Splinter. Crowd control the Sunseeker Gene-Splicers and keep the tank away from Thorngrin's Sacrifice. Sha'tar Revered (Phase 1 to 3) for the Warpforged Key." },
    { key = "heroic_shattered_halls", kind = "KILL", title = "Heroic Shattered Halls: 4 badges, 5 with the Executioner", optional = true, weekly = true, phases = { from = 1, to = 1 },
      inside = {
        instance = 540,
        heroic = true,
        boss = "Warchief Kargath Bladefist",
        npcs = { 16808, 20923, 17301 },
        encounters = { 1938 },
        last = true,
      },
      places = {
        { role = "inside", name = "The Shattered Halls", instance = 540 },
      },
      detail = "Heroic Shattered Halls adds Blood Guard Porung as a fourth boss alongside Grand Warlock Nethekurse, Warbringer O'mrogg and Warchief Kargath Bladefist, four badges. The Shattered Hand Executioner in the final gauntlet drops a fifth badge if he is killed before the 55 minute timer executes the hostages, which also completes the Trial of the Naaru: Mercy quest. Bladefist's Seal drops from Kargath. This is the hardest heroic in Phase 1; bring two interrupts and a solid tank for the Legionnaire packs." },
    { key = "bonus_bosses", kind = "KILL", title = "Add the three optional bosses: Yor, Anzu, the Executioner", optional = true, weekly = true, phases = { from = 1, to = 3 },
      inside = { instance = 557, heroic = true, boss = "Yor", npcs = { 22930, 23035, 17301 }, encounters = { 250 } },
      places = {
        { role = "inside", name = "Mana-Tombs", instance = 557 },
      },
      detail = "Three heroic bosses only exist if you bring the right key or class. Yor is released from Shaffar's personal stasis chamber in Nexus-Prince Shaffar's room (in front of him, at the end of the instance) with The Eye of Haramad (the permanent key from quest 10982 at Consortium Exalted) or a single-use Shaffar's Stasis Chamber Key from the repeatable quest 10981 (one Mark of the Nexus-King each), and drops a badge. Anzu in heroic Sethekk Halls is summoned by a druid who has completed the Swift Flight Form chain and drops a badge. The Shattered Hand Executioner in heroic Shattered Halls drops a badge when killed before the hostages are executed. Each is worth one badge per run on top of the dungeon's total." },
    { key = "stasis_quest", kind = "QUEST", title = "One-off: Stasis Chambers of the Mana-Tombs, 5 badges", optional = true, phases = { from = 1, to = 3 }, questId = 10977, questName = "Stasis Chambers of the Mana-Tombs",
      inside = { instance = 557, heroic = true },
      places = {
        {
          role = "start",
          name = "Image of Commander Ameer",
          npc = 22919,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 52.9,
          y = 15,
        },
        {
          role = "turnin",
          name = "Image of Commander Ameer",
          npc = 22919,
          zone = "Blade's Edge Mountains",
          map = 1949,
          x = 52.9,
          y = 15,
        },
        { role = "inside", name = "Mana-Tombs", instance = 557 },
      },
      detail = "The Ethereum Prison chain from Commander Ameer at the Protectorate Watch Post in Netherstorm (A Mission of Mercy, Ethereum Secrets, Ethereum Prisoner I.D. Catalogue, A Thousand Worlds, then Stasis Chambers of Bash'ir, Purging the Chambers of Bash'ir and The Mark of the Nexus-King at the Image of Commander Ameer at Bash'ir's Landing) ends in Stasis Chambers of the Mana-Tombs. Use the Mana-Tombs Stasis Chamber Key on the Mana-Tombs Stasis Chamber near the front of heroic Mana-Tombs, in the room after Pandemonius on the right; it releases the Consortium ethereal Ambassador Pax'ivi and no boss kill is needed. Turn in for 5 Badges of Justice and 500 Consortium reputation. Yor lives in Shaffar's personal chamber and is opened only with Shaffar's Stasis Chamber Key or The Eye of Haramad. A Thousand Worlds only becomes available at Consortium Revered. Ethereum Prison Keys from Mah'duun's normal daily and Netherstorm drops feed the chain. It is a one-time payout available from Phase 1." },
    { key = "no_new_sources", kind = "MANUAL", title = "Know what does not pay badges in Phase 2", optional = true, note = true, phases = { from = 2, to = 2 },
      detail = "Phase 2's new content pays no Badges of Justice: Ogri'la and Sha'tari Skyguard dailies reward Apexis Shards, gold and reputation; SSC and TK bosses drop no badges until Phase 4; arena and honour are separate currencies. The Shartuul's Transporter event (Ogri'la Honored, Blade's Edge) pays Ogri'la reputation and Depleted items only on this client; its three Badges of Justice were added in patch 3.0.2 and do not exist in TBC. Put spare time into heroics and bank badges for the Phase 4 catalogue (helms 50, legs and chests 75)." },
    { key = "bank_for_p4", kind = "MANUAL", title = "Bank badges for the Phase 4 catalogue", optional = true, note = true, phases = { from = 3, to = 3 },
      detail = "Phase 4 (Zul'Aman) makes every Karazhan, Gruul, Magtheridon, SSC, TK and Zul'Aman boss plus Kazzak and Doomwalker drop badges and gives G'eras the 2.3 and 2.4 Shattrath stock. The first purchases on day one of Phase 4 are the 75-badge legs and chests and the 50-badge helms, so a balance of 125 to 200 at the phase change turns straight into upgrades. There is no cap on Badges of Justice. If you still lack a 41-badge trinket or a 25-badge slot, buy it; otherwise hold." },
    { key = "karazhan", kind = "KILL", title = "Karazhan full clear: 22 badges", optional = false, weekly = true, phases = { from = 4, to = 5 },
      inside = {
        instance = 532,
        heroic = false,
        boss = "Prince Malchezaar",
        npcs = { 16152, 15687, 16457, 17521, 17533, 17534, 18168, 15691, 15688, 16524, 15689, 16816, 15690, 17225 },
        encounters = { 652, 653, 654, 655, 656, 657, 658, 659, 660, 661, 662 },
        last = true,
        full = true,
      },
      places = {
        { role = "inside", name = "Karazhan", instance = 532 },
      },
      detail = "From Phase 4 every Karazhan encounter drops Badges of Justice, Attumen the Huntsman 1, Prince Malchezaar 3 and the other nine 2 each: Attumen the Huntsman, Moroes, Maiden of Virtue, the Opera event (Big Bad Wolf, Romulo and Julianne, or the Wizard of Oz Crone), the Curator, Terestian Illhoof, Shade of Aran, Netherspite, the Chess event chest, Prince Malchezaar and Nightbane, eleven encounters for 22 badges a week. Nightbane needs the Blackened Urn summon. Karazhan is the best badge farm in the game: a Tier 6 group clears it in ninety minutes with no competition for loot. Weekly lockout, 10 players. Karazhan's gate needs one Master's Key holder in the raid, or a rogue or a blacksmith's skeleton key, in every phase; Phase 4 changed nothing about Karazhan access." },
    { key = "zulaman", kind = "KILL", title = "Zul'Aman full clear: 13 badges", optional = false, weekly = true, phases = { from = 4, to = 5 },
      inside = {
        instance = 568,
        heroic = false,
        boss = "Zul'jin",
        npcs = { 23576, 23574, 23578, 23577, 24239, 23863 },
        encounters = { 1189, 1190, 1191, 1192, 1193, 1194 },
        last = true,
        full = true,
      },
      places = {
        { role = "inside", name = "Zul'Aman", instance = 568 },
      },
      detail = "Nalorakk drops 1 badge, Akil'zon, Jan'alai and Halazzi 2 each, Hex Lord Malacrass 3 and Zul'jin 3, 13 in total. Zul'Aman is a 10-player raid in the Ghostlands with a 3-day lockout and no attunement, so a guild can run it twice in some weeks for 26 badges. The timed hostage run for the Amani War Bear is independent of badge drops." },
    { key = "za_quests", kind = "QUEST", title = "One-off Zul'Aman quests: 15 badges", optional = true, phases = { from = 4, to = 5 }, questId = 11171, questIds = { 11171, 11163 }, questMode = "ALL", questName = "Hex Lord? Hah! and Undercover Sister", related = { quests = { 11130, 11132, 11166, 11178 } },
      inside = { instance = 568, heroic = false, boss = "Hex Lord Malacrass and Zul'jin", npcs = { 24239, 23863 } },
      places = {
        {
          role = "start",
          name = "Budd Nedreck",
          npc = 23559,
          zone = "Ghostlands",
          map = 1942,
          x = 70.3,
          y = 67.8,
        },
        {
          role = "turnin",
          name = "Donna Brascoe",
          npc = 23858,
          zone = "Ghostlands",
          map = 1942,
          x = 70.5,
          y = 68.3,
        },
        { role = "inside", name = "Zul'Aman", instance = 568 },
      },
      detail = "Two quests at Budd's camp in Hatchet Hills outside Zul'Aman pay badges once. Hex Lord? Hah! from Budd Nedreck (70.3, 67.8) asks you to kill Hex Lord Malacrass and pays 5 Badges of Justice; it follows X Marks... Your Doom!, which follows Promises, Promises..., which follows Oooh, Shinies! (from Griftah in Shattrath, turned in to Budd). Undercover Sister from Donna Brascoe (70.5, 68.3) pays 10 Badges of Justice after you have turned in Blood of the Warlord, the Blood of Zul'jin that drops from Zul'jin and is handed to Budd. Both are one-time, so do them on your first full clear." },
    { key = "gruul_mag", kind = "KILL", title = "Gruul's Lair and Magtheridon's Lair: 8 badges", optional = true, weekly = true, phases = { from = 4, to = 5 },
      inside = {
        instance = 565,
        heroic = false,
        boss = "Gruul the Dragonkiller",
        npcs = { 18831, 19044, 17257 },
        encounters = { 650 },
        last = true,
      },
      places = {
        { role = "inside", name = "Gruul's Lair", instance = 565 },
      },
      detail = "High King Maulgar and Gruul the Dragonkiller drop 5 badges between them and Magtheridon in his lair drops 3. Both are 25-player weekly lockouts that a Tier 6 raid clears in half an hour each, so they are worth keeping on the calendar purely for badges and Tier 4 tokens for alts." },
    { key = "ssc_tk", kind = "KILL", title = "Serpentshrine Cavern and Tempest Keep: 20 badges", optional = true, weekly = true, phases = { from = 4, to = 5 },
      inside = {
        instance = 548,
        heroic = false,
        boss = "Lady Vashj",
        npcs = { 21216, 21217, 21215, 21214, 21213, 21212, 19514, 19516, 18805, 19622 },
        encounters = { 628 },
        last = true,
      },
      places = {
        { role = "inside", name = "Serpentshrine Cavern", instance = 548 },
      },
      detail = "Serpentshrine Cavern's six bosses (Hydross the Unstable, the Lurker Below, Leotheras the Blind, Fathom-Lord Karathress, Morogrim Tidewalker, Lady Vashj) drop 12 badges, 2 each, and Tempest Keep: The Eye's four (Al'ar, Void Reaver, High Astromancer Solarian, Kael'thas Sunstrider) drop 8. Both are weekly 25-player lockouts that lost their attunement at the start of Phase 3 (27 August 2026), when the direct skips to Lady Vashj and Kael'thas also opened; Phase 4 removed only the Hyjal and Black Temple attunements, so a Tier 6 guild can farm them for badges and Tier 5 tokens for newer raiders." },
    { key = "world_bosses", kind = "KILL", title = "Doom Lord Kazzak and Doomwalker: 2 badges each", optional = true, weekly = true, phases = { from = 4, to = 5 },
      inside = { instance = 530, heroic = false, boss = "Doom Lord Kazzak and Doomwalker", npcs = { 18728, 17711 } },
      places = {
        { role = "inside", name = "Outland", instance = 530 },
      },
      detail = "From Phase 4 Doom Lord Kazzak (Throne of Kil'jaeden, Hellfire Peninsula) and Doomwalker (outside the Black Temple, Shadowmoon Valley) drop Badges of Justice; loot data lists 2 per kill at a guaranteed rate. Their loot is bind-on-equip from Phase 4. Both are contested world spawns on a multi-day timer, so this is an opportunistic 4 badges rather than a weekly plan." },
    { key = "heroic_mgt", kind = "KILL", title = "Heroic Magisters' Terrace: 4 badges", optional = false, weekly = true, phases = { from = 5, to = 5 },
      inside = {
        instance = 585,
        heroic = true,
        boss = "Kael'thas Sunstrider",
        npcs = { 24723, 24744, 24560, 24664 },
        encounters = { 1894 },
        last = true,
      },
      places = {
        { role = "inside", name = "Magisters' Terrace", instance = 585 },
      },
      detail = "Heroic Magisters' Terrace on the Isle of Quel'Danas drops one badge from each of Selin Fireheart, Vexallus, Priestess Delrissa and Kael'thas Sunstrider, four per run, plus the heroic daily's 2 on days its Wanted quest names Magisters' Terrace. Normal mode drops no badges. Heroic Magisters' Terrace has no key: finishing the Hard to Kill chain opens it, not reputation. Kael'thas also drops the Phoenix Hatchling and the Swift White Hawkstrider on heroic." },
    { key = "hyjal_bt", kind = "KILL", title = "Mount Hyjal and Black Temple: 28 badges", optional = true, weekly = true, phases = { from = 5, to = 5 },
      inside = {
        instance = 564,
        heroic = false,
        boss = "Illidan Stormrage",
        npcs = { 17767, 17808, 17888, 17842, 17968, 22887, 22898, 22841, 22871, 22948, 23420, 22947, 22949, 22917 },
        encounters = { 609 },
        last = true,
      },
      places = {
        { role = "inside", name = "Black Temple", instance = 564 },
      },
      detail = "From Phase 5 the Tier 6 raids drop badges: Hyjal Summit (Rage Winterchill, Anetheron, Kaz'rogal, Azgalor, Archimonde) pays 10, 2 per boss, and Black Temple (High Warlord Naj'entus, Supremus, Shade of Akama, Teron Gorefiend, Gurtogg Bloodboil, Reliquary of Souls, Mother Shahraz, the Illidari Council, Illidan Stormrage) pays 18, 2 per boss. The 2.5.4 Classic notes explicitly left these two out of Phase 4, and the original 2.4 patch made every raid boss drop badges, which is why they are placed here; no attunement is needed from Phase 4." },
    { key = "sunwell", kind = "KILL", title = "Sunwell Plateau: 12 badges", optional = true, weekly = true, phases = { from = 5, to = 5 },
      inside = {
        instance = 580,
        heroic = false,
        boss = "Kil'jaeden",
        npcs = { 24850, 24882, 25038, 25166, 25165, 25741, 25315 },
        encounters = { 729 },
        last = true,
      },
      places = {
        { role = "inside", name = "Sunwell Plateau", instance = 580 },
      },
      detail = "Sunwell Plateau's six encounters (Kalecgos, Brutallus, Felmyst, the Eredar Twins Grand Warlock Alythess and Lady Sacrolash, M'uru, Kil'jaeden) drop 2 badges each and Kil'jaeden 3, 12 or 13 a week depending on the source. Every badge from Sunwell is a bonus on top of the best loot in the expansion; even a guild stuck on Brutallus banks 4 a week." },
    { key = "t5_and_below", kind = "KILL", title = "Gruul, Magtheridon, SSC, TK and the world bosses: 32 badges", optional = true, weekly = true, phases = { from = 4, to = 5 },
      inside = {
        instance = 548,
        heroic = false,
        boss = "Lady Vashj",
        npcs = { 18831, 19044, 17257, 21216, 21217, 21215, 21214, 21213, 21212, 19514, 19516, 18805, 19622, 18728, 17711 },
        encounters = { 628 },
        last = true,
      },
      places = {
        { role = "inside", name = "Serpentshrine Cavern", instance = 548 },
      },
      detail = "The Phase 4 sources keep paying: Gruul's Lair 5, Magtheridon's Lair 3, Serpentshrine Cavern 12, Tempest Keep 8 and Doom Lord Kazzak and Doomwalker 2 each. A Sunwell guild that still runs the Tier 4 and Tier 5 lockouts for alts and badges adds 28 a week plus the opportunistic 4 from world bosses." },
    { key = "sso_supplies", kind = "QUEST", title = "Isle dailies: a chance of a badge in Shattered Sun Supplies", optional = true, daily = true, phases = { from = 5, to = 5 }, questIds = { 11513, 11514, 11520, 11521, 11516, 11877 }, questMode = "ANY", questName = "Intercepting the Mana Cells, Maintaining the Sunwell Portal, Discovering Your Roots, Rediscovering Your Roots, Blast the Gateway, Sunfury Attack Plans",
      places = {
        {
          role = "start",
          name = "Exarch Nasuun",
          npc = 24932,
          zone = "Shattrath City",
          map = 1955,
          x = 49.1,
          y = 42.5,
        },
      },
      detail = "No Shattered Sun Offensive daily pays Badges of Justice directly; they pay gold and Shattered Sun Offensive reputation. A few of them reward a bag of Shattered Sun Supplies that holds a level 68 green and, by community reports from TBC Classic, roughly a 15 percent chance of a Badge of Justice. The bag comes from Intercepting the Mana Cells and its follow-up Maintaining the Sunwell Portal from Exarch Nasuun on the Terrace of Light, and Discovering Your Roots and Rediscovering Your Roots from Mar'nah at Sun's Reach Harbor once the harbour phase is open. Treat this as a few bonus badges a month, not a plan. Blast the Gateway (Magistrix Seyla at the Throne of Kil'jaeden in Hellfire Peninsula, after The Missing Magistrix) and Sunfury Attack Plans (Isle of Quel'Danas) also award Shattered Sun Supplies; The Multiphase Survey stopped awarding it in 2.4.2." },
    { key = "spend", kind = "MANUAL", title = "Spend: what to buy first this phase", optional = false, note = true, section = "SPEND", phases = { from = 1, to = false },
      detailByPhase = {
        [1] = "G'eras's Phase 1 catalogue is the 2.0 and 2.1 stock. Buy the 41-badge trinket for your role first (Icon of the Silver Crescent for casters, Bloodlust Brooch for melee and hunters, Essence of the Martyr for healers), because trinkets are the slots Karazhan fills worst. Next the 25-badge pieces that beat your pre-raid item: necklaces (Manasurge Pendant, Necklace of the Juggernaut, Choker of Vile Intent, Necklace of Eternal Hope), rings (Ring of Cryptic Dreams, Band of Halos, Ring of Arathi Warlords, Ring of Unyielding Force), cloaks (Bishop's Cloak, Blood Knight War Cloak, Farstrider Defender's Cloak) and off-hands (Talisman of Kalecgos, Orb of the Soul-Eater, Khadgar's Knapsack, Tears of Heaven, Sapphiron's Wing Bone, Flametongue Seal). Shields are 33 (Azure-Shield of Coldarra, Light-Bearer's Faith Shield, Mazthoril Honor Shield), Searing Sunblade 50 and Gnomeregan Auto-Blocker 600 41. Primal Nether is 10 badges; only buy it when a crafted epic is waiting on it. Fire resistance sets (20 per hands and feet, 30 per chest and legs) are not needed until Hyjal and Black Temple.",
        [2] = "The G'eras catalogue is still the launch stock, so the priorities are the same as Phase 1: the 41-badge role trinket (Icon of the Silver Crescent, Bloodlust Brooch, Essence of the Martyr) if you still lack it, then 25-badge necks, rings, cloaks and off-hands that beat your Karazhan drops, shields at 33, Searing Sunblade at 50. Primal Nether at 10 badges is now worth buying for the Phase 2 crafted epics if your guild's drops are slow. Once your 25 and 41 slots are done, stop spending and bank: Phase 4 brings 50-badge helms, 60-badge boots, belts, gloves and shoulders, 75-badge legs and chests and 15-badge Nether Vortex, and there is no badge cap.",
        [3] = "The catalogue is the launch stock until Phase 4. Fire resistance now matters: G'eras sells four Inferno sets (Infernoweave cloth, Inferno Hardened leather, Inferno Forged mail, Inferno Tempered plate) at 20 badges for gloves and boots and 30 for chest and legs; the Illidan Flames of Azzinoth tank and Hyjal trash soakers want them, everyone else does not. Beyond that the priorities are unchanged: 41-badge role trinkets, 25-badge necks, rings, cloaks and off-hands, 33-badge shields, 50-badge Searing Sunblade, 10-badge Primal Nether for Tier 6 era crafted items. Relics (Libram of Repentance, Totem of the Pulsing Earth, Everbloom Idol) are 15.",
        [4] = "G'eras now sells the 2.3 and 2.4 Shattrath catalogue. Buy in order of slot value: 75-badge legs (Shifting Camouflage Pants, Natural Life Leggings, Pantaloons of Arcane Annihilation, Achromic Trousers of the Naaru, High Justicar's Legplates, Unwavering Legguards, Bloodthirster's Wargreaves, Shallow-grave Trousers, Pants of Splendid Recovery, Blessed Elunite Coverings) and 75-badge chests (Chestguard of the Stoic Guardian, Hauberk of the Furious Elements, Vestments of Hibernation), then 50-badge helms (Cowl of Naaru Blessings, Mana-Binders Cowl, Warpstalker Helm, Storm Master's Helmet, Mask of the Deceiver, Cowl of Beastly Rage, Faceguard of Determination, Helmet of the Steadfast Champion), then 60-badge boots, belts, gloves and shoulders (Treads of the Life Path, Iron-tusk Girdle, Gauntlets of Sniping, Gnarled Ironwood Pauldrons and the rest), 35-badge bracers, 35-badge Brooch of Deftness and the 75-badge Battlemaster trinkets for PvP. Relics (Idol of Terror, Libram of Divine Purpose, Totem of Living Water, Skycall Totem and others) are 20. Nether Vortex at 15 badges unblocks Tier 6 era crafting and is no longer soulbound, so buying for guild crafters is sensible. Only buy from the launch stock (41 trinkets, 25 slots) where it still beats your raid gear.",
        [5] = "Smith Hauthaa on the Isle (and Anwehu in Shattrath) sell the Sunwell-tier badge gear once the realm has built the Anvil and Forge: chests and legs at 100 badges (Ecclesiastical Cuirass, Tunic of the Dark Hour, Scaled Drakeskin Chestguard, Breastplate of Ire, Shroud of the Lore'nial, Leggings of the Pursuit, Sunguard Legplates, Grovewalker's Leggings and the rest), belts, boots and gloves at 75 (Belt of the Silent Path, Boots of Incantations, Gauntlets of Rapidity, Blue's Greaves of the Righteous Guardian, Enslaved Doomguard Soulgrips), rings and necklaces at 60 (Angelista's Revenge, Ring of the Stalwart Protector, Fused Nethergon Band, Anveena's Touch) and weapons at 150 (The Blade of Harbingers, Crossbow of Relentless Strikes, Scryer's Blade of Focus, Gavel of Naaru Blessings, Staff of the Forest Lord), 105 (Vanir's Right Fist of Brutality, Blade of Serration) and 45 (Swift Blade of Uncertainty, Vanir's Left Fist of Savagery and Brutality, The Mutilator). Buy the 100-badge chest or legs that beats your Tier 6 piece first, then the 150-badge weapon if Sunwell is not dropping yours, then 75-badge slots. Kayri's Veteran's belts and boots (40) and bracers (25) cover PvP slots, and Shaani or Ontuvo sell uncut epic gems at 15 each, the best use of leftover badges once gear is done. G'eras's Phase 4 catalogue (75 legs and chests, 50 helms) remains the cheaper fill for alts.",
      } },
    { key = "talk_geras", kind = "TALK", title = "Find G'eras on the Terrace of Light", optional = false, note = true, section = "SPEND", phases = { from = 1, to = 5 },
      places = {
        {
          role = "vendor",
          name = "G'eras",
          npc = 18525,
          zone = "Shattrath City",
          map = 1955,
          x = 50.8,
          y = 42.3,
        },
      },
      detail = "G'eras is a naaru on the upper walkway of the Terrace of Light in Shattrath City (50.8, 42.3). He is the only badge vendor from Phase 1 to Phase 4. His launch stock is the 2.0 and 2.1 catalogue: trinkets at 41 badges (Icon of the Silver Crescent, Bloodlust Brooch, Essence of the Martyr), necklaces, rings, cloaks and off-hands at 25, shields at 33, Searing Sunblade at 50, class relics at 15, fire resistance pieces at 20 and 30, and Primal Nether at 10. In Phase 4 he adds the 2.3 and 2.4 Shattrath catalogue (helms 50, bracers 35, gloves, belts, boots and shoulders 60, legs and chests 75, Battlemaster trinkets 75, relics 20) and Nether Vortex at 15." },
    { key = "talk_zhareem", kind = "TALK", title = "Pick up the heroic daily from Wind Trader Zhareem", optional = false, note = true, section = "SPEND", phases = { from = 1, to = 5 },
      places = {
        {
          role = "vendor",
          name = "Wind Trader Zhareem",
          npc = 24369,
          zone = "Shattrath City",
          map = 1955,
          x = 75.1,
          y = 36.7,
        },
      },
      detail = "Wind Trader Zhareem stands in the Lower City outside the World's End Tavern (75.1, 36.7), beside Nether-Stalker Mah'duun. He offers one random Wanted quest per day that must be completed on Heroic difficulty and pays 2 Badges of Justice plus about 13 to 25 gold and 350 reputation with the Consortium and the dungeon's faction. On the Anniversary realms the daily is available from Phase 1 (TBC Classic had it at launch too). The pool is 15 quests, one per heroic dungeon, and gains Magisters' Terrace in Phase 5. You cannot hold two Wanted quests at once and the quest resets at the daily reset." },
    { key = "talk_mahduun", kind = "TALK", title = "Know that Mah'duun's normal daily pays no badges", optional = true, note = true, section = "SPEND", phases = { from = 1, to = 5 },
      places = {
        {
          role = "vendor",
          name = "Nether-Stalker Mah'duun",
          npc = 24370,
          zone = "Shattrath City",
          map = 1955,
          x = 75.5,
          y = 37.2,
        },
      },
      detail = "Nether-Stalker Mah'duun stands next to Zhareem (75.5, 37.2) and offers the non-heroic daily: kill a handful of named trash mobs in one of eight dungeons, nine from Phase 5. The reward is one Ethereum Prison Key, about 16 gold and 250 reputation with the Consortium and the dungeon's faction; it never pays Badges of Justice. It is still worth doing on the way to a heroic because the key opens Ethereum Prisons in Netherstorm and feeds the Mana-Tombs stasis chain that pays 5 badges once." },
    { key = "talk_hauthaa", kind = "TALK", title = "Buy Sunwell-tier badge gear from Smith Hauthaa", optional = false, note = true, section = "SPEND", phases = { from = 5, to = 5 },
      places = {
        {
          role = "vendor",
          name = "Smith Hauthaa",
          npc = 25046,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 50.6,
          y = 40.8,
        },
      },
      detail = "Smith Hauthaa stands at her anvil behind the Sun's Reach Armory on the Isle of Quel'Danas (50.6, 40.8). She is a Phase 5 vendor and is gated by the realm-wide Shattered Sun Offensive effort: she appears once the Sun's Reach Armory has been retaken and only starts selling once the Anvil and Forge behind the armory has been built by the realm completing the daily Making Ready, after which the follow-up daily Don't Stop Now.... keeps it running. Her catalogue is the 2.4 badge gear: chests and legs at 100 badges, belts, boots and gloves at 75, rings and necklaces at 60, two-handers and main weapons at 150, one-handers at 105 and off-hand weapons at 45. Anwehu in Shattrath mirrors her stock under the same gate." },
    { key = "talk_anwehu", kind = "TALK", title = "Use Anwehu in Shattrath as Hauthaa's mirror", optional = true, note = true, section = "SPEND", phases = { from = 5, to = 5 },
      places = {
        {
          role = "vendor",
          name = "Anwehu",
          npc = 27667,
          zone = "Shattrath City",
          map = 1955,
          x = 48.1,
          y = 42.9,
        },
      },
      detail = "Anwehu (added in patch 2.4.2) stands on the Terrace of Light behind Exarch Nasuun and the Shattrath portal to the Isle (48.1, 42.9). He sells exactly Smith Hauthaa's badge gear at the same prices and obeys the same gate: no sales until the realm has built the Anvil and Forge through Making Ready. Handy when you are already in Shattrath turning in the heroic daily. Ontuvo (48.6, 40.9) next to him mirrors Shaani's epic gems at 15 badges each." },
    { key = "talk_kayri", kind = "TALK", title = "Trade badges for Veteran's PvP pieces at Kayri", optional = true, note = true, section = "SPEND", phases = { from = 5, to = 5 },
      places = {
        {
          role = "vendor",
          name = "Kayri",
          npc = 26089,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 50.2,
          y = 39.8,
        },
      },
      detail = "Kayri, Exotic Gear Purveyor, stands by the Sun's Reach Armory (50.2, 39.8) and sells Veteran's (Season 2) belts and boots for 40 badges and bracers for 25 badges, the PvP waist, wrist and feet slots that are otherwise honour purchases. She appears as soon as the realm retakes the Sun's Reach Armory, the same moment Smith Hauthaa and Anwehu appear; retaking the Harbor is not required. Good value for arena players who would rather spend badges than honour on these three slots." },
    { key = "talk_shaani", kind = "TALK", title = "Buy uncut epic gems from Shaani for 15 badges", optional = true, note = true, section = "SPEND", phases = { from = 5, to = 5 },
      places = {
        {
          role = "vendor",
          name = "Shaani",
          npc = 25950,
          zone = "Isle of Quel'Danas",
          map = 1957,
          x = 51.5,
          y = 32.5,
        },
      },
      detail = "Shaani, Jewelcrafting Supplies, stands near the Sun's Reach Sanctum (51.5, 32.5) and sells uncut epic gems (Crimson Spinel, Empyrean Sapphire, Lionseye, Shadowsong Amethyst, Pyrestone, Seaspray Emerald) for 15 badges each. She begins selling once the realm has retaken Sun's Reach Harbor and activated the Alchemy Lab. Ontuvo in Shattrath mirrors her stock. This is the cheapest reliable epic-gem source once badge gear is finished." },
  },
}
end
